function(template, values, blocks = .multilpa_accelerated_blocks()) {
    position <- 0L
    fill <- function(block) {
        if (is.list(block)) 
            return(lapply(block, fill))
        size <- length(block)
        block[] <- values[position + seq_len(size)]
        position <<- position + size
        block
    }
    names_present <- intersect(blocks, names(template))
    template[names_present] <- lapply(template[names_present], fill)
    stopifnot(`the flat vector must match the template's size` = position == length(values))
    template
}

