before.definition_AST:
function(parameters) {
    probabilities <- unlist(parameters[c("profile_probabilities", "group_probabilities", "initial_probabilities", "transition_probabilities", "response_probabilities")], use.names = FALSE)
    if (any(!is.finite(probabilities)) || any(probabilities <= 0) || any(probabilities > 1 + 1e-12)) {
        return(FALSE)
    }
    normalized <- function(totals) all(is.finite(totals) & abs(totals - 1) <= 1e-08)
    if (!is.null(parameters$profile_probabilities) && !normalized(rowSums(parameters$profile_probabilities))) 
        return(FALSE)
    if (!is.null(parameters$response_probabilities) && !all(vapply(parameters$response_probabilities, function(block) {
        normalized(rowSums(block))
    }, logical(1)))) 
        return(FALSE)
    if (!is.null(parameters$initial_probabilities) && !normalized(rowSums(parameters$initial_probabilities))) 
        return(FALSE)
    if (!is.null(parameters$transition_probabilities) && !normalized(apply(parameters$transition_probabilities, c(1L, 3L), sum))) {
        return(FALSE)
    }
    if (!is.null(parameters$group_probabilities) && !normalized(sum(parameters$group_probabilities))) 
        return(FALSE)
    if (length(c(parameters$count_means, parameters$count_dispersion)) > 0L && (any(!is.finite(c(parameters$count_means, parameters$count_dispersion))) || any(c(parameters$count_means, parameters$count_dispersion) <= 0))) {
        return(FALSE)
    }
    if (length(parameters$variances) > 0L && (any(!is.finite(parameters$variances)) || any(parameters$variances <= 0))) {
        return(FALSE)
    }
    covariances <- parameters$covariances
    if (is.null(covariances)) 
        return(TRUE)
    all(vapply(seq_len(dim(covariances)[3L]), function(profile) {
        block <- matrix(covariances[, , profile], dim(covariances)[1L])
        all(is.finite(block)) && !inherits(tryCatch(chol(block), error = function(error) error), "error")
    }, logical(1)))
}

