function(x, data = NULL, scale = c("raw", "standardized"), standard_errors = !is.null(data)) {
    scale <- match.arg(scale)
    vars <- .multilpa_continuous_names(x)
    n_profiles <- x$n_profiles
    basis <- if (identical(scale, "standardized") && length(vars) > 0L) {
        .multilpa_standardization(x, vars)
    }
    else {
        list(centre = rep(0, length(vars)), spread = rep(1, length(vars)))
    }
    means <- sweep(sweep(x$means, 2L, basis$centre, "-"), 2L, basis$spread, "/")
    variances <- sweep(x$variances, 2L, basis$spread^2, "/")
    frame <- data.frame(profile = rep(seq_len(n_profiles), each = length(vars)), indicator = rep(vars, times = n_profiles), mean = as.vector(t(means)), variance = as.vector(t(variances)), standard_deviation = sqrt(as.vector(t(variances))))
    if (!isTRUE(standard_errors)) 
        return(frame)
    if (nrow(frame) == 0L) {
        frame$mean_standard_error <- numeric()
        frame$variance_standard_error <- numeric()
        return(frame)
    }
    errors <- .multilpa_table_errors(x, data)
    if (is.null(errors)) {
        frame$mean_standard_error <- NA_real_
        frame$variance_standard_error <- NA_real_
        return(frame)
    }
    row_spread <- rep(basis$spread, times = n_profiles)
    frame$mean_standard_error <- .multilpa_match_error(errors, "mean", frame$profile, frame$indicator)/row_spread
    frame$variance_standard_error <- .multilpa_variance_error(errors, frame$profile, frame$indicator)/row_spread^2
    frame
}

