starting_values <- function(x, covariance = c("auto", "drop", "keep"),
                            what = c("all", "measurement")) {
  stopifnot("`x` must be a list or a `multilpa` fit" = is.list(x))
  .multilpa_refuse_noise(x, "starting_values()")
