function(x, vcov_type = c("observed", "robust", "opg"), step = 1e-04, warn_weak = TRUE) {
    vcov_type <- match.arg(vcov_type)
    stopifnot(`\`step\` must be finite and positive` = is.numeric(step) && length(step) == 1L && is.finite(step) && step > 0)
    if (!isTRUE(x$converged)) {
        stop(errorCondition("Inference requires a converged fit.", class = "latents_no_converge", call = NULL))
    }
    if (any(x$between_zero) || any(x$within_floor)) {
        stop(errorCondition(paste("A between-group variance is estimated at zero or a within-group variance", "sits at min_variance; the parameter is on the edge of its space and Wald", "inference does not apply."), class = "latents_boundary_fit", call = NULL))
    }
    if (any(x$group_probabilities <= 1e-06) || isTRUE(x$small_classes)) {
        stop(errorCondition("A group class has (nearly) no membership, so its parameters are not identified.", class = "latents_boundary_fit", call = NULL))
    }
    stats <- x$sufficient_statistics
    class_names <- names(x$group_probabilities)
    parameters <- list(means = unname(x$means), between = unname(x$between_variances), within = unname(x$within_variances), weights = unname(x$group_probabilities))
    theta <- .additive_pack(parameters, x$structure, class_names, x$vars)
    scores <- .additive_group_scores(stats, parameters, x$structure, class_names, x$vars)
    information <- .additive_information(stats, theta, x$structure, class_names, x$vars, step)
    inverse <- .inference_invert(information, "ratio_le_eps")
    eigenvalues <- eigen(information, symmetric = TRUE, only.values = TRUE)$values
    condition_ratio <- min(eigenvalues)/max(eigenvalues)
    dimnames(inverse) <- dimnames(information)
    gradient <- colSums(scores)
    scaled_score <- sqrt(max(0, drop(crossprod(gradient, inverse %*% gradient))))
    if (scaled_score > 0.01) {
        warning(warningCondition(sprintf(paste("The score at the estimate is not near zero (scaled %.3g); the fit may", "not be at a maximum. Refit with a smaller `tol`."), scaled_score), class = "latents_unconverged", call = NULL))
    }
    if (vcov_type != "observed") {
        .multilpa_require_clusters(sum((x$sampling_weights %||% rep(1, nrow(scores))) > 0), ncol(scores), "A robust or OPG additive covariance")
        .inference_require_rank(scores, paste("The %d group scores span %d of %d dimensions, too few to form a", "%s covariance."), formatted = TRUE, extra = list(vcov_type))
    }
    meat <- crossprod(scores)
    covariance <- switch(vcov_type, observed = inverse, robust = .inference_sandwich(inverse, meat, sum((x$sampling_weights %||% rep(1, nrow(scores))) > 0)), opg = chol2inv(chol(meat)))
    dimnames(covariance) <- dimnames(information)
    inference <- list(theta = theta, vcov = covariance, information = information, gradient = gradient, group_scores = scores, scaled_score = scaled_score, condition_ratio = condition_ratio, vcov_type = vcov_type)
    if (isTRUE(warn_weak)) 
        .additive_warn_weak(x, inference)
    inference
}

