function(x, data, truth) {
    if (is.null(data) || is.null(truth)) {
        stop(errorCondition("The `recovery` table needs `data` and `truth`.", class = "latents_bad_argument", call = NULL))
    }
    if (!is.character(truth) || length(truth) != 1L || !truth %in% names(data)) {
        stop(errorCondition("`truth` must name one column of `data`.", class = "latents_bad_argument", call = NULL))
    }
    supplied <- .additive_prepare(data, x$vars, x$id)
    if (!identical(supplied$ids, x$sufficient_statistics$ids) || !identical(supplied$sizes, x$sufficient_statistics$sizes)) {
        stop(errorCondition("`data` does not have the groups this fit was made from.", class = "latents_bad_inference_data", call = NULL))
    }
    values <- data[[truth]]
    per_group <- tapply(as.character(values), supplied$index, function(v) length(unique(v)))
    if (anyNA(values) || any(per_group != 1L)) {
        stop(errorCondition(sprintf("`%s` must be complete and constant within each group: group classes are group-level.", truth), class = "latents_bad_data", call = NULL))
    }
    group_truth <- as.character(values)[match(seq_len(supplied$n_groups), supplied$index)]
    assigned <- names(x$group_probabilities)[x$group_assignments]
    counts <- as.data.frame(table(assigned = assigned, truth = group_truth), stringsAsFactors = FALSE, responseName = "n")
    counts$share <- counts$n/as.vector(table(assigned)[counts$assigned])
    counts <- counts[order(counts$assigned, counts$truth), , drop = FALSE]
    rownames(counts) <- NULL
    counts
}

