function(x, what = c("means", "variances", "intercepts"), level = 0.95, main = NULL, subtitle = NULL, ...) {
    .latents_warn_unused_arguments(list(...), "plot()", "Style the returned plot with ggplot2, for example `+ ggplot2::theme()`.")
    what <- match.arg(what)
    .gg_require()
    key <- .additive_key(x)
    table <- withCallingHandlers(.additive_table(x, "parameters", level, .additive_default_vcov(x)), latents_no_standard_errors = function(condition) {
        invokeRestart("muffleMessage")
    })
    has_errors <- any(is.finite(table$standard_error))
    caption <- if (has_errors) {
        sprintf("Bars: %.0f%% Wald intervals.", 100 * level)
    }
    else "No intervals: inference is not available for this fit."
    switch(what, means = {
        frame <- subset(table, parameter == "mean")
        frame$label <- key$label[match(frame$group_class, key$group_class)]
        frame$label <- droplevels(frame$label)
        key <- subset(key, label %in% levels(frame$label))
        key$label <- droplevels(key$label)
        frame$indicator <- factor(frame$indicator, levels = x$vars)
        plot <- ggplot2::ggplot(frame, ggplot2::aes(x = indicator, y = estimate, colour = label, fill = label, shape = label, group = label)) + ggplot2::geom_line(linewidth = 0.6, alpha = 0.7) + ggplot2::geom_point(size = 3, colour = "grey20")
        if (has_errors) {
            plot <- plot + ggplot2::geom_errorbar(ggplot2::aes(ymin = conf_low, ymax = conf_high), width = 0.12)
        }
        plot + .gg_scales(data.frame(label = key$label, colour = key$colour, shape = key$shape), legend = TRUE) + .gg_theme() + .gg_top_legend() + ggplot2::labs(x = NULL, y = "Group-class mean") + .gg_titles(main, subtitle, "Group-class means", "Means of the group intercepts in each class", caption)
    }, variances = {
        frame <- subset(table, parameter == "variance")
        frame$label <- key$label[match(frame$group_class, key$group_class)]
        frame$label <- droplevels(frame$label)
        key <- subset(key, label %in% levels(frame$label))
        key$label <- droplevels(key$label)
        frame$panel <- factor(ifelse(frame$level == "within", "Within groups", "Between groups"), levels = c("Within groups", "Between groups"))
        frame$indicator <- factor(frame$indicator, levels = x$vars)
        dodge <- ggplot2::position_dodge(width = 0.5)
        plot <- ggplot2::ggplot(frame, ggplot2::aes(x = indicator, y = estimate, colour = label, fill = label, shape = label, group = label)) + ggplot2::geom_point(size = 3, colour = "grey20", position = dodge)
        if (has_errors) {
            plot <- plot + ggplot2::geom_errorbar(ggplot2::aes(ymin = conf_low, ymax = conf_high), width = 0.15, position = dodge)
        }
        plot + ggplot2::facet_wrap(ggplot2::vars(panel), scales = "free_y") + .gg_scales(data.frame(label = key$label, colour = key$colour, shape = key$shape), aesthetics = c(if (has_errors) "colour", "fill", "shape"), legend = TRUE) + ggplot2::expand_limits(y = 0) + .gg_theme() + .gg_top_legend() + ggplot2::labs(x = NULL, y = "Variance") + .gg_titles(main, subtitle, "Within- and between-group variances", sprintf("%s family", .additive_family_label(x$family)), caption)
    }, intercepts = {
        frame <- .additive_table(x, "intercepts")
        groups <- .additive_table(x, "groups")
        frame$group_class <- groups$group_class[match(frame[[x$id]], groups[[x$id]])]
        frame$label <- key$label[match(frame$group_class, key$group_class)]
        frame$indicator <- factor(frame$indicator, levels = x$vars)
        n_classes <- length(x$group_probabilities)
        key <- subset(key, group_class != "shared")
        key$label <- droplevels(key$label)
        frame$offset_x <- as.integer(frame$indicator) + (match(frame$group_class, key$group_class) - (n_classes + 1)/2) * 0.18
        means <- subset(table, parameter == "mean")
        if (identical(x$structure$means, "equal")) {
            means <- do.call(rbind, lapply(names(x$group_probabilities), function(h) {
                transform(means, group_class = h)
            }))
        }
        means$label <- key$label[match(means$group_class, key$group_class)]
        means$offset_x <- match(means$indicator, x$vars) + (match(means$group_class, key$group_class) - (n_classes + 1)/2) * 0.18
        ggplot2::ggplot(frame, ggplot2::aes(x = offset_x, y = intercept_mean, colour = label, fill = label, shape = label)) + ggplot2::geom_point(size = 1.6, alpha = 0.55, stroke = 0.3) + ggplot2::geom_point(data = means, ggplot2::aes(y = estimate), size = 4, colour = "grey10", stroke = 0.8) + ggplot2::scale_x_continuous(breaks = seq_along(x$vars), labels = x$vars) + .gg_scales(data.frame(label = key$label, colour = key$colour, shape = key$shape), legend = TRUE) + .gg_theme() + .gg_top_legend() + 
            ggplot2::labs(x = NULL, y = "Posterior group intercept") + .gg_titles(main, subtitle, "Group intercepts by modal group class", "Small marks: groups; large marks: class means", NULL)
    })
}

