function(x, data = NULL, by = c("profile", "overall"), adjust = .multilpa_p_adjust_methods) {
    stopifnot(`\`x\` must be a fitted model of this package` = .multilpa_any_fit(x))
    .multilpa_refuse_noise(x, "Bivariate residuals")
    data <- .multilpa_resolve_data(x, data)
    stopifnot(`\`data\` must be a data frame` = is.data.frame(data))
    .multilpa_check_row_count(x, data)
    by <- match.arg(by)
    adjust <- match.arg(adjust)
    continuous <- .multilpa_continuous_names(x)
    categorical <- x$categorical %||% character()
    stopifnot(`\`data\` must contain the fitted indicators` = all(c(continuous, categorical) %in% names(data)))
    stopifnot(`Gaussian indicators must be numeric and finite when observed` = all(vapply(data[continuous], function(value) is.numeric(value) && all(is.na(value) | is.finite(value)), logical(1))))
    .multilpa_check_alignment(x, data)
    weights <- if (identical(by, "profile")) {
        stats::setNames(lapply(seq_len(x$n_profiles), function(k) x$subject_posteriors[, k]), paste0("profile_", seq_len(x$n_profiles)))
    }
    else list(overall = rep(1, x$n_observations))
    sampling <- .multilpa_level_weights(x, "individuals", x$n_observations)
    if (!is.null(sampling)) 
        weights <- lapply(weights, `*`, sampling)
    rows <- lapply(names(weights), function(label) {
        weight <- weights[[label]]
        rbind(.multilpa_gaussian_residuals(x, data, continuous, weight, label, by), .multilpa_categorical_residuals(x, data, categorical, weight, label))
    })
    result <- do.call(rbind, rows)
    if (is.null(result) || nrow(result) == 0L) {
        return(data.frame(profile = character(), indicator_1 = character(), indicator_2 = character(), kind = character(), observed = numeric(), expected = numeric(), residual = numeric(), effective_n = numeric(), statistic = numeric(), df = integer(), p_value = numeric(), p_adjusted = numeric()))
    }
    result <- result[order(-abs(result$residual), result$indicator_1, result$indicator_2, result$profile), , drop = FALSE]
    result$p_adjusted <- stats::p.adjust(result$p_value, method = adjust)
    row.names(result) <- NULL
    result
}

