function(counts) {
    stopifnot(`\`counts\` must be a numeric matrix` = is.matrix(counts) && is.numeric(counts))
    total <- sum(counts)
    smaller <- min(nrow(counts), ncol(counts)) - 1L
    if (!is.finite(total) || total <= 0 || smaller < 1L) 
        return(NA_real_)
    independent <- outer(rowSums(counts), colSums(counts))/total
    positive <- independent > 0
    chi_square <- sum((counts[positive] - independent[positive])^2/independent[positive])
    sqrt(chi_square/(total * smaller))
}

