function(object, data, continuous, weight, label, by) {
    if (length(continuous) < 2L) 
        return(NULL)
    x <- .latents_direct_shift(.multilpa_center_like(object, as.matrix(data[continuous])), object$extra_data, object)
    sampling <- .multilpa_level_weights(object, "individuals", object$n_observations)
    pairs <- utils::combn(seq_along(continuous), 2L)
    profiles <- if (identical(by, "profile")) 
        as.integer(sub("^profile_", "", label))
    else seq_len(object$n_profiles)
    rows <- lapply(seq_len(ncol(pairs)), function(index) {
        pair <- pairs[, index]
        observed_rows <- stats::complete.cases(x[, pair, drop = FALSE])
        effective <- sum(weight[observed_rows])
        moments <- lapply(profiles, function(profile) {
            profile_weight <- object$subject_posteriors[observed_rows, profile]
            if (!is.null(sampling)) 
                profile_weight <- profile_weight * sampling[observed_rows]
            residual <- sweep(x[observed_rows, pair, drop = FALSE], 2L, object$means[profile, pair], "-")
            covariance <- if (identical(object$covariance_model, "full")) 
                matrix(object$covariances[pair, pair, profile], 2L)
            else diag(object$variances[profile, pair], 2L)
            list(observed = crossprod(residual * profile_weight, residual), expected = covariance * sum(profile_weight))
        })
        observed_covariance <- Reduce(`+`, lapply(moments, `[[`, "observed"))
        expected_covariance <- Reduce(`+`, lapply(moments, `[[`, "expected"))
        observed <- if (all(diag(observed_covariance) > 0)) 
            observed_covariance[1L, 2L]/sqrt(prod(diag(observed_covariance)))
        else NA_real_
        expected <- if (all(diag(expected_covariance) > 0)) 
            expected_covariance[1L, 2L]/sqrt(prod(diag(expected_covariance)))
        else NA_real_
        statistic <- if (is.null(sampling) && effective > 3 && is.finite(observed) && is.finite(expected)) {
            (atanh(pmin(pmax(observed, -0.999999), 0.999999)) - atanh(pmin(pmax(expected, -0.999999), 0.999999))) * sqrt(effective - 3)
        }
        else NA_real_
        data.frame(profile = label, indicator_1 = continuous[pair[1L]], indicator_2 = continuous[pair[2L]], kind = "gaussian", observed = observed, expected = expected, residual = observed - expected, effective_n = effective, statistic = statistic, df = NA_integer_, p_value = 2 * stats::pnorm(-abs(statistic)), row.names = NULL, stringsAsFactors = FALSE)
    })
    do.call(rbind, rows)
}

