function(x, data, level, iter, n_starts, max_iter, tol, adjust) {
    staged <- isTRUE(x$staged)
    if (length(x$fixed %||% character()) > 0L && !staged) {
        stop(errorCondition(paste("A fit that holds a block fixed cannot be bootstrapped here: the held", "values came from another fit, and resampling these data does not", "resample them. Bootstrap the fit the measurement came from, or fit", "both stages with fit_staged(), whose bootstrap refits each stage."), class = "latents_unsupported_inference", call = NULL))
    }
    if (!isTRUE(x$converged)) {
        stop(errorCondition("The original fit did not converge; bootstrap it only once it has.", class = "latents_no_converge", call = NULL))
    }
    free_natural <- if (staged) 
        seq_along(.multilpa_coefficients(x, "natural"))
    else .multilpa_free_index(x, "natural")
    drawn <- .multilpa_bootstrap_replicates(x, data, iter, n_starts, max_iter, tol)
    estimates <- drawn$estimates[, free_natural, drop = FALSE]
    valid <- stats::complete.cases(estimates)
    if (sum(valid) < 2L) {
        reasons <- drawn$messages[!is.na(drawn$messages)]
        stop(errorCondition(sprintf("Only %d of %d resamples produced a usable fit; the first reason was: %s", sum(valid), iter, if (length(reasons) > 0L) 
            reasons[1L]
        else "no reason was recorded"), class = "latents_bootstrap_failed", call = NULL))
    }
    kept <- estimates[valid, , drop = FALSE]
    if (sum(valid) < iter) {
        warning(warningCondition(sprintf("%d of %d resamples did not produce a usable fit and were dropped.", iter - sum(valid), iter), class = "latents_bootstrap_dropped", call = NULL))
    }
    bounds <- c((1 - level)/2, (1 + level)/2)
    quantiles <- apply(kept, 2L, stats::quantile, probs = bounds, names = FALSE)
    point <- .multilpa_coefficients(x, "natural")[free_natural]
    result <- data.frame(.multilpa_coefficient_labels(x, "natural")[free_natural, , drop = FALSE], estimate = unname(point), standard_error = apply(kept, 2L, stats::sd), statistic = NA_real_, p_value = NA_real_, conf_low = unname(quantiles[1L, ]), conf_high = unname(quantiles[2L, ]), row.names = NULL, stringsAsFactors = FALSE)
    result <- .multilpa_adjust_p(result, adjust)
    covariance <- stats::cov(kept)
    dimnames(covariance) <- list(names(point), names(point))
    attributes(result) <- c(attributes(result), list(covariance = covariance, covariance_unconstrained = NULL, level = level, method = "bootstrap", iter = iter, n_valid = sum(valid), replicates = kept, messages = drawn$messages, structure = x$covariance_structure, fixed = x$fixed %||% character(), stages_resampled = if (staged) 2L else 1L))
    result
}

