function(table, what, criterion) {
    if (identical(what, "candidates")) 
        return(table)
    usable <- which(is.finite(table[[criterion]]) & table$converged %in% TRUE)
    if (length(usable) == 0L) {
        if (identical(what, "all")) 
            return(list(candidates = table))
        stop(errorCondition("No candidate was fitted and converged, so no criterion has a minimum.", class = "latents_failed_candidate", call = NULL))
    }
    minimum <- table[usable[which.min(table[[criterion]][usable])], , drop = FALSE]
    if (identical(what, "all")) 
        return(list(candidates = table, best = minimum))
    minimum
}

