function(value, indicator, min_categories = 2L) {
    if (!(is.factor(value) || is.numeric(value) || is.logical(value) || is.character(value))) {
        stop(errorCondition(sprintf("Categorical indicator `%s` must be numeric, logical, character or a factor.", indicator), class = "latents_bad_categorical", call = NULL))
    }
    if (!is.null(dim(value))) {
        stop(errorCondition(sprintf("Categorical indicator `%s` must be a vector.", indicator), class = "latents_bad_categorical", call = NULL))
    }
    if (is.numeric(value) && any(!is.finite(value[!is.na(value)]))) {
        stop(errorCondition(sprintf("Categorical indicator `%s` contains non-finite values.", indicator), class = "latents_bad_categorical", call = NULL))
    }
    levels_observed <- if (is.factor(value)) {
        if (length(attr(value, "latents_pair", exact = TRUE)) == 2L) 
            levels(value)
        else levels(droplevels(value))
    }
    else sort(unique(value[!is.na(value)]))
    if (length(levels_observed) < min_categories) {
        stop(errorCondition(sprintf("Categorical indicator `%s` has fewer than two observed categories.", indicator), class = "latents_bad_categorical", call = NULL))
    }
    labels <- as.character(levels_observed)
    if (anyDuplicated(labels) > 0L) {
        stop(errorCondition(sprintf(paste("Categorical indicator `%s` has distinct values that print alike (%s);", "round the column so that each category has its own label."), indicator, paste(sprintf("\"%s\"", unique(labels[duplicated(labels)])), collapse = ", ")), class = "latents_bad_categorical", call = NULL))
    }
    levels_observed
}

