    expressions <- vapply(as.list(substitute(list(...)))[-1L], deparse1, character(1))
    labels <- names(fits) %||% rep("", length(fits))
    labels[!nzchar(labels)] <- expressions[!nzchar(labels)]
    if (length(fits) >= 1L && inherits(fits[[1L]], "latents_family_enumeration")) {
        stop(errorCondition(paste("Group-class family grids are compared in their own table:", "as.data.frame(grid)."), class = "latents_bad_argument", call = NULL))
    }
    if (length(fits) >= 1L && .latents_is_grid(fits[[1L]])) {
        return(.multilpa_compare_candidates(fits[[1L]], fits[-1L], labels[-1L], n_profiles, n_group_classes, cutoff))
    }
    if (!is.null(n_profiles) || !is.null(n_group_classes)) {
        stop(errorCondition(paste("`n_profiles` and `n_group_classes` select candidates of an enumeration", "grid; pass the grid first."), class = "latents_bad_argument", call = NULL))
    }
    if (length(fits) >= 1L && all(vapply(fits, .latents_comparison_measurement_fit, logical(1)))) {
        return(.multilpa_compare_fits(fits, labels, cutoff))
    }
    supported <- vapply(fits, function(fit) {
        inherits(fit, "latents_mixture_regression") || inherits(fit, "latents_growth_mixture")
    }, logical(1))
    if (length(fits) < 2L || !all(supported)) {
        stop(errorCondition(paste("`compare_models()` takes an enumeration grid and two or more candidate", "keys, or two or more fits of one kind: from multilpa(), lpa(), lca() or", "get_candidate(), or from mixture_regression()."), class = "latents_bad_argument", call = NULL))
    }
    if (anyDuplicated(labels)) {
        stop(errorCondition("Every model needs a distinct name.", class = "latents_bad_argument", call = NULL))
    }
    signature <- function(fit) {
        spec <- fit$spec
        list(y = spec$y, trials = spec$trials, family = spec$family, categories = spec$category_levels, groups = spec$group_index, group_levels = spec$group_levels, clusters = spec$cluster_index, cluster_levels = spec$cluster_levels, weights = spec$sampling_weights, rows = spec$kept_rows, response = spec$response_name)
    }
    reference <- signature(fits[[1L]])
    same <- vapply(fits, function(fit) .latents_same_comparison_data(signature(fit), reference), logical(1))
    if (!all(same)) {
        stop(errorCondition(sprintf(paste("%s %s fitted to different data from %s: information criteria compare", "models only on the same outcome and observations."), paste(labels[!same], collapse = ", "), if (sum(!same) > 1L) 
            "are"
        else "is", labels[1L]), class = "latents_incomparable_models", call = NULL))
    }
    rows <- lapply(seq_along(fits), function(i) {
        fit_row <- get_results(fits[[i]], "fit")
        data.frame(model = labels[i], n_classes = as.integer(fit_row$n_classes), random = .growth_random_description(fits[[i]]$spec), n_parameters = as.integer(fit_row$n_parameters), log_likelihood = fit_row$log_likelihood, aic = fit_row$aic, bic = fit_row$bic, sabic = fit_row$sabic, icl = fit_row$icl, entropy = fit_row$entropy, smallest_share = fit_row$smallest_share, converged = isTRUE(fit_row$converged), stringsAsFactors = FALSE)
    })
    table <- do.call(rbind, rows)
    table$delta_bic <- table$bic - min(table$bic)
    relative <- exp(-table$delta_bic/2)
    table$bic_weight <- relative/sum(relative)
    table <- table[c("model", "n_classes", "random", "n_parameters", "log_likelihood", "aic", "bic", "sabic", "icl", "entropy", "smallest_share", "delta_bic", "bic_weight", "converged")]
    column <- .latents_column
    table <- .latents_table(table, title = "Model comparison", display = list(column("Model", "model", "text"), column("Classes", "n_classes", "integer"), column("Random", "random", "text"), column("k", "n_parameters", "integer"), column("LogLik", "log_likelihood"), column("BIC", "bic"), column(if (isTRUE(l10n_info()$`UTF-8`)) "ΔBIC" else "dBIC", "delta_bic"), column("Weight", "bic_weight", "share"), column("Entropy", "entropy")))
    attr(table, "models") <- stats::setNames(fits, labels)
    class(table) <- c("latents_comparison", class(table))
    table
}

