function(grid, chosen, labels, n_profiles, n_group_classes, cutoff) {
    names <- .latents_candidate_names(grid)
    table <- .subset2(grid, "table")
    if (length(chosen) > 0L) {
        if (!is.null(n_profiles) || !is.null(n_group_classes)) {
            stop(errorCondition(paste("Name the candidates, or select them with `n_profiles` and", "`n_group_classes`, not both."), class = "latents_bad_argument", call = NULL))
        }
        rows <- vapply(chosen, function(candidate) .latents_candidate_row(grid, candidate), integer(1L))
        fits <- lapply(rows, function(at) .latents_candidate_at(grid, at))
        given <- nzchar(names(chosen) %||% rep("", length(chosen)))
        labels <- ifelse(given, labels, names[rows])
    }
    else {
        counts <- function(value) {
            is.null(value) || (is.numeric(value) && length(value) >= 1L && all(is.finite(value)) && all(value >= 1) && all(value == floor(value)))
        }
        if (!counts(n_profiles) || !counts(n_group_classes)) {
            stop(errorCondition(paste("`n_profiles` and `n_group_classes` must be NULL or positive whole", "numbers."), class = "latents_bad_argument", call = NULL))
        }
        rows <- which((is.null(n_profiles) | table$n_profiles %in% n_profiles) & (is.null(n_group_classes) | table$n_group_classes %in% n_group_classes))
        if (length(rows) == 0L) {
            stop(errorCondition(sprintf("No candidate matches that selection. The grid has %s.", paste(sprintf("\"%s\"", names), collapse = ", ")), class = "latents_unknown_candidate", call = NULL))
        }
        failed <- rows[vapply(rows, function(at) is.null(.subset2(grid, "fits")[[at]]), logical(1L))]
        if (length(failed) > 0L) {
            message(sprintf("Left out %s, which could not be fitted.", paste(sprintf("\"%s\"", names[failed]), collapse = ", ")))
        }
        rows <- setdiff(rows, failed)
        fits <- lapply(rows, function(at) .subset2(grid, "fits")[[at]])
        labels <- names[rows]
    }
    if (length(fits) < 2L) {
        stop(errorCondition(sprintf(paste("A comparison needs two or more fitted candidates; this one has %d.", "The grid has %s."), length(fits), paste(sprintf("\"%s\"", names), collapse = ", ")), class = "latents_bad_argument", call = NULL))
    }
    .multilpa_compare_fits(fits, labels, cutoff)
}

