function(x, label) {
    if (missing(label)) {
        stop(errorCondition(paste("Name the row: get_candidate(comparison, \"<model>\"), as the", "comparison's `model` column shows it."), class = "latents_bad_argument", call = NULL))
    }
    models <- attr(x, "models")
    if (is.null(models)) {
        stop(errorCondition(paste("This comparison carries no models: it was made by an earlier version,", "or rows were taken out of it. Compare the models again."), class = "latents_incomplete_fit", call = NULL))
    }
    present <- intersect(names(models), x$model)
    if (!is.character(label) || length(label) != 1L || is.na(label) || !label %in% present) {
        stop(errorCondition(sprintf("%s is not a model of this comparison. It has %s.", deparse1(label), paste(sprintf("\"%s\"", present), collapse = ", ")), class = "latents_unknown_candidate", call = NULL))
    }
    models[[label]]
}

