function(structure) {
    if (is.na(structure)) 
        return(list())
    stopifnot(`\`structure\` must be a supported covariance structure` = structure %in% .multilpa_structures())
    spherical <- structure %in% c("EII", "VII")
    letter <- function(position) {
        if (substr(structure, position, position) == "E") 
            "equal"
        else "varying"
    }
    arguments <- list(volume = letter(1L), shape = if (spherical) "spherical" else letter(2L))
    if (spherical) 
        return(arguments)
    third <- substr(structure, 3L, 3L)
    arguments$orientation <- if (third == "I") 
        "axis"
    else if (third == "E") 
        "equal"
    else "varying"
    arguments
}

