function(k, d, structure) {
    stopifnot(k >= 1L, d >= 1L, structure %in% .multilpa_structures())
    equal_volume <- startsWith(structure, "E")
    equal_shape <- substr(structure, 2L, 2L) == "E"
    volume <- if (equal_volume) 
        matrix(1, k * d, 1L)
    else diag(k)[rep(seq_len(k), each = d), , drop = FALSE]
    if (d == 1L) 
        return(volume)
    shape <- rbind(diag(d - 1L), rep(-1, d - 1L))
    if (equal_shape) 
        return(cbind(volume, shape[rep(seq_len(d), k), , drop = FALSE]))
    shape_design <- matrix(0, k * d, k * (d - 1L))
    invisible(lapply(seq_len(k), function(profile) {
        shape_design[(profile - 1L) * d + seq_len(d), (profile - 1L) * (d - 1L) + seq_len(d - 1L)] <<- shape
    }))
    cbind(volume, shape_design)
}

