function(scatter, weights, structure, min_variance) {
    stopifnot(is.matrix(scatter), nrow(scatter) == length(weights), all(weights > 0), all(is.finite(scatter)), min_variance > 0)
    k <- nrow(scatter)
    d <- ncol(scatter)
    scatter <- pmax(scatter, 0)
    if (k == 1L || structure == "VVI") 
        return(pmax(scatter/weights, min_variance))
    if (structure == "EEI") 
        return(matrix(pmax(colSums(scatter)/sum(weights), min_variance), k, d, byrow = TRUE))
    if (structure == "EII") 
        return(matrix(max(sum(scatter)/(sum(weights) * d), min_variance), k, d))
    if (structure == "VII") 
        return(matrix(pmax(rowSums(scatter)/(weights * d), min_variance), k, d))
    if (d == 1L) 
        return(.multilpa_bounded_variances(scatter, weights, if (startsWith(structure, "E")) "EEI" else "VVI", min_variance))
    design <- .multilpa_eigenvalue_design(k, d, structure)
    lower <- log(min_variance)
    n_volume <- if (startsWith(structure, "E")) 
        1L
    else k
    initial_volume <- if (n_volume == 1L) 
        sum(scatter)/(sum(weights) * d)
    else rowSums(scatter)/(weights * d)
    point <- c(log(pmax(initial_volume, min_variance)) + 0.1, numeric(ncol(design) - n_volume))
    counts <- rep(weights, each = d)
    values <- as.vector(t(scatter))
    total <- sum(weights)
    dimension <- ncol(design)
    active <- integer()
    iteration <- 0L
    settled <- FALSE
    while (iteration < 500L && !settled) {
        iteration <- iteration + 1L
        logs <- as.vector(design %*% point)
        terms <- values * exp(-logs)
        slack <- logs - lower
        binding_tolerance <- 64 * .Machine$double.eps * dimension * max(1, abs(lower), max(abs(logs)))
        if (length(active) > 0L && any(abs(slack[active]) > binding_tolerance)) {
            active <- active[abs(slack[active]) <= binding_tolerance]
        }
        gradient <- as.vector(crossprod(design, counts - terms))/total
        hessian <- crossprod(design, design * terms)/total
        basis <- if (length(active) > 0L) {
            factor <- qr(t(design[active, , drop = FALSE]))
            qr.Q(factor, complete = TRUE)[, seq_len(dimension) > length(active), drop = FALSE]
        }
        else diag(dimension)
        projected <- as.vector(crossprod(basis, gradient))
        if (length(projected) == 0L || max(abs(projected)) < 1e-11 * (1 + max(abs(gradient)))) {
            if (length(active) == 0L) {
                settled <- TRUE
                break
            }
            constraints <- design[active, , drop = FALSE]
            multipliers <- as.vector(solve(tcrossprod(constraints), constraints %*% gradient))
            kkt_tolerance <- 1e-11 * (1 + max(abs(gradient)))
            if (min(multipliers) >= -kkt_tolerance && all(slack >= -binding_tolerance) && max(abs(multipliers * slack[active])) <= kkt_tolerance) {
                settled <- TRUE
                break
            }
            release <- if (min(multipliers) < -kkt_tolerance) 
                which.min(multipliers)
            else which.max(abs(multipliers * slack[active]))
            active <- active[-release]
            next
        }
        reduced <- crossprod(basis, hessian %*% basis)
        delta <- tryCatch({
            factor <- chol(reduced)
            -backsolve(factor, forwardsolve(t(factor), projected))
        }, error = function(condition) -projected)
        direction <- as.vector(basis %*% delta)
        velocity <- as.vector(design %*% direction)
        velocity[abs(velocity) <= 64 * .Machine$double.eps * dimension * max(abs(design)) * max(abs(direction))] <- 0
        limited <- setdiff(which(velocity < 0), active)
        bounds <- slack[limited]/(-velocity[limited])
        alpha <- if (length(bounds) > 0L) 
            min(1, max(0, min(bounds)))
        else 1
        at_boundary <- if (length(bounds) > 0L && min(bounds) <= 1) 
            limited[which.min(bounds)]
        else integer()
        change <- function(alpha) {
            movement <- alpha * velocity
            sum(gradient * (alpha * direction)) + sum(terms * (expm1(-movement) + movement))/total
        }
        candidate <- point + alpha * direction
        candidate_change <- change(alpha)
        halvings <- 0L
        while ((!is.finite(candidate_change) || candidate_change > 0) && halvings < 60L) {
            alpha <- alpha/2
            candidate <- point + alpha * direction
            candidate_change <- change(alpha)
            halvings <- halvings + 1L
            at_boundary <- integer()
        }
        point <- candidate
        if (length(at_boundary) > 0L) {
            possible <- unique(c(active, at_boundary))
            factor <- qr(t(design[possible, , drop = FALSE]))
            active <- possible[factor$pivot[seq_len(factor$rank)]]
        }
    }
    if (!settled) {
        stop(errorCondition("The bounded covariance optimization did not satisfy its KKT conditions.", class = "latents_no_converge", call = NULL))
    }
    logs <- as.vector(design %*% point)
    stopifnot(`the bounded chart must remain feasible` = all(is.finite(logs)), all(logs >= lower - 1e-12))
    matrix(exp(logs), k, d, byrow = TRUE)
}

