function(object, response = c("natural", "free")) {
    response <- match.arg(response)
    vars <- object$vars
    profiles <- paste0("profile_", seq_len(object$n_profiles))
    variance_rows <- if (identical(object$variance_model, "equal")) 
        "shared"
    else profiles
    block <- function(term, outcome, level, parameter) {
        grid <- expand.grid(term = term, outcome = outcome, stringsAsFactors = FALSE)
        data.frame(level = rep(level, nrow(grid)), outcome = grid$outcome, term = grid$term, parameter = rep(parameter, nrow(grid)), stringsAsFactors = FALSE)
    }
    continuous <- .multilpa_continuous_names(object)
    spread <- if (.multilpa_cov_is_full(object)) {
        positions <- which(lower.tri(matrix(0, length(continuous), length(continuous)), diag = TRUE), arr.ind = TRUE)
        pairs <- sprintf("%s:%s", continuous[positions[, 1L]], continuous[positions[, 2L]])
        block(pairs, variance_rows, "measurement", "covariance")
    }
    else block(continuous, variance_rows, "measurement", "variance")
    blocks <- object$response_probabilities %||% list()
    responses <- do.call(rbind, c(list(block(character(), profiles, "measurement", "response")), lapply(names(blocks), function(indicator) {
        categories <- colnames(blocks[[indicator]])
        if (identical(response, "free")) categories <- categories[-length(categories)]
        block(sprintf("%s:%s", indicator, categories), profiles, "measurement", if (identical(response, "free")) "response_logit" else "response")
    })))
    extra <- .latents_extra_labels(object, profiles, free = identical(response, "free"))
    rbind(block(continuous, profiles, "measurement", "mean"), spread, responses, extra, block(rownames(object$profile_coefficients), colnames(object$profile_coefficients), "profile", "coefficient"), block(rownames(object$group_coefficients), colnames(object$group_coefficients), "group", "coefficient"))
}

