function(object) {
    stopifnot(`\`object\` must be a fitted \`multilpa_covariates\` model` = inherits(object, "multilpa_covariates"))
    if (is.null(object$indicator_data) || is.null(object$profile_design) || is.null(object$group_design)) {
        stop(errorCondition(paste("This fit does not store its indicators and membership designs, so the", "fitting data cannot be rebuilt; supply `data`."), class = "latents_no_indicator_data", call = NULL))
    }
    result <- data.frame(row.names = seq_len(object$n_observations))
    result <- cbind(result, as.data.frame(.multilpa_uncentered_indicators(object)))
    invisible(lapply(object$categorical %||% character(), function(name) {
        result[[name]] <<- object$categorical_values[[name]][object$categorical_data[, name]]
    }))
    extra <- .latents_draw_extra_columns(object$extra_data)
    if (length(extra) > 0L) 
        result[names(extra)] <- extra
    result[[object$id]] <- object$group_values[object$group_index]
    profile_block <- object$profile_design[[1L]][, object$n_group_classes + seq_along(object$profile_covariates), drop = FALSE]
    if (ncol(profile_block) > 0L) {
        colnames(profile_block) <- object$profile_covariates
        result <- cbind(result, as.data.frame(profile_block))
    }
    group_block <- object$group_design[, -1L, drop = FALSE]
    if (ncol(group_block) > 0L) {
        colnames(group_block) <- object$group_covariates
        result <- cbind(result, as.data.frame(group_block[object$group_index, , drop = FALSE]))
    }
    result
}

