function(design) {
    stopifnot(`\`design\` must be a finite numeric matrix` = is.matrix(design) && is.numeric(design) && all(is.finite(design)))
    if (ncol(design) == 0L || nrow(design) < ncol(design)) 
        return(NULL)
    decomposition <- qr(design)
    if (decomposition$rank < ncol(design) || !identical(decomposition$pivot, seq_len(ncol(design)))) {
        return(NULL)
    }
    factor <- qr.R(decomposition)/sqrt(nrow(design))
    factor * sign(diag(factor))
}

