function(profile_coefficients, group_coefficients, profile_design, group_design, limit = 20) {
    stopifnot(`\`profile_design\` must be a list of matrices` = is.list(profile_design) && length(profile_design) >= 1L, `\`group_design\` must be a matrix` = is.matrix(group_design))
    unit_free <- function(coefficients, design) {
        basis <- .multilpa_design_basis(design)
        if (is.null(basis)) {
            as.matrix(coefficients) * .multilpa_design_scale(design)
        }
        else basis %*% as.matrix(coefficients)
    }
    scaled <- c(unit_free(profile_coefficients, do.call(rbind, profile_design)), unit_free(group_coefficients, group_design))
    any(abs(scaled) > limit)
