function(data, vars, id, n_profiles, n_group_classes, family, variance_model, between_variance, n_starts, max_iter, tol, min_variance, seed, call, weights = NULL, search = "kmeans", n_screen = NULL) {
    counts <- list(n_profiles = n_profiles, n_group_classes = n_group_classes, n_starts = n_starts)
    invisible(lapply(names(counts), function(field) {
        value <- counts[[field]]
        if (!is.numeric(value) || length(value) != 1L || !is.finite(value) || value < 1 || value != floor(value) || value > .Machine$integer.max) {
            stop(errorCondition(sprintf("%s must be a positive integer.", field), class = "latents_bad_argument", call = NULL))
        }
    }))
    if (!is.numeric(max_iter) || length(max_iter) != 1L || !is.finite(max_iter) || max_iter < 0 || max_iter != floor(max_iter) || max_iter > .Machine$integer.max || !is.numeric(tol) || length(tol) != 1L || !is.finite(tol) || tol <= 0 || !is.numeric(min_variance) || length(min_variance) != 1L || !is.finite(min_variance) || min_variance <= 0) {
        stop(errorCondition("max_iter, tol and min_variance must be valid numbers.", class = "latents_bad_argument", call = NULL))
    }
    .multilpa_check_seed(seed)
    n_profiles <- as.integer(n_profiles)
    n_group_classes <- as.integer(n_group_classes)
    stats <- .additive_prepare(data, vars, id, weights)
    sampling_weights <- stats$sampling_weights
    if (n_group_classes > stats$n_groups) {
        stop(errorCondition(sprintf("%d group classes cannot be estimated from %d groups.", n_group_classes, stats$n_groups), class = "latents_unidentified", call = NULL))
    }
    x <- matrix(as.numeric(as.matrix(data[, vars, drop = FALSE])), nrow(data), length(vars), dimnames = list(NULL, vars))
    group_index <- stats$index
    group_means <- unname(stats$averages)
    .latents_local_seed(seed)
    fitted <- if (identical(family, "full_cross_level")) {
        screen <- .latents_search_screen(search, n_starts, n_screen, max_iter)
        best <- .cross_level_select(.latents_run_starts(n_starts, prepare = function(start_index) {
            .cross_level_initialize(x, group_index, group_means, n_profiles, n_group_classes, variance_model, between_variance, min_variance, start_index, kind = .latents_start_kind(start_index, n_starts), sampling_weights = sampling_weights)
        }, run = function(start_index, start, pause = Inf, resume = NULL) {
            .cross_level_em(x, group_index, group_means, start %||% resume$state, variance_model, between_variance, min_variance, max_iter, tol, sampling_weights, pause = pause, resume = resume)
        }, select_start = "likelihood", screen = screen), n_starts)
        best$search_record <- .latents_search_record(search, n_starts, screen, "likelihood", "allow")
        if (!is.null(sampling_weights)) {
            reported <- .multilpa_expectation(x, group_index, c(best$parameters, list(group_log_density = .cross_level_group_density(group_means, best$parameters$between_means, best$parameters$between_variances))))
            reported$log_likelihood <- best$expectation$log_likelihood
            best$expectation <- reported
        }
        best
    }
    else {
        .cross_level_restricted(x, group_index, group_means, n_profiles, n_group_classes, variance_model, between_variance, n_starts, max_iter, tol, min_variance, sampling_weights, search = search, n_screen = n_screen)
    }
    result <- .cross_level_result(fitted, family, stats, x, group_means, vars, id, n_profiles, n_group_classes, variance_model, between_variance, min_variance, call)
    record <- fitted$search_record %||% .latents_search_record(search, n_starts, .latents_search_screen(search, n_starts, n_screen, max_iter), "likelihood", "allow")
    result[names(record)] <- record
    if (!is.null(sampling_weights)) {
        result$weights <- weights
        result$sampling_weights <- stats::setNames(sampling_weights, stats$ids)
    }
    result
}

