        stop(errorCondition("`definitions` describes one criterion per row, which the wide form has not. Use format = \"long\".", class = "latents_bad_argument", call = NULL))
    }
    q <- x$n_parameters
    deviance <- -2 * x$log_likelihood
    conventions <- data.frame(convention = c("groups", "individuals"), n = c(.multilpa_group_sample_size(x), x$n_informative %||% x$n_observations))
    entropies <- c(groups = if (is.null(x$group_posteriors)) NA_real_ else .multilpa_entropy_sum(.multilpa_classified_group_posteriors(x)), individuals = .multilpa_entropy_sum(.multilpa_classified_posteriors(x)))
    scale_free <- data.frame(criterion = c("deviance", "aic", "kic"), convention = NA_character_, n = NA_integer_, penalty = c(0, 2 * q, 3 * (q + 1)))
    scaled <- do.call(rbind, lapply(seq_len(nrow(conventions)), function(row) {
        convention <- conventions$convention[row]
        n <- conventions$n[row]
        entropy_sum <- entropies[[convention]]
        penalties <- c(bic = q * log(n), sabic = q * log((n + 2)/24), caic = q * (log(n) + 1), awe = 2 * q * (1.5 + log(n)) + 2 * entropy_sum, icl = q * log(n) + 2 * entropy_sum, clc = 2 * entropy_sum)
        data.frame(criterion = names(penalties), convention = convention, n = n, penalty = unname(penalties))
    }))
    result <- rbind(scale_free, scaled)
    result$value <- deviance + result$penalty
    result <- result[c("criterion", "convention", "n", "value")]
    row.names(result) <- NULL
    if (identical(format, "wide")) 
        return(.multilpa_criteria_wide(result, x))
