function(grid) {
    present <- intersect(.multilpa_enumeration_criteria(), names(grid))
    eligible <- grid$converged %in% TRUE
    rows <- lapply(present, function(name) {
        values <- grid[[name]]
        values[!eligible] <- NA_real_
        best <- if (all(is.na(values))) 
            NA_integer_
        else which.min(values)
        data.frame(criterion = sub("_(groups|individual)$", "", name), convention = if (grepl("_groups$", name)) 
            "groups"
        else if (grepl("_individual$", name)) 
            "individuals"
        else NA_character_, candidate = if (is.na(best) || is.null(grid$candidate)) 
            NA_character_
        else grid$candidate[best], n_profiles = if (is.na(best)) 
            NA_integer_
        else as.integer(grid$n_profiles[best]), n_group_classes = if (is.na(best)) 
            NA_integer_
        else as.integer(grid$n_group_classes[best]), model = if (is.na(best)) 
            NA_character_
        else as.character(grid$model[best]), value = if (is.na(best)) 
            NA_real_
        else values[best], row.names = NULL, stringsAsFactors = FALSE)
    })
    do.call(rbind, rows)
}

