function(null_model, alternative_model) {
    stopifnot(`\`null_model\` must be a fitted \`multilpa\` model` = inherits(null_model, "multilpa"), `\`alternative_model\` must be a fitted \`multilpa\` model` = inherits(alternative_model, "multilpa"))
    held_null <- null_model$fixed %||% character()
    held_alternative <- alternative_model$fixed %||% character()
    if (length(held_null) == 0L && length(held_alternative) == 0L) {
        return(list(start = NULL, fixed = character()))
    }
    if (length(held_null) == 0L || length(held_alternative) == 0L) {
        stop(errorCondition(paste("One model holds measurement blocks fixed and the other estimates them,", "so the smaller is not nested in the larger. Fit both with the same", "`fixed` specification, or neither."), class = "latents_bad_nesting", call = NULL))
    }
    if (!identical(sort(held_null), sort(held_alternative))) {
        stop(errorCondition(sprintf(paste("The models hold different measurement blocks fixed (%s against %s), so", "they are not nested. Give both the same `fixed` specification."), paste(sprintf("\"%s\"", sort(held_null)), collapse = ", "), paste(sprintf("\"%s\"", sort(held_alternative)), collapse = ", ")), class = "latents_bad_nesting", call = NULL))
    }
    if (!identical(null_model$n_profiles, alternative_model$n_profiles)) {
        stop(errorCondition(sprintf(paste("A held measurement cannot be compared across %d and %d profiles: the", "held blocks have different shapes, so the null is not a restriction of", "the alternative. Compare models that differ by one group class, or", "refit both without `fixed`."), null_model$n_profiles, alternative_model$n_profiles), class = "latents_bad_nesting", call = NULL))
    }
    covariance_model <- null_model$covariance_model %||% "diagonal"
    start <- starting_values(null_model, what = "measurement")
    values_null <- .multilpa_held_parameters(start, held_null, covariance_model)
    values_alternative <- .multilpa_held_parameters(starting_values(alternative_model, what = "measurement"), held_alternative, alternative_model$covariance_model %||% "diagonal")
    agreement <- all.equal(values_null, values_alternative, tolerance = 1e-08)
    if (!isTRUE(agreement)) {
        stop(errorCondition(sprintf(paste("The models hold the same blocks at different values, so they are not", "nested: %s. Hold both at one measurement solution, as fit_staged()", "does."), paste(agreement, collapse = "; ")), class = "latents_bad_nesting", call = NULL))
    }
    if (alternative_model$n_parameters <= null_model$n_parameters) {
        stop(errorCondition(sprintf(paste("The alternative must estimate more free parameters than the null; with", "this constraint it estimates %d against %d."), alternative_model$n_parameters, null_model$n_parameters), class = "latents_bad_nesting", call = NULL))
    }
    list(start = start, fixed = held_null)
}

