    stopifnot(`both models must be multilpa() fits of one family, with or without membership covariates` = (inherits(null_model, "multilpa") && inherits(alternative_model, "multilpa")) || (covariate_family && inherits(alternative_model, "multilpa_covariates")))
    .multilpa_refuse_noise(null_model, "bootstrap_lrt()")
    .multilpa_refuse_noise(alternative_model, "bootstrap_lrt()")
    if (!is.null(null_model$prior) || !is.null(alternative_model$prior)) {
        stop(errorCondition(paste("bootstrap_lrt() requires maximum-likelihood fits; a fit with `prior`", "is estimated at a posterior mode. Refit both models without `prior`."), class = "latents_unsupported_prior", call = NULL))
    }
    data <- if (covariate_family && is.null(data)) {
        .multilpa_cov_stored_data(alternative_model)
    }
    else .multilpa_number_single_level(null_model, .multilpa_resolve_data(null_model, data))
    stopifnot(is.data.frame(data), is.numeric(iter), length(iter) == 1L, is.finite(iter), iter >= 2L, iter == as.integer(iter), is.null(n_starts) || (is.numeric(n_starts) && length(n_starts) == 1L && is.finite(n_starts) && n_starts >= 1 && n_starts == as.integer(n_starts)), is.null(max_iter) || (is.numeric(max_iter) && length(max_iter) == 1L && is.finite(max_iter) && max_iter >= 1 && max_iter == as.integer(max_iter)), is.null(tol) || (is.numeric(tol) && length(tol) == 1L && is.finite(tol) && tol > 
        0))
    controls <- lapply(list(null = null_model, alternative = alternative_model), .latents_refit_controls, n_starts = n_starts, max_iter = max_iter, tol = tol)
    .multilpa_check_seed(seed)
    .latents_local_seed(seed)
    fields <- c("vars", "id", "group_values", "group_index", "variance_model", "min_variance", "covariance_model")
    fields <- c(fields, "categorical", "categorical_levels", "min_probability", "ordinal", "count")
    extra_spec <- function(model) {
        list(levels = model$extra_data$ordinal_levels, count_model = model$extra_data$count_model %||% "poisson", count_dispersion = model$extra_data$count_dispersion %||% "varying")
    }
    missing_for <- function(model) model$missing %||% "error"
    structure_for <- function(model) model$covariance_structure %||% .multilpa_resolve_structure(model$variance_model, model$covariance_model %||% "diagonal")
    centering_for <- function(model) model$centering %||% "none"
    scaling_for <- function(model) model$scaling %||% "none"
    drop_empty_for <- function(model) model$drop_empty %||% TRUE
    same_fields <- all(vapply(fields, function(field) identical(null_model[[field]], alternative_model[[field]]), logical(1))) && identical(null_model$covariance_pattern, alternative_model$covariance_pattern) && identical(.latents_direct_key(null_model), .latents_direct_key(alternative_model))
    if (!same_fields || !identical(extra_spec(null_model), extra_spec(alternative_model)) || !identical(structure_for(null_model), structure_for(alternative_model)) || !identical(centering_for(null_model), centering_for(alternative_model)) || !identical(scaling_for(null_model), scaling_for(alternative_model)) || !identical(drop_empty_for(null_model), drop_empty_for(alternative_model)) || !identical(missing_for(null_model), missing_for(alternative_model))) {
        stop(errorCondition(paste("Models must use the same observations, group layout, covariance", "structure, local dependence, direct effects, centering and scaling", "mode, missing-data handling and `drop_empty`."), class = "latents_incomparable_models", call = NULL))
