            stop(errorCondition("data must preserve the original observations and group ordering.", class = "latents_bad_inference_data", call = NULL))
        }
        continuous <- .multilpa_continuous_names(model)
        x <- if (length(continuous) == 0L) matrix(numeric(0), nrow(data), 0L) else .multilpa_center_like(null_model, as.matrix(data[continuous]))
