            stop(errorCondition(paste("Bootstrap needs finite indicators; missing values are allowed only", "when both models were fitted with `missing = \"fiml\"`."), class = "latents_bad_data", call = NULL))
        }
        if (!is.null(model$indicator_data) && length(continuous) > 0L && !identical(x, model$indicator_data)) {
            stop(errorCondition("data must reproduce the original indicator data and row order.", class = "latents_bad_inference_data", call = NULL))
        }
        encoded <- if (length(model$categorical %||% character()) == 0L) NULL else .multilpa_encode_categorical(data[, model$categorical, drop = FALSE])
        codes <- encoded$codes
        if (!fiml && anyNA(codes)) {
            stop(errorCondition(paste("Bootstrap needs complete indicators unless both models were fitted", "with `missing = \"fiml\"`."), class = "latents_bad_data", call = NULL))
        }
