            stop(errorCondition("data must reproduce the original categorical levels and coding.", class = "latents_bad_inference_data", call = NULL))
        }
        if (!is.null(codes) && !identical(unname(codes), unname(model$categorical_data))) {
            stop(errorCondition("data must reproduce the original categorical indicators and row order.", class = "latents_bad_inference_data", call = NULL))
        }
        if (!is.null(model$extra_data)) .multilpa_check_alignment(model, data)
        extra <- if (is.null(model$extra_data)) NULL else .latents_prepare_extra_like(model, data)
        likelihood <- .multilpa_expectation(x, model$group_index, model, codes, extra = extra)$log_likelihood
        if (abs(likelihood - model$log_likelihood) > 1e-07 * (1 + abs(likelihood))) {
            stop(errorCondition("data do not reproduce the fitted model likelihood.", class = "latents_bad_inference_data", call = NULL))
        }
    }))
