        stop(errorCondition(sprintf(paste("Alternative has lower likelihood by %.3g, beyond the %.3g that", "`tol = %.3g` can explain; improve its optimization first."), -observed, reversal_window, max(controls$null$tol, controls$alternative$tol)), class = "latents_reversed_likelihood", call = NULL))
    }
    observed <- max(0, observed)
    replicates <- .latents_blrt_replicates(iter, function(i) {
