        list(statistic = statistic, valid = valid, boundary = any(vapply(models, `[[`, logical(1), "boundary")), logits_settled = logits_settled, null_replications = models[[1L]]$n_best_replicated %||% NA_integer_, alternative_replications = models[[2L]]$n_best_replicated %||% NA_integer_)
    }, muffle_warnings = FALSE)
