    result <- list(statistic = observed, p_value = tally$p_value, monte_carlo_se = tally$monte_carlo_se, iter = iter, n_valid = tally$n_valid, replicates = replicates, fixed = constraint$fixed, null_profiles = null_model$n_profiles, null_group_classes = null_model$n_group_classes, alternative_profiles = alternative_model$n_profiles, alternative_group_classes = alternative_model$n_group_classes, call = match.call(), refit_controls = .latents_refit_controls_frame(controls))
    class(result) <- "multilpa_bootstrap_lrt"
    result
}

