function(counts, intercepts, locations, max_newton = 100L) {
    n_profiles <- nrow(counts)
    n_categories <- ncol(counts)
    scores <- seq_len(n_categories) - 1
    features <- lapply(seq_len(n_profiles), function(profile) {
        location <- matrix(0, n_categories, n_profiles - 1L)
        if (profile < n_profiles) 
            location[, profile] <- scores
        cbind(diag(n_categories)[, -1L, drop = FALSE], location)
    })
    totals <- rowSums(counts)
    pack <- function(a, eta) c(a, eta[-n_profiles])
    unpack <- function(theta) {
        list(intercepts = theta[seq_len(n_categories - 1L)], locations = c(theta[n_categories - 1L + seq_len(n_profiles - 1L)], 0))
    }
    objective <- function(theta) {
        point <- unpack(theta)
        sum(counts * .latents_ordinal_log_probabilities(point$intercepts, point$locations))
    }
    derivatives <- function(theta) {
        point <- unpack(theta)
        probability <- exp(.latents_ordinal_log_probabilities(point$intercepts, point$locations))
        pieces <- lapply(seq_len(n_profiles), function(profile) {
            feature <- features[[profile]]
            expected <- drop(crossprod(feature, probability[profile, ]))
            list(gradient = drop(crossprod(feature, counts[profile, ])) - totals[profile] * expected, information = totals[profile] * (crossprod(feature, feature * probability[profile, ]) - tcrossprod(expected)))
        })
        list(gradient = Reduce(`+`, lapply(pieces, `[[`, "gradient")), information = Reduce(`+`, lapply(pieces, `[[`, "information")))
    }
    theta <- pack(intercepts, locations)
    value <- objective(theta)
    iteration <- 0L
    while (iteration < max_newton) {
        step_parts <- derivatives(theta)
        if (max(abs(step_parts$gradient)) <= 1e-10 * (1 + sum(totals))) 
            break
        information <- step_parts$information
        ridge <- 1e-10 * (1 + max(abs(diag(information))))
        factor <- chol(information + diag(ridge, nrow(information)))
        direction <- backsolve(factor, forwardsolve(t(factor), step_parts$gradient))
        step <- 1
        accepted <- FALSE
        while (step > 1e-10 && !accepted) {
            candidate <- theta + step * direction
            candidate_value <- objective(candidate)
            accepted <- is.finite(candidate_value) && candidate_value >= value - 1e-12 * (1 + abs(value))
            if (!accepted) 
                step <- step/2
        }
        if (!accepted) 
            break
        theta <- candidate
