function(parameters, extra, n_profiles, scale) {
    if (is.null(extra)) 
        return(stats::setNames(numeric(0), character(0)))
    names_of <- .latents_extra_names(extra)
    ordinal <- lapply(seq_along(names_of$ordinal), function(j) {
        indicator <- names_of$ordinal[[j]]
        intercepts <- unname(parameters$ordinal_intercepts[[j]])
        locations <- unname(parameters$ordinal_locations[, j])[seq_len(n_profiles - 1L)]
        c(stats::setNames(intercepts, sprintf("ordinal_intercept[shared,%s,%s]", indicator, extra$ordinal_levels[[j]][-1L])), stats::setNames(locations, sprintf("ordinal_location[%d,%s]", seq_len(n_profiles - 1L), indicator)))
    })
    natural <- identical(scale, "natural")
    count <- lapply(seq_along(names_of$count), function(j) {
        indicator <- names_of$count[[j]]
        means <- unname(parameters$count_means[, j])
        mean_values <- stats::setNames(if (natural) 
            means
        else log(means), sprintf(if (natural) 
            "count_mean[%d,%s]"
        else "log_count_mean[%d,%s]", seq_len(n_profiles), indicator))
        if (!.latents_negative_binomial(extra)) 
            return(mean_values)
        rows <- .latents_dispersion_rows(extra, n_profiles)
        dispersion <- unname(parameters$count_dispersion[seq_len(rows), j])
        outcome <- if (identical(extra$count_dispersion, "equal")) 
            "shared"
        else as.character(seq_len(rows))
        c(mean_values, stats::setNames(if (natural) dispersion else log(dispersion), sprintf(if (natural) "count_dispersion[%s,%s]" else "log_count_dispersion[%s,%s]", outcome, indicator)))
    })
    effects <- extra$direct$effects
    direct <- if (is.null(effects)) 
        NULL
    else stats::setNames(unname(parameters$direct_effects), sprintf("direct_effect[shared,%s,%s]", effects$indicator, effects$covariate))
    unlist(c(ordinal, count, list(direct)))
}

