function(x, data = NULL, standard_errors = TRUE) {
    extra <- x$extra_data
    empty <- data.frame(profile = integer(), indicator = character(), category = character(), probability = numeric(), location = numeric(), location_standard_error = numeric())
    if (is.null(extra$ordinal)) 
        return(empty)
    n_profiles <- x$n_profiles
    frame <- do.call(rbind, lapply(seq_len(ncol(extra$ordinal)), function(j) {
        levels_for <- extra$ordinal_levels[[j]]
        probability <- exp(.latents_ordinal_log_probabilities(x$ordinal_intercepts[[j]], x$ordinal_locations[, j]))
        data.frame(profile = rep(seq_len(n_profiles), times = length(levels_for)), indicator = colnames(extra$ordinal)[[j]], category = rep(levels_for, each = n_profiles), probability = as.vector(probability), location = rep(unname(x$ordinal_locations[, j]), times = length(levels_for)), stringsAsFactors = FALSE)
    }))
    if (isTRUE(standard_errors)) {
        errors <- .multilpa_table_errors(x, data)
        frame$location_standard_error <- if (is.null(errors)) 
            NA_real_
        else .multilpa_match_error(errors, "ordinal_location", frame$profile, frame$indicator)
    }
    category_rank <- unlist(lapply(seq_len(ncol(extra$ordinal)), function(j) {
        rep(seq_along(extra$ordinal_levels[[j]]), each = n_profiles)
    }))
    frame <- frame[order(match(frame$indicator, colnames(extra$ordinal)), frame$profile, category_rank), ]
    row.names(frame) <- NULL
    frame
}

