function(x, data = NULL, standard_errors = TRUE) {
    means <- x$count_means
    if (is.null(means)) {
        return(data.frame(profile = integer(), indicator = character(), mean = numeric(), standard_error = numeric()))
    }
    frame <- data.frame(profile = rep(seq_len(nrow(means)), times = ncol(means)), indicator = rep(colnames(means), each = nrow(means)), mean = as.vector(means), stringsAsFactors = FALSE)
    negative_binomial <- !is.null(x$count_dispersion)
    if (negative_binomial) 
        frame$dispersion <- as.vector(x$count_dispersion)
    if (!isTRUE(standard_errors)) 
        return(frame)
    errors <- .multilpa_table_errors(x, data)
    frame$standard_error <- if (is.null(errors)) 
        NA_real_
    else .multilpa_match_error(errors, "count_mean", frame$profile, frame$indicator)
    if (negative_binomial) {
        shared <- identical(x$extra_data$count_dispersion, "equal")
        frame$dispersion_standard_error <- if (is.null(errors)) 
            NA_real_
        else .multilpa_match_error(errors, "count_dispersion", if (shared) 
            rep("shared", nrow(frame))
        else frame$profile, frame$indicator)
    }
    frame
