function(what, accepted, extra) {
    if (length(extra) == 0L) 
        return(invisible(NULL))
    supplied <- names(extra) %||% rep("", length(extra))
    unknown <- is.na(match(supplied, accepted)) | !nzchar(supplied)
    if (!any(unknown)) 
        return(invisible(NULL))
    labels <- ifelse(nzchar(supplied[unknown]), sprintf("`%s`", supplied[unknown]), "an unnamed argument")
    takes <- if (length(accepted) == 0L) 
        "takes no further arguments"
    else sprintf("takes %s", paste(sprintf("`%s`", accepted), collapse = ", "))
    stop(errorCondition(sprintf("`what = \"%s\"` does not use %s; it %s.", what, paste(labels, collapse = ", "), takes), class = "latents_bad_argument", call = NULL))
}

