        table <- .subset2(x, "table")
        return(list(individuals = ifelse(table$n_classes >= 2L, table$smallest_share, NA_real_), groups = rep(NA_real_, nrow(table))))
    }
    counts_field <- c(individuals = "effective_profile_counts", groups = "effective_group_counts")
    share <- function(fit, level) {
        posteriors <- if (identical(level, "individuals")) 
            .multilpa_classified_posteriors(fit)
