        if (is.null(posteriors)) 
            return(NA_real_)
        weights <- .multilpa_level_weights(fit, level, nrow(posteriors)) %||% 1
        counts <- fit[[counts_field[[level]]]] %||% colSums(posteriors[, seq_len(if (identical(level, "individuals")) ncol(fit$subject_posteriors) else ncol(posteriors)), drop = FALSE] * weights)
