            return(NA_real_)
        min(counts)/sum(posteriors * weights)
    }
    fits <- .subset2(x, "fits")
    lapply(stats::setNames(names(counts_field), names(counts_field)), function(level) {
        vapply(fits, function(fit) {
            if (is.null(fit)) 
                NA_real_
            else share(fit, level)
        }, numeric(1L), USE.NAMES = FALSE)
    })
}

