function(spec, stats, params, weights, bounds, max_steps = 25L) {
    log_likelihood <- function(v) {
        tryCatch(.growth_expectation(spec, stats, .growth_unpack(spec, v, params))$log_likelihood, latents_singular_covariance = function(condition) -Inf)
    }
    total <- function(v) {
        colSums(.growth_scores(spec, stats, .growth_unpack(spec, v, params)) * weights)
    }
    on_bound <- function(v, score) {
        width <- 1e-08 * (1 + abs(v))
        (v <= bounds$lower + width & score <= 0) | (v >= bounds$upper - width & score >= 0)
    }
    newton_step <- function(v) {
        score <- total(v)
        free <- !on_bound(v, score)
        information <- .inference_score_information(total, v, 1e-05, scheme = "central", h_rule = "plus1")[free, free, drop = FALSE]
        inverse <- tryCatch(solve(information), error = function(condition) NULL)
        if (is.null(inverse) || any(diag(inverse) <= 0)) {
            return(list(direction = NULL, displacement = Inf, free = free))
        }
        direction <- numeric(length(v))
        direction[free] <- as.vector(inverse %*% score[free])
        list(direction = direction, free = free, displacement = max(abs(score[free]) * sqrt(diag(inverse))))
    }
    theta <- .growth_pack(spec, params)
    value <- log_likelihood(theta)
    iterations <- 0L
    step <- newton_step(theta)
    while (iterations < max_steps && !is.null(step$direction) && step$displacement >= 1e-08) {
        accepted <- FALSE
        multiplier <- 1
        while (!accepted && multiplier > 1e-09) {
            candidate <- pmin(pmax(theta + multiplier * step$direction, bounds$lower), bounds$upper)
            candidate_value <- log_likelihood(candidate)
            accepted <- is.finite(candidate_value) && candidate_value >= value - 1e-10 * (1 + abs(value))
            multiplier <- multiplier/2
        }
        if (!accepted) 
            break
        theta <- candidate
        value <- candidate_value
        iterations <- iterations + 1L
        step <- newton_step(theta)
    }
    score <- total(theta)
    at_bound <- names(theta)[on_bound(theta, score)]
    displacement <- step$displacement
    if (displacement >= 1e-04) {
        process <- startsWith(names(theta), "residual_correlation.")
        rest <- !process & !(names(theta) %in% at_bound)
        information <- .inference_score_information(total, theta, 1e-05, scheme = "central", h_rule = "plus1")[rest, rest, drop = FALSE]
        inverse <- tryCatch(solve(information), error = function(condition) NULL)
        held <- if (is.null(inverse) || any(diag(inverse) <= 0)) 
            Inf
        else max(abs(score[rest]) * sqrt(diag(inverse)))
        if (held < 1e-04) {
            at_bound <- union(at_bound, names(theta)[process])
            displacement <- held
        }
    }
    list(params = .growth_unpack(spec, theta, params), iterations = iterations, displacement = displacement, converged = displacement < 1e-04, at_bound = at_bound)
}

