function(residual_correlation, residual_time, random, formula, data) {
    bad <- function(message, class = "latents_bad_argument") {
        stop(errorCondition(message, class = class, call = NULL))
    }
    if (is.null(random)) {
        bad("`residual_correlation` applies to a growth mixture: give `random` as well.")
    }
    if (is.null(residual_time)) {
        candidates <- unique(c(all.vars(random), all.vars(formula[[3L]])))
        numeric_ones <- candidates[vapply(candidates, function(v) is.numeric(data[[v]]), logical(1))]
        if (length(numeric_ones) == 0L) {
            bad(paste("`residual_correlation` needs the time of each observation: name it", "with `residual_time`."))
        }
        residual_time <- numeric_ones[1L]
    }
    if (!is.character(residual_time) || length(residual_time) != 1L || !residual_time %in% names(data) || !is.numeric(data[[residual_time]])) {
        bad("`residual_time` must name a numeric column of `data`.")
    }
    if (identical(residual_correlation, "brownian") && any(data[[residual_time]] < 0, na.rm = TRUE)) {
        bad(paste("Brownian motion starts at time zero: `residual_time` must not be", "negative."), "latents_bad_data")
    }
    residual_time
}

