function(fit, vcov_type = c("observed", "robust", "opg")) {
    vcov_type <- match.arg(vcov_type)
    spec <- fit$spec
    stats <- fit$stats
    params <- fit$params
    theta <- .growth_pack(spec, params)
    weights <- spec$sampling_weights %||% 1
    scores <- .growth_scores(spec, stats, params)
    n_units <- sum((spec$sampling_weights %||% rep(1, nrow(scores))) > 0)
    if (identical(vcov_type, "robust")) {
        .multilpa_require_clusters(n_units, length(theta), "A robust growth covariance", unit = "independent units")
        .inference_require_rank(scores * weights, "The unit scores are rank deficient; robust inference is unavailable.")
    }
    total <- function(v) {
        colSums(.growth_scores(spec, stats, .growth_unpack(spec, v, params)) * weights)
    }
    information <- if (identical(vcov_type, "opg")) 
        crossprod(scores * sqrt(weights))
    else .inference_score_information(total, theta, 1e-05, scheme = "central", h_rule = "plus1")
    dimnames(information) <- list(names(theta), names(theta))
    free <- !names(theta) %in% (fit$residual_boundary %||% character())
    inverse <- matrix(0, length(theta), length(theta))
    inverse[free, free] <- .mixture_invert(information[free, free, drop = FALSE])
    vcov <- inverse
    if (identical(vcov_type, "robust")) {
        vcov[free, free] <- .inference_sandwich(inverse[free, free, drop = FALSE], crossprod(scores[, free, drop = FALSE] * weights), n_units)
    }
    dimnames(vcov) <- list(names(theta), names(theta))
    list(theta = theta, vcov = vcov, vcov_type = vcov_type, information = information, score_norm = max(abs(colSums(scores * weights))))
}

