    spec <- x$spec
    terms <- colnames(spec$random_design)
    n_random <- length(terms)
    classes <- .growth_class_names(x)
    template <- x$params
    covariance_of <- function(v, k) {
        .growth_covariances(spec, .growth_unpack(spec, v, template))[[k]]
    }
    pairs <- which(upper.tri(diag(n_random)), arr.ind = TRUE)
    shared <- identical(spec$random_covariance, "equal")
    if (shared) 
        classes <- "all"
    covariance_rows <- do.call(rbind, lapply(seq_along(classes), function(k) {
        variances <- lapply(seq_len(n_random), function(j) {
            cbind(data.frame(class = classes[k], parameter = "variance", term = terms[j], stringsAsFactors = FALSE), .growth_delta_table(inference, function(v) covariance_of(v, k)[j, j], "log", level))
        })
        deviations <- lapply(seq_len(n_random), function(j) {
            cbind(data.frame(class = classes[k], parameter = "sd", term = terms[j], stringsAsFactors = FALSE), .growth_delta_table(inference, function(v) sqrt(covariance_of(v, k)[j, j]), "log", level))
        })
        correlations <- if (isTRUE(spec$random_diagonal)) 
            list()
        else lapply(seq_len(nrow(pairs)), function(p) {
            a <- pairs[p, 1L]
            b <- pairs[p, 2L]
            cbind(data.frame(class = classes[k], parameter = "correlation", term = paste(terms[a], terms[b], sep = ":"), stringsAsFactors = FALSE), .growth_delta_table(inference, function(v) {
                covariance <- covariance_of(v, k)
                covariance[a, b]/sqrt(covariance[a, a] * covariance[b, b])
            }, "atanh", level))
