function(x, level, inference) {
    spec <- x$spec
    template <- x$params
    classes <- .growth_class_names(x)
    posterior <- x$expectation$posterior
    weights <- spec$sampling_weights %||% rep(1, nrow(posterior))
    modal <- max.col(posterior, ties.method = "first")
    shares <- do.call(rbind, lapply(seq_along(classes), function(k) {
        .growth_delta_table(inference, function(v) {
            prior <- .growth_class_prior(spec, .growth_unpack(spec, v, template))
            sum(weights * prior[, k])/sum(weights)
        }, "logit", level)
    }))
    sigma <- do.call(rbind, lapply(seq_along(classes), function(k) {
        .growth_delta_table(inference, function(v) {
            sqrt(.growth_unpack(spec, v, template)$sigma2[k])
        }, "log", level)
    }))
    average <- vapply(seq_along(classes), function(k) {
        if (!any(modal == k)) 
            NA_real_
        else mean(posterior[modal == k, k])
    }, numeric(1))
    data.frame(class = classes, share = shares$estimate, share_std_error = shares$std_error, share_conf_low = shares$conf_low, share_conf_high = shares$conf_high, expected_persons = colSums(posterior * weights), assigned_persons = tabulate(modal, length(classes)), average_posterior = average, residual_sd = sigma$estimate, residual_sd_std_error = sigma$std_error, stringsAsFactors = FALSE)
}

