function(x, level, inference) {
    theta <- inference$theta
    se <- sqrt(pmax(diag(inference$vcov), 0))
    picked <- startsWith(names(theta), "membership.") | startsWith(names(theta), "group_membership.")
    if (!any(picked)) {
        return(data.frame(class = character(), term = character(), estimate = numeric(), std_error = numeric(), statistic = numeric(), p_value = numeric(), conf_low = numeric(), conf_high = numeric()))
    }
    parts <- strsplit(sub("^(group_)?membership\\.", "", names(theta)[picked]), ".", fixed = TRUE)
    data.frame(class = vapply(parts, `[`, character(1), 1L), term = vapply(parts, function(p) paste(p[-1L], collapse = "."), character(1)), .inference_wald(unname(theta[picked]), unname(se[picked]), level), stringsAsFactors = FALSE)
}

