function(x, level, inference) {
    spec <- x$spec
    structure <- .growth_structure(spec)
    if (identical(structure$nesting, "observation")) {
        return(data.frame(group_class = character(), class = character(), probability = numeric(), group_share = numeric()))
    }
    rho <- x$expectation$structure$rho
    n_group_classes <- structure$n_group_classes
    group_names <- paste0("group_class_", seq_len(n_group_classes))
    classes <- .growth_class_names(x)
    probabilities <- function(params, cluster_weights) {
        matrix(vapply(seq_len(n_group_classes), function(h) {
            prior <- exp(.mixture_log_softmax(.mixture_two_level_design(structure, h), params$class_logits))
            weight <- cluster_weights[structure$group_index, h]
            colSums(prior * weight)/sum(weight)
        }, numeric(spec$n_classes)), spec$n_classes)
    }
    estimate <- probabilities(x$params, rho)
    standard_error <- if (ncol(structure$w) == 0L && !is.null(inference)) {
        .mixture_delta(inference$theta, inference$vcov, function(v) {
            as.vector(probabilities(.growth_unpack(spec, v, x$params), rho))
        })$std_error
    }
    else rep(NA_real_, length(estimate))
    data.frame(group_class = rep(group_names, each = spec$n_classes), class = rep(classes, n_group_classes), probability = as.vector(estimate), std_error = standard_error, group_share = rep(colMeans(rho), each = spec$n_classes), assigned_clusters = rep(tabulate(max.col(rho, ties.method = "first"), n_group_classes), each = spec$n_classes), stringsAsFactors = FALSE)
}

