function(x, digits = 4L, ...) {
    fit <- .growth_fit_table(x)
    random <- paste("random", .growth_random_description(x$spec))
    covariance <- switch(fit$random_covariance, varying = "class-specific", equal = "shared across classes", proportional = "proportional across classes")
    if (is.null(x$spec$cluster)) {
        cat("Growth mixture model\n")
        cat(sprintf("  %d classes, %d persons, %d observations\n", fit$n_classes, fit$n_persons, fit$n_observations))
    }
    else {
        cat("Multilevel growth mixture model\n")
        cat(sprintf("  %d classes and %d group classes; %d clusters, %d persons, %d observations\n", fit$n_classes, fit$n_group_classes, fit$n_clusters, fit$n_persons, fit$n_observations))
    }
    cat(sprintf("  %s%s, covariance %s; residual variance %s\n", toupper(substr(random, 1L, 1L)), substring(random, 2L), covariance, if (identical(fit$residual_variance, "equal")) 
        "shared"
    else "by class"))
    if (.growth_is_correlated(x$spec)) {
        process <- x$params$correlation
        cat(sprintf("  Correlated residuals: %s over `%s`%s, sd %.*f\n", if (identical(x$spec$residual_correlation, "ar")) 
            "continuous-time autoregressive"
        else "Brownian motion", x$spec$residual_time, if (identical(x$spec$residual_correlation, "ar")) 
            sprintf(", rate %.*f", digits, process[["rate"]])
        else "", digits, process[["sd"]]))
    }
    .latents_print_weights(x)
    cat(sprintf("  Log likelihood %.2f, BIC %.2f, entropy %.2f, %s\n", fit$log_likelihood, fit$bic, fit$entropy, if (fit$converged) 
        "converged"
    else "NOT converged"))
    cat("\n")
    print(get_results(x, "classes"))
    if (!is.null(x$spec$cluster)) {
        cat("\n")
        print(get_results(x, "group_classes"))
    }
    cat("\n")
    print(get_results(x, "coefficients"))
    if (isTRUE(x$random_boundary)) {
        cat(paste0("\nNote: a random-effect covariance is degenerate or a residual variance", " is at its floor (see the warning at fit).\n"))
    }
    cat("\nMore: get_results(x, \"random\"), plot(x), summary(x)\n")
    invisible(x)
}

