    adjust <- match.arg(adjust)
    method <- match.arg(method)
    boundary <- match.arg(boundary)
    .multilpa_check_seed(seed)
    if (!is.null(data)) 
        .trajectory_check_data(x, data)
    if (!isTRUE(x$converged)) {
        stop(errorCondition("The fit did not converge; infer from it only once it has.", class = "latents_no_converge", call = NULL))
    }
    natural <- .growth_natural_parameters(x)
    if (any(natural$degenerate) && identical(boundary, "error")) {
        stop(errorCondition(paste("A random-effect covariance is degenerate, so its parameters sit on a", "bound and have no Wald or bootstrap distribution worth reporting. Use", "`boundary = \"fix\"` to report the other parameters."), class = "latents_boundary_fit", call = NULL))
    }
    if (identical(method, "bootstrap")) {
        result <- .mixture_with_seed(seed, .growth_bootstrap_inference(x, natural, level, as.integer(iter), n_starts, max_iter, tol, adjust))
    }
    else {
        vcov_type <- if (missing(vcov_type)) 
            NULL
        else match.arg(vcov_type)
        inference <- .growth_resolve_inference(x, vcov_type)
        spec <- x$spec
        rows <- lapply(seq_len(nrow(natural$labels)), function(row) {
            .growth_delta_table(inference, function(v) {
                natural$values(.growth_unpack(spec, v, x$params), spec)[row]
            }, natural$scales[row], level)
        })
        wald <- do.call(rbind, rows)
        statistic <- ifelse(natural$tested & wald$std_error > 0, wald$estimate/wald$std_error, NA_real_)
        result <- data.frame(natural$labels, estimate = wald$estimate, standard_error = wald$std_error, statistic = statistic, p_value = 2 * stats::pnorm(-abs(statistic)), p_adjusted = NA_real_, conf_low = wald$conf_low, conf_high = wald$conf_high, row.names = NULL, stringsAsFactors = FALSE)
        attributes(result) <- c(attributes(result), list(covariance_unconstrained = inference$vcov, level = level, method = "wald", vcov_type = inference$vcov_type, adjust = adjust))
    }
    result[natural$degenerate, c("standard_error", "statistic", "p_value", "conf_low", "conf_high")] <- NA_real_
    result$p_adjusted <- stats::p.adjust(result$p_value, method = adjust)
    result
}

