    }
    caption <- paste(c(sprintf("Line and dark band: class mean trajectory and its %s%% confidence band.", format(100 * level)), if (!is.null(spread_band)) sprintf("Light band: where %s%% of the class's persons' trajectories lie.", format(100 * spread)), if (!is.null(means)) "Points: observed class means (posterior-weighted) with intervals.", if (nrow(observed) > 0L) "Thin lines: persons, coloured by their most likely class."), collapse = "\n")
    plot <- ggplot2::ggplot() + layers + .growth_scales(key) + ggplot2::scale_x_continuous(expand = ggplot2::expansion(mult = c(0.01, 0.01))) + ggplot2::labs(x = time, y = x$spec$response_name) + .gg_theme()
    description <- if (inherits(x, "latents_growth_mixture")) {
