function(object, newdata, with_response) {
    spec <- object$spec
    new <- .mixture_prediction_data(.mixture_new_spec(object, newdata, with_response))
    random_frame <- .mixture_prediction_data(stats::model.frame(spec$random, newdata, na.action = stats::na.fail))
    new$random_design <- stats::model.matrix(spec$random, random_frame)
    if (!identical(colnames(new$random_design), colnames(spec$random_design)) || any(!is.finite(new$random_design))) {
        stop(errorCondition(paste("The random-effects design of `newdata` must be finite and have the", "fitted columns."), class = "latents_bad_data", call = NULL))
    }
    new$sampling_weights <- NULL
    new$row_weights <- NULL
    if (.growth_is_correlated(spec)) {
        times <- newdata[[spec$residual_time]]
        if (is.null(times) || anyNA(times) || any(!is.finite(times))) {
            stop(errorCondition(sprintf("`newdata` needs the residual time column `%s`, finite on every row.", spec$residual_time), class = "latents_bad_data", call = NULL))
        }
        new$residual_times <- times
    }
    if (!is.null(spec$cluster)) {
        if (!spec$cluster %in% names(newdata) || anyNA(newdata[[spec$cluster]])) {
            stop(errorCondition(sprintf("`newdata` needs the cluster column `%s`, without missing values.", spec$cluster), class = "latents_bad_data", call = NULL))
        }
        blueprint <- spec$group_membership_design
        frame <- .mixture_prediction_data(stats::model.frame(blueprint$terms, newdata, xlev = blueprint$xlevels, na.action = stats::na.fail))
        row_group <- stats::model.matrix(blueprint$terms, frame, contrasts.arg = blueprint$contrasts)
        row_membership <- new$w[new$group_index, , drop = FALSE]
        new <- utils::modifyList(new, .growth_cluster_spec(newdata[[spec$cluster]], new$group_index, row_membership, row_group, spec$n_cluster_classes, check_count = FALSE))
    }
    new
}

