function(object, newdata = NULL, type = c("response", "class_response", "posterior", "conditional", "class_conditional", "random_effects"), ...) {
    type <- match.arg(type)
    .latents_warn_unused_arguments(list(...), "predict()", "A growth mixture prediction takes `newdata` and `type`.")
    with_response <- type %in% c("posterior", "conditional", "class_conditional", "random_effects")
    spec <- if (is.null(newdata)) 
        object$spec
    else .growth_new_spec(object, newdata, with_response)
    params <- object$params
    classes <- .growth_class_names(object)
    means <- .growth_class_means(spec, params)
    person <- spec$group_index
    if (type %in% c("response", "class_response")) {
        priors <- .growth_class_prior(spec, params)[person, , drop = FALSE]
        if (identical(type, "response")) {
            return(data.frame(row = spec$kept_rows, fitted = rowSums(priors * means)))
        }
        return(data.frame(row = rep(spec$kept_rows, spec$n_classes), class = rep(classes, each = spec$n), prior = as.vector(priors), fitted = as.vector(means), stringsAsFactors = FALSE))
    }
    expectation <- if (is.null(newdata)) 
        object$expectation
    else .growth_expectation(spec, .growth_statistics(spec), params)
    if (identical(type, "posterior")) {
        refit <- object
        refit$spec <- spec
        refit$expectation <- expectation
        return(.growth_assignment_table(refit))
    }
    posterior <- expectation$posterior
    if (identical(type, "random_effects")) {
        terms <- colnames(spec$random_design)
        effects <- do.call(rbind, expectation$means)
        out <- data.frame(id = rep(spec$group_levels, spec$n_classes), class = rep(classes, each = spec$n_groups), posterior = as.vector(posterior), matrix(effects, ncol = length(terms)), stringsAsFactors = FALSE)
        names(out) <- c(spec$id, "class", "posterior", terms)
        return(out)
    }
    own <- matrix(vapply(seq_len(spec$n_classes), function(k) {
        rowSums(spec$random_design * expectation$means[[k]][person, , drop = FALSE])
    }, numeric(spec$n)), spec$n, spec$n_classes) + means
    row_posterior <- posterior[person, , drop = FALSE]
    if (identical(type, "conditional")) {
        return(data.frame(row = spec$kept_rows, fitted = rowSums(row_posterior * own)))
    }
    data.frame(row = rep(spec$kept_rows, spec$n_classes), class = rep(classes, each = spec$n), posterior = as.vector(row_posterior), fitted = as.vector(own), stringsAsFactors = FALSE)
}

