function(random, family, id, class_level, n_group_classes, random_diagonal, cluster = NULL) {
    bad_argument <- function(message) {
        stop(errorCondition(message, class = "latents_bad_argument", call = NULL))
    }
    if (is.null(random)) {
        bad_argument(paste("`cluster` nests persons in clusters for the multilevel growth mixture", "model, which needs random effects within classes: give `random`, for", "example `random = \"intercept\"`."))
    }
    if (!inherits(random, "formula") || length(random) != 2L) {
        bad_argument("`random` must be a one-sided formula such as `~ 1 + time`.")
    }
    if (!identical(family, "gaussian")) {
        bad_argument(paste("Random effects within classes are implemented for the gaussian family;", "binomial and Poisson growth mixtures need numerical integration and", "are not supported yet."))
    }
    if (is.null(id) || !identical(class_level, "group")) {
        bad_argument(paste("A growth mixture model classifies persons: pass `id` naming the", "persons and `class_level = \"group\"`."))
    }
    if (n_group_classes > 1L && is.null(cluster)) {
        bad_argument(paste("Group classes of a growth mixture are classes of clusters of persons:", "pass `cluster` naming the clusters (schools, say) the persons are in."))
    }
    if (!is.null(cluster) && identical(cluster, id)) {
        bad_argument("`cluster` must name a different column from `id`.")
    }
    if (!is.logical(random_diagonal) || length(random_diagonal) != 1L || is.na(random_diagonal)) {
        bad_argument("`random_diagonal` must be TRUE or FALSE.")
    }
    invisible(NULL)
}

