function(x, parameters, codes = NULL, extra = NULL, noise_log_density = NULL, offset = TRUE, n_profiles = nrow(parameters$means), constant = "separate") {
    x <- .latents_direct_shift(x, extra, parameters)
    gaussian <- if (ncol(x) > 0L && (anyNA(x) || !is.null(parameters$covariances))) {
        .multilpa_gaussian_moments(x, parameters)
    }
    else NULL
    log_density <- if (!is.null(gaussian)) 
        gaussian$log_density
    else .latents_gaussian_log_density(x, parameters$means, parameters$variances, constant)
    if (!is.null(noise_log_density)) 
        log_density <- cbind(log_density, noise_log_density)
    row_offset <- rep(0, nrow(x))
    if (offset) {
        row_offset <- .multilpa_row_max(log_density)
        if (any(!is.finite(row_offset))) {
            stop("All component densities vanished, or a density overflowed.")
        }
        log_density <- sweep(log_density, 1L, row_offset, "-")
    }
    if (!is.null(codes)) {
        log_density <- log_density + .multilpa_categorical_log_density(codes, parameters$response_probabilities)
    }
    if (!is.null(extra)) {
        log_density <- log_density + .latents_extra_log_density(extra, parameters, nrow(x), n_profiles)
    }
    list(log_density = log_density, offset = row_offset, moments = gaussian$moments)
}

