function(state, evaluate, maximize, max_iter, tol, settings = .latents_em_settings(), pause = Inf, resume = NULL) {
    if (is.null(resume)) {
        expectation <- evaluate(state)
        history <- expectation$log_likelihood
        converged <- FALSE
        settled <- FALSE
        stalled <- 0L
        iteration <- 0L
        ended <- FALSE
    }
    else {
        state <- resume$state
        expectation <- resume$expectation %||% evaluate(state)
        history <- resume$history
        converged <- resume$converged
        settled <- resume$settled
        stalled <- resume$stalled
        iteration <- resume$iterations
        ended <- resume$ended
    }
    step <- function(point, point_expectation) {
        .latents_em_step(point, point_expectation, evaluate, maximize, settings)
    }
    while (!ended && iteration < max_iter && iteration < pause && !converged && stalled < settings$max_stalled) {
        accelerate <- !is.null(settings$accelerate) && max_iter - iteration >= 3L
        if (accelerate) {
            cycle <- .latents_squarem_cycle(step, state, expectation, evaluate, settings$accelerate)
            evaluations <- 3L
        }
        else {
            plain <- step(state, expectation)
            if (!plain$finite) {
                state <- plain$state
                ended <- TRUE
                break
            }
            cycle <- list(state = plain$state, expectation = plain$expectation, history = plain$expectation$log_likelihood)
            evaluations <- 1L
        }
        gain <- cycle$expectation$log_likelihood - expectation$log_likelihood
        settled <- abs(gain) <= tol * (1 + abs(expectation$log_likelihood))
        solved <- attr(cycle$state, "solved") %||% TRUE
        converged <- settled && isTRUE(solved)
        stalled <- if (settled && !isTRUE(solved)) 
            stalled + 1L
        else 0L
        iteration <- iteration + evaluations
        history <- c(history, cycle$history)
        state <- cycle$state
        expectation <- cycle$expectation
    }
    fit <- list(state = state, expectation = expectation, converged = converged, iterations = iteration, history = history, settled = settled)
    if (is.finite(pause) || !is.null(resume)) {
        fit$checkpoint <- list(state = state, history = history, converged = converged, settled = settled, stalled = stalled, iterations = iteration, ended = ended)
        if (ended) 
            fit$checkpoint$expectation <- expectation
    }
    fit
}

