            cycle <- list(state = plain$state, expectation = plain$expectation, history = plain$expectation$log_likelihood)
            evaluations <- 1L
        }
        gain <- cycle$expectation$log_likelihood - expectation$log_likelihood
        settled <- abs(gain) <= tol * (1 + abs(expectation$log_likelihood))
        solved <- attr(cycle$state, "solved") %||% TRUE
        converged <- settled && isTRUE(solved)
        stalled <- if (settled && !isTRUE(solved)) 
            stalled + 1L
        else 0L
        iteration <- iteration + evaluations
        history <- c(history, cycle$history)
        state <- cycle$state
        expectation <- cycle$expectation
    }
    fit <- list(state = state, expectation = expectation, converged = converged, iterations = iteration, history = history, settled = settled)
    if (is.finite(pause) || !is.null(resume)) {
        fit$checkpoint <- list(state = state, history = history, converged = converged, settled = settled, stalled = stalled, iterations = iteration, ended = ended)
        if (ended) 
            fit$checkpoint$expectation <- expectation
    }
    fit
}

