function(step, state, expectation, evaluate, accelerator) {
    first <- step(state, expectation)
    second <- step(first$state, first$expectation)
    theta0 <- accelerator$flatten(state)
    r <- accelerator$flatten(first$state) - theta0
    v <- accelerator$flatten(second$state) - theta0 - 2 * r
    plain <- list(state = second$state, expectation = second$expectation, history = c(first$expectation$log_likelihood, second$expectation$log_likelihood, second$expectation$log_likelihood), accelerated = FALSE)
    norm_v <- sqrt(sum(v^2))
    if (!is.finite(norm_v) || norm_v <= 0) 
        return(plain)
    alpha <- min(-1, -sqrt(sum(r^2))/norm_v)
    candidate <- NULL
    tries <- 0L
    while (is.null(candidate) && alpha < -1 && tries < 30L) {
        theta <- theta0 - 2 * alpha * r + alpha^2 * v
        proposal <- accelerator$restore(state, theta)
        if (accelerator$valid(proposal)) 
            candidate <- proposal
        else alpha <- (alpha - 1)/2
        tries <- tries + 1L
