    continued <- worker_report$collect(function() {
        .latents_map_candidates(finalists, function(start_index) {
            .latents_start_attempt(run, start_index, NULL, resume = screened[[start_index]]$checkpoint)
        }, cores)
    })
    .latents_select_screened(screened, continued, finalists, ranked$screened_scores, select_start, score, interior)
