        if (is.null(attempt$error)) 
            score(attempt)
        else -Inf
    }, numeric(1))
    usable <- screened_valid & is.finite(screened_scores)
    if (!any(usable)) {
        stop(.latents_start_failure(sprintf("All %d starts failed: %s", screen$n_pool, paste(unique(vapply(screened[!screened_valid], `[[`, character(1), "error")), collapse = "; ")), screened))
    }
    protected <- intersect(screen$protect %||% integer(), pool[usable])
    ranked <- setdiff(pool[usable][order(-screened_scores[usable], pool[usable])], protected)
    finalists <- utils::head(c(protected, ranked), n_starts)
    list(finalists = finalists, screened_scores = screened_scores)
}

