function(screened, continued, finalists, screened_scores, select_start, score = function(attempt) {
    attempt$expectation$log_likelihood
}, interior = NULL) {
    pool <- seq_along(screened)
    attempts <- lapply(screened, function(attempt) {
        attempt$checkpoint <- NULL
        attempt
    })
    attempts[finalists] <- lapply(continued, function(attempt) {
        attempt$checkpoint <- NULL
        attempt
    })
    stage <- ifelse(pool %in% finalists, "final", "screened")
    valid <- vapply(attempts, function(attempt) is.null(attempt$error), logical(1))
    final_valid <- valid & stage == "final"
    if (!any(final_valid)) {
        stop(.latents_start_failure(sprintf("All %d starts carried to the end failed: %s", length(finalists), paste(unique(vapply(attempts[finalists], `[[`, character(1), "error")), collapse = "; ")), c(screened, continued)))
    }
    scores <- vapply(seq_along(attempts), function(start_index) {
        attempt <- attempts[[start_index]]
        if (!valid[start_index]) 
            -Inf
        else if (final_valid[start_index]) 
            score(attempt)
        else attempt$expectation$log_likelihood
    }, numeric(1))
    converged <- vapply(attempts, function(attempt) isTRUE(attempt$converged), logical(1))
    eligible_scores <- ifelse(final_valid, scores, -Inf)
    flags <- if (!is.null(interior)) {
        vapply(seq_along(attempts), function(start_index) {
            final_valid[start_index] && isTRUE(interior(attempts[[start_index]]))
        }, logical(1))
    }
    result <- list(attempts = attempts, valid = valid, scores = scores, converged = converged, stage = stage, screened_scores = screened_scores, best_start = .multilpa_select_start(eligible_scores, converged & final_valid, select_start, flags))
    logs <- lapply(c(screened, continued), attr, which = "lta_structure_log")
    if (any(!vapply(logs, is.null, logical(1)))) 
        attr(result, "lta_structure_logs") <- logs
    result
}

