function(theta, lower, value, gradient, tol, control) {
    theta <- pmax(theta, lower)
    start_value <- value(theta)
    found <- stats::optim(theta, value, gradient, method = "L-BFGS-B", lower = lower, control = control)
    if (!is.finite(found$value) || found$value > start_value) {
        return(list(par = theta, value = start_value, converged = FALSE, improved = FALSE, start_value = start_value))
    }
    converged <- found$convergence == 0L
    if (identical(found$convergence, 52L)) {
        again <- stats::optim(found$par, value, gradient, method = "L-BFGS-B", lower = lower, control = control)
        if (is.finite(again$value) && again$value <= found$value) {
            converged <- again$convergence == 0L || found$value - again$value <= tol * (1 + abs(again$value))
            found <- again
        }
    }
    list(par = found$par, value = found$value, converged = converged, improved = TRUE, start_value = start_value)
}

