function(spec, values, template) {
    k <- spec$n_classes
    position <- 0L
    take <- function(count) {
        taken <- values[position + seq_len(count)]
        position <<- position + count
        unname(taken)
    }
    params <- template
    if (identical(spec$nesting, "two-level")) {
        params$delta[] <- cbind(0, matrix(take(ncol(spec$v) * (spec$n_group_classes - 1L)), ncol(spec$v)))
        params$class_logits[] <- cbind(0, matrix(take(nrow(template$class_logits) * (k - 1L)), nrow(template$class_logits)))
