    condition <- function(parts) {
        diagonal <- diag(parts$information)
        if (any(!is.finite(diagonal) | diagonal <= 0)) {
            stop(errorCondition("The Vuong comparison information is not positive definite.", class = "latents_singular_information", call = NULL))
        }
        scale <- 1/sqrt(diagonal)
        parts$scores <- sweep(parts$scores, 2L, scale, "*")
        parts$information <- parts$information * tcrossprod(scale)
        parts
    }
    alternative$score_gram <- identical(unname(alternative$information), unname(crossprod(alternative$scores)))
    null$score_gram <- identical(unname(null$information), unname(crossprod(null$scores)))
    alternative <- condition(alternative)
    null <- condition(null)
    unresolved <- function() {
        stop(errorCondition(paste("The Vuong reference weights cannot be resolved reliably in these coordinates;", "the comparison probability cannot be reported."), class = "latents_inaccurate_probability", call = NULL))
    }
