                epsilon <- .Machine$double.eps
                rank_error <- max(dim(parts$scores)) * epsilon * max(decomposition$d)
                if (length(decomposition$d) < ncol(parts$scores) || min(decomposition$d) <= rank_error) 
                  unresolved()
                span_error <- rank_error/min(decomposition$d)
                return(list(scores = decomposition$u, weight_error = 2 * span_error/(1 - span_error)))
            }
