            inverse <- backsolve(root, diag(ncol(root)))
            scores <- t(backsolve(root, t(parts$scores), transpose = TRUE))
            columns <- ncol(root)
            epsilon <- .Machine$double.eps
            gamma <- columns * epsilon/(1 - columns * epsilon)
            chol_gamma <- (columns + 1) * epsilon/(1 - (columns + 1) * epsilon)
            information_error <- chol_gamma * crossprod(abs(root)) + (2 * epsilon/(1 - 2 * epsilon)) * abs(parts$information)
            relative_error <- norm(crossprod(abs(inverse), information_error %*% abs(inverse)), "2")
            if (!is.finite(relative_error) || relative_error >= 1) {
                stop("Information whitening cannot resolve the fitted coordinates.")
            }
            score_norm <- norm(scores, "2")
            score_error <- gamma * norm(abs(scores) %*% abs(root) %*% abs(inverse), "2") + epsilon * norm(abs(parts$scores) %*% abs(inverse), "2")
            weight_error <- score_norm^2 * relative_error/(1 - relative_error) + 2 * score_norm * score_error + score_error^2
            if (!is.finite(weight_error)) 
                unresolved()
