function(local_dependence) {
    refuse <- function(message) {
        stop(errorCondition(message, class = "latents_bad_argument", call = NULL))
    }
    if (!(is.character(local_dependence) && !anyNA(local_dependence))) {
        refuse("`local_dependence` names pairs of indicators, such as \"item1:item2\".")
    }
    parts <- strsplit(local_dependence, ":", fixed = TRUE)
    if (!all(lengths(parts) == 2L) || any(!nzchar(unlist(parts)))) {
        refuse(sprintf(paste("Each pair in `local_dependence` is two indicator names joined by a colon,", "such as \"item1:item2\"; %s is not."), paste(sprintf("\"%s\"", local_dependence[lengths(parts) != 2L | vapply(parts, function(p) any(!nzchar(p)), logical(1))]), collapse = ", ")))
    }
    pairs <- data.frame(item_1 = vapply(parts, `[[`, "", 1L), item_2 = vapply(parts, `[[`, "", 2L), stringsAsFactors = FALSE)
    pairs$name <- paste(pairs$item_1, pairs$item_2, sep = ":")
    if (any(pairs$item_1 == pairs$item_2)) 
        refuse("A pair in `local_dependence` names one indicator twice.")
    items <- c(pairs$item_1, pairs$item_2)
    if (anyDuplicated(items) > 0L) {
        refuse(sprintf(paste("An indicator can be in one pair of `local_dependence` only; %s is in more.", "A dependence among three items needs their joint table."), paste(sprintf("`%s`", unique(items[duplicated(items)])), collapse = ", ")))
    }
    pairs
}

