function(pairs, vars, categorical, ordinal, count, conflicts) {
    continuous <- setdiff(vars, c(categorical, ordinal, count))
    items <- c(pairs$item_1, pairs$item_2)
    absent <- setdiff(items, continuous)
    if (length(absent) > 0L) {
        stop(errorCondition(sprintf(paste("`local_dependence` names %s, which %s not a continuous indicator among", "`vars`; pair two categorical items, or two continuous ones."), paste(sprintf("`%s`", absent), collapse = ", "), if (length(absent) > 1L) 
            "are"
        else "is"), class = "latents_bad_argument", call = NULL))
    }
    if (any(conflicts)) {
        stop(errorCondition(sprintf(paste("A covariance for chosen pairs of continuous indicators sets the", "covariance itself; it is not combined with %s."), paste(sprintf("`%s`", names(conflicts)[conflicts]), collapse = ", ")), class = "latents_bad_argument", call = NULL))
    }
    pattern <- diag(length(continuous)) > 0
    dimnames(pattern) <- list(continuous, continuous)
    pattern[cbind(pairs$item_1, pairs$item_2)] <- TRUE
    pattern[cbind(pairs$item_2, pairs$item_1)] <- TRUE
    pattern
}

