function(data, pairs, min_categories = 0L, rebuild_existing = FALSE) {
    if (!is.null(pairs$kind)) 
        pairs <- pairs[pairs$kind == "categorical", , drop = FALSE]
    joined <- Reduce(function(frame, index) {
        pair <- pairs[index, ]
        has_items <- all(c(pair$item_1, pair$item_2) %in% names(frame))
        prepared <- pair$name %in% names(frame) && identical(attr(frame[[pair$name]], "latents_pair"), c(pair$item_1, pair$item_2))
        if (pair$name %in% names(frame) && !has_items && (!any(c(pair$item_1, pair$item_2) %in% names(frame)) || prepared)) 
            return(frame)
        if (!has_items) {
            stop(errorCondition(sprintf("`data` needs `%s` and `%s` for the pair \"%s\" of `local_dependence`.", pair$item_1, pair$item_2, pair$name), class = "latents_bad_data", call = NULL))
        }
        first <- frame[[pair$item_1]]
        second <- frame[[pair$item_2]]
        first_levels <- .multilpa_categorical_levels(first, pair$item_1, min_categories)
        second_levels <- .multilpa_categorical_levels(second, pair$item_2, min_categories)
        colons <- Filter(function(item) {
            any(grepl(":", unique(as.character(frame[[item]])), fixed = TRUE))
        }, c(pair$item_1, pair$item_2))
        if (length(colons) > 0L) {
            stop(errorCondition(sprintf(paste("The categories of %s contain \":\", which joins the two items of the", "pair \"%s\"; recode them without a colon."), paste(sprintf("`%s`", colons), collapse = " and "), pair$name), class = "latents_bad_data", call = NULL))
        }
        observed <- !is.na(first) & !is.na(second)
        labels <- ifelse(observed, paste(as.character(first), as.character(second), sep = ":"), NA_character_)
        frame_pairs <- attr(frame, "latents_pairs")
        prepared <- prepared || (pair$name %in% names(frame) && identical(frame_pairs[[pair$name]], c(pair$item_1, pair$item_2)) && is.factor(frame[[pair$name]]) && identical(as.character(frame[[pair$name]]), labels))
        if (pair$name %in% names(frame) && !prepared && !rebuild_existing) {
            stop(errorCondition(sprintf(paste("The generated joint indicator `%s` conflicts with an existing column;", "rename that column before using `local_dependence`."), pair$name), class = "latents_bad_data", call = NULL))
        }
        partial <- xor(is.na(first), is.na(second))
        if (any(partial)) {
            warning(warningCondition(sprintf(paste("%d rows observe only one item of the pair \"%s\"; the pair is treated", "as missing in those rows."), sum(partial), pair$name), class = "latents_partial_pair", call = NULL))
        }
        grid <- expand.grid(second = as.character(second_levels), first = as.character(first_levels), stringsAsFactors = FALSE)
        combinations <- paste(grid$first, grid$second, sep = ":")
        frame[[pair$name]] <- factor(labels, levels = combinations)
        attr(frame[[pair$name]], "latents_pair") <- c(pair$item_1, pair$item_2)
        frame_pairs[[pair$name]] <- c(pair$item_1, pair$item_2)
        attr(frame, "latents_pairs") <- frame_pairs
        frame
    }, seq_len(nrow(pairs)), init = data)
    joined
}

