function(call, env, local_dependence) {
    pairs <- .latents_parse_pairs(local_dependence)
    arguments <- mget(setdiff(names(call)[-1L], "local_dependence"), envir = env)
    if (!is.null(arguments$family) && !identical(arguments$family, "profiles")) {
        stop(errorCondition(paste("`local_dependence` pairs the indicators of a profile or class model;", "the group-class families have no categorical items to pair."), class = "latents_bad_argument", call = NULL))
    }
    items <- c(pairs$item_1, pairs$item_2)
    categorical <- arguments$categorical %||% character()
    if (anyNA(arguments$vars) || anyDuplicated(arguments$vars) || !all(arguments$vars %in% names(arguments$data)) || any(arguments$id %in% arguments$vars)) {
        stop(errorCondition("Supply unique existing indicators and a distinct group column.", class = "latents_bad_data", call = NULL))
    }
    if (anyDuplicated(categorical) || !all(categorical %in% arguments$vars)) {
        stop(errorCondition("`categorical` must name distinct indicators listed in `vars`.", class = "latents_bad_categorical", call = NULL))
    }
    absent <- setdiff(items, arguments$vars)
    if (length(absent) > 0L) {
        stop(errorCondition(sprintf("`local_dependence` names %s, which %s not among `vars`.", paste(sprintf("`%s`", absent), collapse = ", "), if (length(absent) > 1L) 
            "are"
        else "is"), class = "latents_bad_argument", call = NULL))
    }
    pairs <- .latents_classify_pairs(pairs, categorical)
    covariates <- c(arguments$profile_covariates, arguments$group_covariates, if (length(arguments$direct_effects) > 0L) .latents_parse_direct_effects(arguments$direct_effects)$covariate)
    reused <- intersect(covariates, items)
    if (length(reused) > 0L) {
        stop(errorCondition(sprintf("%s %s an indicator of a `local_dependence` pair, so it cannot also be a covariate.", paste(sprintf("`%s`", reused), collapse = ", "), if (length(reused) > 1L) 
            "are"
        else "is"), class = c("multilpa_indicator_reused", "latents_bad_covariate"), call = NULL))
    }
    joined_pairs <- pairs[pairs$kind == "categorical", , drop = FALSE]
    continuous_pairs <- pairs[pairs$kind == "continuous", , drop = FALSE]
    arguments$local_dependence <- if (nrow(continuous_pairs) > 0L) 
        continuous_pairs$name
    arguments$data <- .latents_join_pairs(arguments$data, joined_pairs, min_categories = 2L)
    categories <- lapply(stats::setNames(seq_len(nrow(joined_pairs)), joined_pairs$name), function(index) {
        first <- as.character(arguments$data[[joined_pairs$item_1[index]]])
        second <- as.character(arguments$data[[joined_pairs$item_2[index]]])
        label <- as.character(arguments$data[[joined_pairs$name[index]]])
        unique(data.frame(label = label, level_1 = first, level_2 = second, stringsAsFactors = FALSE)[!is.na(label), , drop = FALSE])
    })
    original <- list(vars = arguments$vars, categorical = categorical)
    arguments$vars <- .latents_joined_names(arguments$vars, joined_pairs)
    arguments$categorical <- .latents_joined_names(categorical, joined_pairs)
    fit <- do.call(multilpa, arguments)
    fit$local_dependence <- pairs
    fit$local_dependence_categories <- categories
    fit$original_vars <- original$vars
    fit$original_categorical <- original$categorical
    fit$call <- call
    fit
}

