function(x, data, level, iter, n_starts, max_iter, tol, adjust) {
    if (is.null(data)) {
        stop(errorCondition(paste("The bootstrap for a transition model needs `data`: each resample keeps", "its persons' occasions and covariates."), class = "latents_bad_argument", call = NULL))
    }
    .lta_check_data(x, data)
    if (!isTRUE(x$converged)) {
        stop(errorCondition("The original fit did not converge; bootstrap it only once it has.", class = "latents_no_converge", call = NULL))
    }
    table <- .lta_bootstrap_frame(x)
    drawn <- .lta_bootstrap_replicates(x, data, iter, n_starts, max_iter, tol, table$name)
    valid <- stats::complete.cases(drawn$estimates)
    if (sum(valid) < 2L) {
        reasons <- drawn$messages[!is.na(drawn$messages)]
        stop(errorCondition(sprintf("Only %d of %d resamples produced a usable fit; the first reason was: %s", sum(valid), iter, if (length(reasons) > 0L) 
            reasons[1L]
        else "no reason was recorded"), class = "latents_bootstrap_failed", call = NULL))
    }
    if (sum(valid) < iter) {
        warning(warningCondition(sprintf("%d of %d resamples did not produce a usable fit and were dropped.", iter - sum(valid), iter), class = "latents_bootstrap_dropped", call = NULL))
    }
    kept <- drawn$estimates[valid, , drop = FALSE]
    quantiles <- apply(kept, 2L, stats::quantile, probs = c((1 - level)/2, (1 + level)/2), names = FALSE)
    table$standard_error <- apply(kept, 2L, stats::sd)
    table$statistic <- NA_real_
    table$p_value <- NA_real_
    table$p_adjusted <- NA_real_
    table$conf_low <- quantiles[1L, ]
    table$conf_high <- quantiles[2L, ]
    covariance <- stats::cov(kept)
    dimnames(covariance) <- list(table$name, table$name)
    columns <- setdiff(names(table), "name")
    result <- table[, columns, drop = FALSE]
    row.names(result) <- NULL
    structure(result, covariance = covariance, covariance_unconstrained = NULL, level = level, method = "bootstrap", iter = iter, n_valid = sum(valid), replicates = kept, messages = drawn$messages, adjust = adjust)
}

