        }, numeric(n)), n, length(continuous), dimnames = list(NULL, continuous)))
    }
    noise <- matrix(stats::rnorm(n * length(continuous)), n, length(continuous))
    correlated <- Reduce(function(drawn, k) {
        rows <- which(profile == k)
        if (length(rows) == 0L) 
            return(drawn)
        covariance <- block$covariances[, , k]
        if (!is.null(rownames(covariance))) 
            covariance <- covariance[continuous, continuous]
        factor <- chol(covariance)
        drawn[rows, ] <- noise[rows, , drop = FALSE] %*% factor
        drawn
    }, sort(unique(profile)), noise)
    structure(correlated + block$means[profile, continuous, drop = FALSE], dimnames = list(NULL, continuous))
