function(layout, covariate_rows, initial_rows, transitions) {
    n_groups <- nrow(layout$slot)
    first_row <- layout$slot[cbind(seq_len(n_groups), 1L)]
    initial <- cbind(matrix(1, n_groups, 1L, dimnames = list(NULL, "(Intercept)")), if (!is.null(initial_rows)) 
        initial_rows[first_row, , drop = FALSE])
    occasion_names <- paste0("occasion_", seq_len(layout$n_occasions)[-1L])
    transition <- lapply(seq_len(layout$n_occasions)[-1L], function(t) {
        intercepts <- if (identical(transitions, "occasion")) {
            matrix(as.numeric(seq_len(layout$n_occasions)[-1L] == t), n_groups, length(occasion_names), byrow = TRUE, dimnames = list(NULL, occasion_names))
        }
        else matrix(1, n_groups, 1L, dimnames = list(NULL, "(Intercept)"))
        if (is.null(covariate_rows)) 
            return(intercepts)
        rows <- layout$slot[, t]
        values <- matrix(0, n_groups, ncol(covariate_rows), dimnames = list(NULL, colnames(covariate_rows)))
        observed <- !is.na(rows)
        values[observed, ] <- covariate_rows[rows[observed], , drop = FALSE]
        cbind(intercepts, values)
    })
    list(initial = initial, transition = transition)
}

