function(fit, vcov_type = c("observed", "robust", "opg"), step = 1e-04) {
    vcov_type <- match.arg(vcov_type)
    if (!is.numeric(step) || length(step) != 1L || !is.finite(step) || step <= 0) {
        stop(errorCondition("`step` must be a positive finite number.", class = "latents_bad_argument", call = NULL))
    }
    if (any(vapply(fit$measurement, function(block) {
        any(block$count_dispersion <= .latents_min_dispersion * (1 + 1e-06)) || any(block$count_means <= 1e-08)
    }, logical(1)))) {
        stop(errorCondition("A count parameter is at its boundary; Wald inference does not apply.", class = "latents_boundary_fit", call = NULL))
    }
    if (any(vapply(fit$measurement, function(block) {
        any(unlist(block$response_probabilities) <= 1e-06)
    }, logical(1)))) {
        stop(errorCondition(paste("A response probability sits at its bound; Wald inference does not apply."), class = "latents_boundary_fit", call = NULL))
    }
    if (!isTRUE(fit$converged)) {
        stop(errorCondition("Inference requires a converged fit.", class = "latents_no_converge", call = NULL))
    }
    if (isTRUE(fit$boundary)) {
        stop(errorCondition(paste("A variance or covariance eigenvalue sits at min_variance, or a transition", "or initial probability at zero; Wald inference does not apply."), class = "latents_boundary_fit", call = NULL))
    }
    theta <- .lta_pack(.lta_parameters(fit), fit$variance_model, fit$extra_data)
    names(theta) <- .lta_names(fit)
    n_units <- sum(.multilpa_inference_groups(fit))
    if (vcov_type != "observed") {
        .multilpa_require_clusters(sum(.multilpa_inference_groups(fit, observed_only = TRUE)), length(theta), "A robust or OPG transition covariance")
    }
    scores <- .lta_group_scores(theta, fit)
    total <- function(v) colSums(.lta_group_scores(v, fit))
    information <- .inference_score_information(total, theta, step, scheme = "five_point", h_rule = "max1")
    inverse <- .inference_invert(information, "min_le_eps_max")
    meat <- crossprod(scores)
    if (vcov_type != "observed") {
        .inference_require_rank(scores[.multilpa_inference_groups(fit, observed_only = TRUE), , drop = FALSE], "Too few groups for a robust or OPG covariance.")
    }
    covariance <- switch(vcov_type, observed = inverse, robust = .inference_sandwich(inverse, meat, n_units), opg = chol2inv(chol(meat)))
    dimnames(covariance) <- dimnames(information)
    list(theta = theta, vcov = covariance, information = information, group_scores = scores, gradient = colSums(scores), vcov_type = vcov_type)
}

