function(fit, what) {
    parameters <- .lta_parameters(fit)
    unit_weights <- if (is.null(fit$sampling_weights)) 
        NULL
    else unname(fit$sampling_weights)
    n_states <- fit$n_profiles
    profiles <- paste0("profile_", seq_len(n_states))
    classes <- names(fit$group_probabilities)
    if (identical(what, "initial")) {
        return(do.call(rbind, lapply(seq_len(fit$n_group_classes), function(h) {
            p <- exp(.lta_log_initial(fit$designs$initial, matrix(parameters$initial[, , h], ncol(fit$designs$initial))))
            data.frame(group_class = classes[h], profile = profiles, probability = .lta_group_mean(p, unit_weights), stringsAsFactors = FALSE)
        })))
    }
    by_occasion <- !identical(fit$transitions, "homogeneous") || length(fit$transition_covariates) > 0L
    transition_occasions <- if ((fit$order %||% 1L) >= 2L) 
        1L
    else seq_along(fit$designs$transition)
    rows <- lapply(seq_len(fit$n_group_classes), function(h) {
        per_occasion <- lapply(transition_occasions, function(t) {
            active <- fit$layout$within[, t + 1L]
            log_p <- if (isTRUE(parameters$stayer[h])) {
                .lta_identity_transition(sum(active), n_states)
            }
            else .lta_log_transition(fit$designs$transition[[t]][active, , drop = FALSE], array(parameters$transition[, , , h], dim(parameters$transition)[1:3]))
            .lta_group_mean(exp(log_p), unit_weights[active])
        })
        weights <- vapply(transition_occasions, function(t) {
            sum((unit_weights %||% 1) * fit$layout$within[, t + 1L])
        }, numeric(1))
        if (!by_occasion) 
            per_occasion <- list(Reduce(`+`, Map(`*`, per_occasion, weights))/sum(weights))
        do.call(rbind, lapply(seq_along(per_occasion), function(t) {
            cells <- expand.grid(from = seq_len(n_states), to = seq_len(n_states))
            data.frame(group_class = classes[h], occasion = if (by_occasion) 
                t + 1L
            else NA_integer_, from = profiles[cells$from], to = profiles[cells$to], probability = per_occasion[[t]][cbind(cells$from, cells$to)], stringsAsFactors = FALSE)
        }))
    })
    table <- do.call(rbind, rows)
    `rownames<-`(table[order(table$group_class, table$occasion, table$from, table$to), , drop = FALSE], NULL)
}

