function(design, rows = seq_len(nrow(design))) {
    p <- ncol(design)
    basis <- diag(p)
    if (p == 1L) 
        return(basis)
    values <- design[rows, -1L, drop = FALSE]
    centre <- colMeans(values)
    spread <- sqrt(colMeans(sweep(values, 2L, centre)^2))
    if (any(!is.finite(spread)) || any(spread <= sqrt(.Machine$double.eps) * pmax(1, abs(centre)))) {
        stop(errorCondition("A covariate is constant over the occasions it applies to; remove it.", class = "latents_bad_covariate", call = NULL))
    }
    basis[1L, -1L] <- -centre/spread
    basis[-1L, -1L] <- diag(1/spread, p - 1L)
    basis
}

