function(x, rows = 20L, ...) {
    stopifnot(inherits(x, "multilpa"))
    n_continuous <- length(.multilpa_continuous_names(x))
    n_categorical <- length(x$categorical %||% character())
    class_model <- n_continuous == 0L
    unit <- if (class_model) 
        "class"
    else "profile"
    plural <- function(n, word) sprintf("%d %s%s", n, word, if (n == 1L) 
        ""
    else if (endsWith(word, "s")) 
        "es"
    else "s")
    kind <- if (class_model) 
        "latent class analysis"
    else "latent profile analysis"
    if (isTRUE(x$single_level)) {
        cat(sprintf("%s%s: %s\n", toupper(substr(kind, 1L, 1L)), substring(kind, 2L), plural(x$n_profiles, unit)))
    }
    else {
        cat(sprintf("Two-level %s: %s, %s\n", kind, plural(x$n_profiles, unit), plural(x$n_group_classes, "group class")))
    }
    units <- if (isTRUE(x$single_level)) 
        "observations"
    else sprintf("individuals in %d groups", x$n_groups)
    measurement <- if (class_model) {
        plural(n_categorical, "categorical indicator")
    }
    else {
        covariance_model <- x$covariance_model %||% "diagonal"
        paste0(if (!is.null(x$covariance_pattern)) {
            sprintf("%s diagonal residual covariance with covariances for %s (%s)", x$variance_model, paste(.latents_pattern_pairs(x$covariance_pattern), collapse = ", "), .latents_pattern_label(x))
        }
        else sprintf("%s %s residual covariance%s", x$variance_model, covariance_model, if (is.null(x$covariance_structure)) 
            ""
        else sprintf(" (%s)", x$covariance_structure)), if (n_categorical > 0L) 
            sprintf(", %s", plural(n_categorical, "categorical indicator"))
        else "")
    }
    cat(sprintf("%d %s; %s\n", x$n_observations, units, measurement))
    .latents_print_extra(x)
    .latents_print_weights(x)
    if (class_model) {
        cat("Classes are labelled profile_1, profile_2, ... in every table.\n")
    }
    if (identical(x$centering %||% "none", "person")) {
        cat("Indicators person-centred, so the profiles are profiles of change\n")
    }
    else if (identical(x$centering %||% "none", "grand")) {
        cat("Indicators grand-centred, so the means are deviations from the overall mean\n")
    }
    if (!identical(x$scaling %||% "none", "none")) {
        cat(sprintf(paste("Indicators divided by their %s standard deviation, so", "the means are in standard-deviation units\n"), if (identical(x$scaling, "person")) 
            "within-person"
        else "overall"))
    }
    if (isTRUE(x$noise)) {
        cat(sprintf(paste("Noise component: proportion %.4f, %d observation%s", "assigned to it (profile 0); hypervolume %.6g\n"), x$noise_probability, x$n_noise, if (x$n_noise == 1L) 
            ""
        else "s", x$hypervolume))
    }
    if (!is.null(x$prior)) {
        cat(paste("Posterior mode under mclust's conjugate prior; the log likelihood", "and criteria below are unpenalized\n"))
    }
    cat(sprintf("Log likelihood: %.6f | AIC: %.3f | %s: %.3f\n", x$log_likelihood, x$aic, if (isTRUE(x$single_level)) 
        "BIC"
    else "BIC (groups)", x$bic))
    if (identical(x$search, "emEM") && !is.null(x$n_screen)) {
        cat(sprintf(paste("Converged: %s | iterations: %d | best start: %d", "(emEM: %d screened, %d run to the end)\n"), x$converged, x$iterations, x$best_start, x$n_screen, x$n_starts))
    }
    else {
        cat(sprintf("Converged: %s | iterations: %d | best start: %d/%d\n", x$converged, x$iterations, x$best_start, nrow(x$starts)))
    }
    if (!is.null(x$n_informative) && x$n_informative < x$n_observations) {
        cat(sprintf("%d row(s) carry no observed indicator; the individual-level BIC uses %d.\n", x$n_observations - x$n_informative, x$n_informative))
    }
    if (length(x$fixed %||% character()) > 0L) {
        cat(sprintf("Held fixed, not estimated here: %s%s\n", paste(x$fixed, collapse = ", "), if (isTRUE(x$staged)) 
            " (first stage)"
        else ""))
        cat(sprintf("Parameters estimated here: %d; with the held measurement: %d\n", x$n_parameters, x$n_parameters_with_measurement %||% x$n_parameters))
    }
    if (x$boundary) 
        cat("A variance is at its specified lower bound.\n")
    if (x$small_classes) 
        cat("An effective class membership is below one.\n")
    .latents_print_gaussian_diagnostics(x$gaussian_diagnostics)
    .multilpa_print_primary(x, rows = rows)
    invisible(x)
}

