        return(.ordinal_update(spec, params, tau, max_newton))
    }
    n_classes <- spec$n_classes
    p <- ncol(spec$x)
    q <- ncol(spec$z)
    intercept <- match("(Intercept)", colnames(spec$x), nomatch = 0L)
    x_center <- numeric(p)
    z_center <- numeric(q)
    if (intercept > 0L) {
        supported <- rowSums(tau) > 0
        center <- function(design) {
            if (ncol(design) == 0L) 
                return(numeric())
            means <- colMeans(design[supported, , drop = FALSE])
            spread <- apply(abs(sweep(design[supported, , drop = FALSE], 2L, means, "-")), 2L, max)
            means[spread == 0 | abs(means) <= 10000 * spread] <- 0
            means
        }
        x_center <- center(spec$x)
        z_center <- center(spec$z)
        params$beta[intercept, ] <- params$beta[intercept, ] + as.vector(crossprod(x_center, params$beta)) + sum(z_center * params$common)
        spec$x <- sweep(spec$x, 2L, x_center, "-")
        if (q > 0L) 
            spec$z <- sweep(spec$z, 2L, z_center, "-")
