function(x, what = c("fit", "model", "tree"), n_classes = NULL, n_group_classes = 1L, ...) {
    what <- match.arg(what)
    if (identical(what, "fit")) 
        return(x$table)
    if (identical(what, "tree")) {
        extra <- list(...)
        if (!missing(n_classes)) 
            extra$n_profiles <- n_classes
        if (!missing(n_group_classes)) 
            extra$n_group_classes <- n_group_classes
        return(.latents_tree_results(x, extra))
    }
    stopifnot(`\`n_classes\` must name one fitted class count` = .mixture_is_count(n_classes %||% NA_real_))
    row <- which(x$grid$n_classes == n_classes & x$grid$n_group_classes == n_group_classes)
    if (length(row) != 1L || inherits(x$fits[[row]], "condition")) {
        stop(errorCondition(sprintf(paste("No fitted model with %s classes and %s group classes in this", "enumeration."), n_classes, n_group_classes), class = "latents_bad_argument", call = NULL))
    }
    fit <- x$fits[[row]]
    fit$inference <- if (inherits(fit, "latents_growth_mixture")) {
        .growth_resolve_inference(fit)
    }
    else .mixture_resolve_inference(fit, NULL)
    fit
}

