    }
    if (identical(spec$family, "ordinal")) {
        m <- spec$n_categories - 1L
        params$thresholds[] <- .ordinal_natural(take(m * k), m)
    }
    .mixture_structure_unpack(spec, theta[position + seq_len(length(theta) - position)], params)
