function(x, digits = 4L, ...) {
    spec <- x$spec
    fit <- .mixture_fit_table(x)
    nesting <- switch(spec$nesting, observation = "one class per row", group = sprintf("one class per `%s`", spec$id), `two-level` = sprintf("two-level: %d group classes of `%s`", spec$n_group_classes, spec$id))
    cat(sprintf("Mixture of %s regressions: %d classes (%s)\n", spec$family, spec$n_classes, nesting))
    cat(sprintf("%s ~ %s\n", spec$response_name, deparse1(spec$formula[[3L]])))
    cat(sprintf(paste0("%d rows%s | log likelihood %.", digits, "f | ", "BIC %.2f | entropy %.3f\n"), spec$n, if (is.null(spec$id)) 
        ""
    else sprintf(" in %d groups", spec$n_groups), fit$log_likelihood, fit$bic, fit$entropy))
    .latents_print_weights(x)
    cat(sprintf(paste("Converged: %s | iterations: %d | best likelihood reached", "by %d of %d completed starts (%d run)\n\n"), fit$converged, fit$iterations, fit$n_best_replicated, sum(x$starts$stage == "completed"), fit$n_starts))
    if (!is.null(x$inference)) {
        print(.mixture_table(x, "classes"))
        cat("\n")
        print(.mixture_table(x, "coefficients"))
    }
    else if (identical(spec$family, "ordinal")) {
        print(rbind(x$params$thresholds, x$params$beta), digits = digits)
    }
    else {
        print(x$params$beta, digits = digits)
    }
    cat("\nEvery table: get_results(x, what = ), e.g. \"classes\", \"membership\", \"fit\", \"assignments\".\n")
    invisible(x)
}

