function(response, levels = NULL) {
    bad_data <- function(message) {
        stop(errorCondition(message, class = "latents_bad_data", call = NULL))
    }
    whole <- function(v) all(is.finite(v)) && all(abs(v - round(v)) < sqrt(.Machine$double.eps))
    if (is.numeric(response) && !is.matrix(response) && whole(response)) {
        response <- round(as.vector(response))
    }
    if (!is.null(levels)) {
        codes <- match(as.character(response), levels)
        if (anyNA(codes)) {
            bad_data(sprintf("The outcome has categories the model was not fitted with: %s.", paste(sprintf("`%s`", unique(as.character(response)[is.na(codes)])), collapse = ", ")))
        }
        return(list(y = as.numeric(codes), trials = rep(1, length(codes))))
    }
    usable <- is.factor(response) || (is.numeric(response) && !is.matrix(response) && whole(response))
    if (!usable) {
        bad_data(paste("An ordinal outcome must be an ordered factor, a factor", "(its levels taken in order) or whole-number categories."))
    }
    kind <- if (is.ordered(response)) 
        "ordered"
    else if (is.factor(response)) 
        "factor"
    else "numeric"
    values <- if (is.factor(response)) 
        levels(response)
    else sort(unique(response))
    labels <- as.character(values)
    if (length(values) < 2L) {
        bad_data("An ordinal outcome needs at least two observed categories.")
    }
    list(y = as.numeric(match(as.character(response), labels)), trials = rep(1, length(response)), levels = labels, values = values, kind = kind)
}

