function(n_categories, n_classes, nesting, n_predictors) {
    if (n_classes < 2L || identical(nesting, "group")) 
        return(invisible(NULL))
    if (n_categories == 2L) {
        stop(errorCondition(paste("A two-category ordinal outcome is binary, and a mixture of binary", "outcomes with one outcome per class assignment is not identified (a", "mixture of Bernoulli distributions is itself a Bernoulli; Follmann and", "Lambert 1991). With two categories the ordinal model is the logistic", "mixture of `family = \"binomial\"`; give each class assignment several", "outcomes with `id` and `class_level = \"group\"`."), class = "latents_not_identified", call = NULL))
    }
    if (n_predictors == 0L) {
        stop(errorCondition(paste("An ordinal mixture without predictors and with one outcome per class", "assignment is not identified: a mixture of categorical distributions", "is itself a categorical distribution. Add predictors, or give each", "class assignment several outcomes with `id` and", "`class_level = \"group\"`."), class = "latents_not_identified", call = NULL))
    }
    invisible(NULL)
}

