function(spec) {
    if (spec$n_classes < 2L || !identical(spec$nesting, "observation")) {
        return(invisible(NULL))
    }
    patterns <- nrow(unique(cbind(spec$x, spec$z, spec$offset, spec$w)))
    capacity <- patterns * (spec$n_categories - 1L)
    n_parameters <- .mixture_count_parameters(spec)
    if (capacity < n_parameters) {
        stop(errorCondition(sprintf(paste("This ordinal mixture is not identified: its predictors take %d distinct", "covariate pattern%s, which with %d categories determine at most %d", "category probabilities, fewer than its %d free parameters. Add a", "continuous predictor, fit fewer classes, or give each class assignment", "several outcomes with `id` and `class_level = \"group\"`."), patterns, if (patterns == 1L) 
            ""
        else "s", spec$n_categories, capacity, n_parameters), class = "latents_not_identified", call = NULL))
    }
    invisible(NULL)
}

