function(object, newdata = NULL, type = c("response", "class_response", "posterior", "probabilities"), ..., trials = NULL) {
    type <- match.arg(type)
    if (identical(type, "probabilities") && !identical(object$spec$family, "ordinal")) {
        stop(errorCondition(paste("`type = \"probabilities\"` gives category probabilities of an ordinal", "outcome; use \"response\" or \"class_response\" for this family."), class = "latents_bad_argument", call = NULL))
    }
    spec <- if (is.null(newdata)) 
        object$spec
    else .mixture_prediction_data(.mixture_new_spec(object, newdata, identical(type, "posterior")))
    if (identical(spec$family, "binomial")) {
        resolved <- .mixture_prediction_trials(object, newdata, spec, trials, identical(type, "posterior"))
        spec$trials <- resolved
    }
    else if (!is.null(trials)) {
        stop(errorCondition("`trials` applies only to binomial predictions.", class = "latents_bad_argument", call = NULL))
    }
    params <- object$params
    if (identical(type, "posterior")) {
        refit <- object
        refit$spec <- spec
        refit$expectation <- .mixture_expectation(spec, params, weighted = FALSE)
        return(.mixture_assignment_table(refit))
    }
    priors <- .mixture_row_priors(spec, params)
    if (identical(type, "probabilities")) {
        return(.ordinal_probability_table(spec, params, priors))
    }
    means <- .mixture_class_means(spec, params)
    if (identical(type, "response")) {
        return(data.frame(row = spec$kept_rows, fitted = rowSums(priors * means)))
    }
    data.frame(row = rep(spec$kept_rows, spec$n_classes), class = rep(paste0("class_", seq_len(spec$n_classes)), each = spec$n), prior = as.vector(priors), fitted = as.vector(means))
}

