function(object, newdata, spec, trials, posterior) {
    bad_data <- function(message) {
        stop(errorCondition(message, class = "latents_bad_data", call = NULL))
    }
    if (!is.null(trials)) {
        if (is.character(trials) && length(trials) == 1L && !is.na(trials)) {
            frame <- newdata %||% object$spec$model_data
            if (!trials %in% names(frame)) 
                bad_data("`trials` names no column of the prediction data.")
            trials <- frame[[trials]]
        }
        if (!is.numeric(trials) || !is.null(dim(trials)) || !length(trials) %in% c(1L, spec$n) || any(!is.finite(trials)) || any(trials < 0) || any(abs(trials - round(trials)) > sqrt(.Machine$double.eps))) {
            bad_data("`trials` must be finite, non-negative whole numbers: one value or one per prediction row.")
        }
        if (length(trials) == 1L) 
            trials <- rep(trials, spec$n)
        trials <- as.numeric(trials)
        if (posterior && !isTRUE(all.equal(trials, as.numeric(spec$trials)))) {
            bad_data("For posterior prediction, `trials` must agree with the observed binomial response.")
        }
        return(trials)
    }
    if (is.null(newdata) || posterior) 
        return(spec$trials)
    response <- attr(object$spec$terms, "variables")[[2L]]
    counts <- any(object$spec$trials != 1) || is.matrix(.mixture_prediction_data(eval(response, object$spec$model_data, environment(object$spec$terms))))
    if (!counts) 
        return(rep(1, spec$n))
    if (all(all.vars(response) %in% names(newdata))) {
        return(.mixture_prediction_data(.mixture_response(eval(response, newdata, environment(object$spec$terms)), "binomial"))$trials)
    }
    bad_data(paste("Binomial count predictions need `trials` or the response", "columns in `newdata`; trial counts cannot be inferred from predictors alone."))
}

