function(spec, results, select_start) {
    log_likelihood <- vapply(results, function(r) r$expectation$log_likelihood, numeric(1))
    converged <- vapply(results, `[[`, logical(1), "converged")
    degenerate <- vapply(results, `[[`, logical(1), "degenerate")
    usable <- is.finite(log_likelihood) & !degenerate
    if (!any(usable)) {
        stop(errorCondition(sprintf(paste("Every one of the %d starts degenerated: a class emptied or collapsed", "onto too few rows to estimate its regression. Fewer classes, more", "starts, or a larger `min_variance` may help."), length(results)), class = "latents_no_valid_start", call = NULL))
    }
    if (any(degenerate)) {
        warning(warningCondition(sprintf(paste("%d of %d starts degenerated (an emptied class or a collapsed", "variance) and were set aside."), sum(degenerate), length(results)), class = "latents_degenerate_start", call = NULL))
    }
    candidates <- which(usable)
    best <- candidates[.multilpa_select_start(log_likelihood[candidates], converged[candidates], select_start)]
    chosen <- results[[best]]
    if (!chosen$converged) {
        warning(warningCondition(sprintf(paste("The selected start did not converge in %d iterations; the estimates", "are not a maximum. Raise `max_iter` or use", "`select_start = \"converged\"`."), chosen$iterations), class = "latents_unconverged", call = NULL))
    }
    params <- .mixture_order_classes(spec, chosen$params, chosen$expectation)
    expectation <- .mixture_expectation(spec, params, weighted = FALSE)
    if (isTRUE(params$separation) || isTRUE(params$membership_separation) || isTRUE(params$group_separation)) {
        warning(warningCondition(paste("A coefficient exceeded 30 on the logit or log scale: a class", "separates perfectly on some predictor, and that coefficient and its", "standard error are not reliable."), class = "latents_separation", call = NULL))
