function(value, argument) {
    if (is.null(value)) 
        return(NULL)
    if (inherits(value, "formula")) {
        if (length(all.vars(value)) == 0L) 
            environment(value) <- baseenv()
        return(value)
    }
    if (!is.character(value) || length(value) == 0L || anyNA(value) || !all(nzchar(value))) {
        stop(errorCondition(sprintf(paste("`%s` must be variable names such as \"time\" (or \"intercept\"), or a", "one-sided formula such as `~ 1 + time`."), argument), class = "latents_bad_argument", call = NULL))
    }
    terms <- setdiff(value, c("intercept", "1"))
    if (length(terms) == 0L) 
        return(stats::as.formula("~ 1", env = baseenv()))
    stats::reformulate(sprintf("`%s`", terms), env = baseenv())
}

