function(arguments, calls, costs, cores, verbose = FALSE) {
    force(arguments)
    force(calls)
    force(costs)
    force(cores)
    indices <- seq_along(arguments)
    started <- proc.time()[["elapsed"]]
    worker_report <- .latents_worker_reporter()
    on.exit(worker_report$signal(), add = TRUE)
    .latents_pool_progress(verbose, "Preparing %s on %s.", .latents_count(length(indices), "candidate"), .latents_count(min(cores, length(indices)), "worker"))
    candidates <- worker_report$collect(function() .latents_pool_setup(lapply(indices, function(i) {
        list(candidate = i, arguments = arguments[[i]], call = calls[[i]])
    }), .multilpa_setup_task, costs, cores, distribute = all(vapply(arguments, function(current) !is.null(current$seed), logical(1))) && !all(vapply(arguments, .multilpa_pool_fallback, logical(1)))))
    screen_tasks <- .multilpa_start_tasks(candidates, "screen")
    if (length(screen_tasks)) {
        .latents_pool_progress(verbose, "Screening %s on %s.", .latents_count(length(screen_tasks), "start"), .latents_count(min(cores, length(screen_tasks)), "worker"))
    }
    screened <- worker_report$collect(function() .latents_pool_phase(screen_tasks, costs, cores, length(indices), .multilpa_execute_start, .multilpa_pool_loss))
    ranked <- lapply(indices, function(i) {
        plan <- candidates[[i]]$value
        .latents_collect_conditions(function() tryCatch({
            if (inherits(plan, "error") || is.null(plan$screen)) 
                NULL
            else .latents_rank_screened(lapply(screened[[i]], `[[`, "value"), plan$n_starts, plan$screen)
        }, error = .lta_candidate_error))
    })
    final_tasks <- .multilpa_start_tasks(candidates, "final", screened, ranked)
    .latents_pool_progress(verbose, "Fitting %s on %s.", .latents_count(length(final_tasks), "start"), .latents_count(min(cores, max(1L, length(final_tasks))), "worker"))
    finished <- worker_report$collect(function() .latents_pool_phase(final_tasks, costs, cores, length(indices), .multilpa_execute_start, .multilpa_pool_loss))
    on.exit(.latents_pool_progress(verbose, "Done in %s.", .latents_format_duration(proc.time()[["elapsed"]] - started)), add = TRUE)
    lapply(indices, function(i) {
        plan <- candidates[[i]]$value
        final <- .latents_collect_conditions(function() tryCatch({
            if (inherits(plan, "error")) 
                stop(plan)
            if (!is.null(plan$arguments)) 
                return(finished[[i]][[1L]]$value)
            if (inherits(ranked[[i]]$value, "error")) 
                stop(ranked[[i]]$value)
            attempts <- lapply(finished[[i]], `[[`, "value")
            found <- if (is.null(plan$screen)) {
                .latents_select_starts(attempts, plan$select_start, interior = plan$interior)
            }
            else {
                .latents_select_screened(lapply(screened[[i]], `[[`, "value"), attempts, ranked[[i]]$value$finalists, ranked[[i]]$value$screened_scores, plan$select_start, interior = plan$interior)
            }
            .multilpa_finish_plan(plan, found)
        }, error = function(error) {
            if (inherits(plan, "latents_multilpa_plan")) {
                .multilpa_report_failed_plan(plan, error)
            }
            .lta_candidate_error(error)
        }))
        final$conditions <- c(candidates[[i]]$conditions, unlist(lapply(screened[[i]], `[[`, "conditions"), recursive = FALSE), ranked[[i]]$conditions, unlist(lapply(finished[[i]], `[[`, "conditions"), recursive = FALSE), final$conditions)
        final
    })
}

