function(x, expectation, variance_model, min_variance, covariance_model = "diagonal", codes = NULL, n_categories = NULL, min_probability = 1e-10, held = NULL, structure = NULL, previous = NULL, prior = NULL, extra = NULL, covariance_pattern = NULL) {
    stopifnot(is.matrix(x), is.list(expectation), variance_model %in% c("varying", "equal"), min_variance > 0, is.null(held) || is.list(held))
    unshifted <- x
    x <- .latents_direct_shift(x, extra, previous)
    weights <- colSums(expectation$subject_posteriors)
    group_weights <- colSums(expectation$group_posteriors)
    if (any(weights <= 0) || any(group_weights <= 0)) {
        stop("A profile or group class has zero effective membership.")
    }
    noisy <- !is.null(previous$noise_log_density)
    gaussian_expectation <- expectation
    if (noisy) {
        gaussian_expectation$subject_posteriors <- expectation$subject_posteriors[, -ncol(expectation$subject_posteriors), drop = FALSE]
        weights <- colSums(gaussian_expectation$subject_posteriors)
    }
    gaussian <- if (!is.null(prior)) {
        .multilpa_prior_maximize(x, gaussian_expectation$subject_posteriors, structure, prior, min_variance)
    }
    else if (!is.null(expectation$gaussian_moments)) {
        .multilpa_maximize_moments(x, gaussian_expectation, variance_model, min_variance, covariance_model, held, structure, previous, covariance_pattern = covariance_pattern)
    }
    else NULL
    if (ncol(x) == 0L) {
        means <- matrix(numeric(0), length(weights), 0L)
        variances <- matrix(numeric(0), length(weights), 0L)
    }
    else if (is.null(gaussian)) {
        means <- held$means %||% sweep(crossprod(gaussian_expectation$subject_posteriors, x), 1L, weights, "/")
        variance_sums <- t(matrix(vapply(seq_along(weights), function(profile) {
            residuals <- sweep(x, 2L, means[profile, ], "-")
            colSums(residuals^2 * gaussian_expectation$subject_posteriors[, profile])
        }, numeric(ncol(x))), nrow = ncol(x), ncol = length(weights)))
        constrained <- !is.null(structure) && identical(covariance_model, "diagonal") && !structure %in% c("EEI", "VVI")
        variances <- if (!is.null(held$variances)) 
            held$variances
        else if (constrained) {
            .multilpa_structure_variances(variance_sums, weights, structure, min_variance)
        }
        else if (variance_model == "varying") {
            sweep(variance_sums, 1L, weights, "/")
        }
        else {
            matrix(colSums(variance_sums)/if (noisy) 
                sum(weights)
            else expectation$n_total %||% nrow(x), length(weights), ncol(x), byrow = TRUE)
        }
        if (is.null(held$variances)) 
            variances <- pmax(variances, min_variance)
    }
    else {
        means <- gaussian$means
        variances <- gaussian$variances
    }
    n_columns <- ncol(expectation$subject_posteriors)
    profile_counts <- t(matrix(vapply(expectation$joint, colSums, numeric(n_columns)), nrow = n_columns, ncol = length(group_weights)))
    profile_probabilities <- profile_counts/rowSums(profile_counts)
    parameters <- list(means = means, variances = variances, profile_probabilities = profile_probabilities, group_probabilities = group_weights/sum(group_weights))
    if (!is.null(gaussian$covariances)) 
        parameters$covariances <- gaussian$covariances
    if (noisy) 
        parameters$noise_log_density <- previous$noise_log_density
    if (!is.null(codes)) {
        parameters$response_probabilities <- held$response_probabilities %||% .multilpa_categorical_maximize(codes, expectation$subject_posteriors, n_categories, min_probability)
    }
    if (!is.null(extra)) {
        blocks <- .latents_extra_maximize(extra, expectation$subject_posteriors, previous)
        parameters[names(blocks)] <- blocks
    }
    if (!is.null(extra$direct)) {
        parameters$direct_effects <- .latents_direct_maximize(unshifted, extra, expectation$subject_posteriors, means, variances)
    }
    if (any(!is.finite(unlist(parameters, use.names = FALSE)))) {
        stop("Non-finite parameters in the M-step; check indicator scales.")
    }
