    stopifnot(is.matrix(x), length(group_index) == nrow(x), n_profiles >= 1L, n_types >= 1L, start_index >= 1L, variance_model %in% c("varying", "equal"), min_variance > 0, kind %in% c("kmeans", "partition", "centres"))
