        if (any(!is.finite(initial_means))) {
            stop(errorCondition(paste("Every continuous indicator needs an observed row with positive", "sampling weight for initialization."), class = "latents_bad_data", call = NULL))
        }
        x <- matrix(vapply(seq_len(ncol(x)), function(indicator) {
            value <- x[, indicator]
            value[is.na(value)] <- initial_means[indicator]
            value
