function(response_probabilities, categorical, levels = NULL) {
    if (!is.list(response_probabilities) || length(categorical) == 0L || length(response_probabilities) != length(categorical)) {
        return(response_probabilities)
    }
    block_names <- names(response_probabilities)
    if (!is.null(block_names) && !anyNA(block_names) && all(nzchar(block_names))) {
        if (anyDuplicated(block_names) > 0L || !setequal(block_names, categorical)) {
            stop(errorCondition(sprintf("start$response_probabilities is labelled %s, but this fit's categorical indicators are %s.", paste(sprintf("\"%s\"", block_names), collapse = ", "), paste(sprintf("\"%s\"", categorical), collapse = ", ")), class = "latents_bad_start", call = NULL))
        }
        response_probabilities <- response_probabilities[categorical]
    }
    if (is.null(levels)) 
        return(unname(response_probabilities))
    unname(lapply(seq_along(categorical), function(index) {
        block <- response_probabilities[[index]]
        wanted <- levels[[categorical[[index]]]]
        observed <- if (is.matrix(block)) 
            colnames(block)
        else NULL
        if (is.null(observed) || is.null(wanted)) 
            return(block)
        if (anyDuplicated(observed) > 0L || !setequal(observed, wanted)) {
            stop(errorCondition(sprintf("start$response_probabilities for `%s` is labelled %s, but `%s` has categories %s here.", categorical[[index]], paste(sprintf("\"%s\"", observed), collapse = ", "), categorical[[index]], paste(sprintf("\"%s\"", wanted), collapse = ", ")), class = "latents_bad_start", call = NULL))
        }
        block[, match(wanted, observed), drop = FALSE]
    }))
