        sum(log(apply(values, 2L, function(column) diff(range(column)))))
    }
    if (ncol(x) == 1L) 
        return(log_ranges(x))
    centred <- sweep(x, 2L, colMeans(x), "-")
    rotation <- eigen(crossprod(centred)/nrow(x), symmetric = TRUE)$vectors
    min(log_ranges(x), log_ranges(centred %*% rotation))
}

