        if (cores > 1L) {
            tryCatch(parallel::mclapply(indices, collected, mc.cores = cores, mc.preschedule = FALSE), error = function(condition) {
                if (!retry) 
                  stop(condition)
                rep(list(NULL), length(indices))
            })
        }
        else {
            unavailable <- FALSE
            run_task <- function(task) {
                job <- NULL
                finished <- FALSE
                on.exit(if (!finished && !is.null(job)) suspendInterrupts({
                  tryCatch(tools::pskill(job$pid, tools::SIGKILL), error = function(condition) NULL)
                  suppressWarnings(tryCatch(parallel::mccollect(job, wait = FALSE), error = function(condition) NULL, interrupt = function(condition) NULL))
                }), add = TRUE)
                job <- parallel::mcparallel(collected(task), mc.set.seed = TRUE)
                result <- parallel::mccollect(job)
                finished <- TRUE
                if (is.null(result)) 
                  NULL
                else result[[1L]]
            }
            lapply(indices, function(task) {
                if (unavailable) 
                  return(NULL)
                tryCatch(run_task(task), error = function(condition) {
                  if (!retry) 
                    stop(condition)
                  unavailable <<- TRUE
                  NULL
                })
            })
        }
    }, warning = function(condition) {
        if (grepl("did not deliver a result|scheduled cores.*error|parallel function calls?.*error", conditionMessage(condition))) 
