function(indices, collected, cores, retry = FALSE) {
    if (retry) 
        cores <- 1L
    cluster <- NULL
    attempted <- FALSE
    unavailable <- FALSE
    finished <- FALSE
    on.exit(if (!is.null(cluster)) suspendInterrupts({
        if (finished) .latents_stop_cluster(cluster) else {
            tryCatch(.latents_abort_cluster(cluster), error = function(condition) NULL)
        }
    }), add = TRUE)
    chunks <- split(seq_along(indices), ceiling(seq_along(indices)/cores))
    results <- lapply(chunks, function(positions) {
        if (unavailable) 
            return(rep(list(NULL), length(positions)))
        if (is.null(cluster)) {
            cluster <<- tryCatch(.latents_make_cluster(cores), error = function(condition) {
                if (retry || attempted) {
                  unavailable <<- TRUE
                  return(NULL)
                }
                stop(errorCondition(sprintf("Could not start the worker cluster (%s).", conditionMessage(condition)), class = "latents_parallel_failure", call = NULL))
            })
            if (is.null(cluster)) 
                return(rep(list(NULL), length(positions)))
        }
        attempted <<- TRUE
        tryCatch(parallel::parLapplyLB(cluster, indices[positions], collected, chunk.size = 1L), error = function(condition) {
            if (!grepl("connection|unserialize|serialize|socket|node.*(died|terminated)", conditionMessage(condition), ignore.case = TRUE)) 
                stop(condition)
            retired <- .latents_abort_cluster(cluster)
            cluster <<- NULL
            if (!retired) {
                .latents_warn_worker_lost(length(positions), 0L, 1L)
                stop(errorCondition(paste("Owned worker processes could not be stopped safely.", "No replacement workers were started; run again with fewer `cores`."), class = "latents_parallel_failure", call = NULL))
            }
            rep(list(NULL), length(positions))
        })
    })
    results <- unname(do.call(c, results))
    finished <- TRUE
    results
}

