function(y, gap) {
    if (length(y) < 2L) 
        return(y)
    ordering <- order(y)
    steps <- gap * (seq_along(y) - 1)
    spread <- cummax(y[ordering] - steps) + steps
    spread <- spread - mean(spread) + mean(y)
    out <- numeric(length(y))
    out[ordering] <- spread
    out
}

