        stop(errorCondition("This model has no continuous indicators; plot `what = \"responses\"` instead.", class = "latents_no_continuous", call = NULL))
    }
    reason <- if (is.character(errors)) 
        errors
    else NULL
    if (is.character(errors)) 
        errors <- NULL
    means <- x$means
    if (identical(scale, "standardized")) {
        basis <- .multilpa_standardization(x, vars)
        means <- sweep(sweep(means, 2L, basis$centre, "-"), 2L, basis$spread, "/")
        if (!is.null(errors)) 
            errors <- sweep(errors, 2L, basis$spread, "/")
    }
    n_profiles <- x$n_profiles
    cells <- expand.grid(position = seq_along(vars), profile = seq_len(n_profiles))
    z <- stats::qnorm(0.975)
    frame <- data.frame(profile = cells$profile, position = cells$position, indicator = factor(vars[cells$position], levels = vars), mean = means[cbind(cells$profile, cells$position)])
    spread <- if (is.null(errors)) 
        NA_real_
    else errors[cbind(cells$profile, cells$position)]
    frame$lower <- frame$mean - z * spread
    frame$upper <- frame$mean + z * spread
    frame$profile_label <- key$label[frame$profile]
    frame$rank <- key$rank[frame$profile]
    note <- if (!is.null(errors) && any(is.finite(spread))) {
        "; whiskers are 95% intervals"
    }
    else if (!is.null(reason)) 
        paste0("; ", reason)
    else ""
    list(frame = frame, vars = vars, note = note, has_errors = !is.null(errors) && any(is.finite(spread)))
}

