function(x, category, labels, errors, main, subtitle) {
    blocks <- x$response_probabilities
    if (is.null(blocks) || length(blocks) == 0L) {
        stop(errorCondition("This model has no categorical indicators.", class = "latents_no_categorical", call = NULL))
    }
    key <- .gg_profile_key(x)
    vars <- names(blocks)
    n_profiles <- x$n_profiles
    chosen <- vapply(blocks, function(block) {
        index <- if (identical(category, "last")) 
            ncol(block)
        else if (identical(category, "first")) 
            1L
        else if (is.numeric(category)) 
            as.integer(category)
        else match(as.character(category), colnames(block))
        if (is.na(index) || index < 1L || index > ncol(block)) {
            stop(errorCondition(sprintf("`category` does not match a category of an indicator with categories %s.", paste(colnames(block), collapse = ", ")), class = "latents_unknown_category", call = NULL))
        }
        index
    }, integer(1))
