        colnames(blocks[[index]])[chosen[[index]]]
    }, character(1))
    reason <- if (is.character(errors)) 
        errors
    else NULL
    if (is.character(errors)) 
        errors <- NULL
    cells <- expand.grid(position = seq_along(vars), profile = seq_len(n_profiles))
    frame <- data.frame(profile = cells$profile, position = cells$position, mean = vapply(seq_len(nrow(cells)), function(row) {
        blocks[[cells$position[row]]][cells$profile[row], chosen[[cells$position[row]]]]
    }, numeric(1)))
    bounds <- .gg_match_bounds(errors, "response", frame$profile, sprintf("%s:%s", vars[frame$position], category_labels[frame$position]))
    frame$lower <- bounds$lower
    frame$upper <- bounds$upper
    frame$profile_label <- key$label[frame$profile]
    frame$rank <- key$rank[frame$profile]
    has_errors <- any(is.finite(frame$lower) & is.finite(frame$upper))
    held <- isTRUE(attr(errors, "held"))
    note <- if (has_errors) {
        if (held) 
            "; whiskers: 95% intervals where estimable"
        else "; whiskers: 95% intervals"
    }
    else if (!is.null(reason)) 
        paste0("; ", reason)
    else ""
    shared <- length(unique(category_labels)) == 1L
    axis_labels <- if (shared) 
        vars
    else sprintf("%s=%s", vars, category_labels)
    .gg_series_plot(frame, key, labels, has_errors, y_label = if (shared) 
        sprintf("P(response = %s)", category_labels[[1L]])
    else "Response probability", x_labels = axis_labels, ylim = c(0, 1)) + .gg_titles(main, subtitle, "Response probabilities by profile", sprintf("%d profiles%s, %d categorical indicator%s%s", n_profiles, .gg_group_class_text(x), length(vars), if (length(vars) == 1L) 
        ""
    else "s", note))
}

