function(grid, criteria, by_classes = FALSE) {
    model <- grid$model
    known <- unique(stats::na.omit(model))
    if (length(known) == 1L) 
        model[is.na(model)] <- known
    model[is.na(model)] <- "-"
    classes_text <- sprintf("%d group class%s", grid$n_group_classes, ifelse(grid$n_group_classes == 1L, "", "es"))
    several_models <- length(unique(model)) > 1L
    several_groups <- !by_classes && length(unique(grid$n_group_classes)) > 1L
    series <- if (several_models && several_groups) {
        paste(model, classes_text, sep = ", ")
    }
    else if (several_models) 
        model
    else if (several_groups) 
        classes_text
    else rep("", nrow(grid))
    do.call(rbind, Map(function(column, title) {
        values <- grid[[column]]
        eligible <- grid$converged %in% TRUE & is.finite(values)
        data.frame(title = title, series = series, n_profiles = if (by_classes) 
            grid$n_group_classes
        else grid$n_profiles, value = values, eligible = eligible)
    }, criteria, names(criteria)))
}

