function(x, what = c("all", "sizes", "posteriors", "entropy", "avepp", "group_sizes", "group_posteriors", "group_entropy", "group_avepp"), main = NULL, subtitle = NULL) {
    .gg_require_fit(x, "plot_diagnostics")
    what <- match.arg(what)
    .gg_require()
    if (!identical(.latents_plot_kind(x), "profile_model")) {
        individual <- c("sizes", "posteriors", "entropy", "avepp")
        return(.multilpa_plot_grouped(x, what, stats::setNames(rep(list(c("main", "subtitle")), 4L), individual), .multilpa_supplied_arguments(match.call(), environment()), "plot_diagnostics"))
    }
    views <- list(sizes = .gg_view_sizes, posteriors = .gg_view_posteriors, entropy = .gg_view_entropy, avepp = .gg_view_avepp)
    group_views <- lapply(views, function(view) function(x, main, subtitle) view(x, main, subtitle, level = "groups"))
    names(group_views) <- paste0("group_", names(views))
    if (!identical(what, "all")) {
        if (what %in% names(group_views)) {
            .multilpa_require_case_posteriors(x, what, level = "groups")
            return(group_views[[what]](x, main, subtitle))
        }
        if (!identical(what, "sizes")) {
            .multilpa_refuse_noise(x, sprintf("plot_diagnostics(what = \"%s\")", what))
        }
        return(views[[what]](x, main, subtitle))
    }
    if (isTRUE(x$noise)) 
        views <- views["sizes"]
    else if (ncol(x$subject_posteriors) < 2L) 
        views <- views[c("sizes", "avepp")]
    if (.gg_has_group_classes(x) && !isTRUE(x$noise)) {
        views <- c(views, group_views)
    }
    .gg_plots(lapply(views, function(view) view(x, main, subtitle)))
}

