        stop(errorCondition(sprintf(paste("A single-profile fit assigns every case to that profile with probability one,", "so `what = \"%s\"` has nothing to separate. Views available for this fit: %s."), what, .multilpa_available_views_text(x)), class = "latents_nothing_to_plot", call = NULL))
    }
    invisible(NULL)
}

