function(grid, criterion) {
    classification <- c("awe", "icl", "clc")
    no_group_classes <- nrow(grid) > 0L && !is.null(grid$n_group_classes) && all(grid$n_group_classes %in% 1L)
    if (no_group_classes) {
        stems <- sub("_groups$", "", criterion)
        redundant <- grepl("_groups$", criterion) & stems %in% classification & paste0(stems, "_individual") %in% criterion
        criterion <- criterion[!redundant]
    }
    base <- sub("_(groups|individual)$", "", criterion)
    level <- ifelse(grepl("_groups$", criterion), "groups", ifelse(grepl("_individual$", criterion), "individuals", ""))
    same_at_both <- vapply(base, function(stem) {
        both <- paste0(stem, c("_groups", "_individual"))
        all(both %in% names(grid)) && isTRUE(all.equal(grid[[both[1L]]], grid[[both[2L]]]))
    }, logical(1))
    plain <- same_at_both | !nzchar(level) | (no_group_classes & base %in% classification & level == "individuals")
    keep <- !duplicated(ifelse(same_at_both, base, criterion))
    titles <- ifelse(plain, toupper(base), sprintf("%s (%s)", toupper(base), level))
    stats::setNames(criterion[keep], titles[keep])
}

