  if (length(absent) > 0L) {
    bad_data(sprintf("`newdata` lacks the column%s %s the fit uses.",
                     if (length(absent) > 1L) "s" else "",
                     paste(sprintf("`%s`", absent), collapse = ", ")))
  }
