function(shrinkage = 0.01, mean = NULL, dof = NULL, scale = NULL) {
    bad <- function(message) {
        stop(errorCondition(message, class = "latents_bad_argument", call = NULL))
    }
    if (!is.numeric(shrinkage) || length(shrinkage) != 1L || !is.finite(shrinkage) || shrinkage < 0) {
        bad("`shrinkage` must be a single non-negative number.")
    }
    if (!is.null(mean) && (!is.numeric(mean) || anyNA(mean) || any(!is.finite(mean)))) {
        bad("`mean` must be NULL or a finite numeric vector.")
    }
    if (!is.null(mean) && shrinkage == 0) {
        bad("A prior `mean` needs a positive `shrinkage`, or it has no effect.")
    }
    if (!is.null(dof) && (!is.numeric(dof) || length(dof) != 1L || !is.finite(dof) || dof <= 0)) {
        bad("`dof` must be NULL or a single positive number.")
    }
    if (!is.null(scale) && (!is.numeric(scale) || length(scale) == 0L || any(!is.finite(scale)) || !.multilpa_positive_scale(scale))) {
        bad("`scale` must be NULL, a positive number or a positive-definite matrix.")
    }
    structure(list(shrinkage = shrinkage, mean = mean, dof = dof, scale = scale), class = "latents_prior")
}

