function(x, ...) {
    stopifnot(inherits(x, "multilpa_diagnostics"))
    fit <- x$fit
    cat(sprintf("Classification quality: %d profile%s", fit$n_profiles, if (identical(as.integer(fit$n_profiles), 1L)) 
        ""
    else "s"))
    one_group_class <- is.null(fit$n_group_classes) || identical(as.integer(fit$n_group_classes), 1L)
    if (!one_group_class) 
        cat(sprintf(", %d group classes", fit$n_group_classes))
    cat("\n\n")
    entropy <- x$entropy
    if (one_group_class) 
        entropy <- entropy[entropy$level == "individuals", , drop = FALSE]
    levels_in_order <- entropy$level
    line <- function(label, values) {
        cat(sprintf("  %-20s %s\n", label, paste(values, collapse = "    ")))
    }
    per_level <- function(frame, f) {
        parts <- lapply(levels_in_order, function(level) {
            f(frame[frame$level == level, , drop = FALSE], level)
        })
        unlist(parts, use.names = FALSE)
    }
    line("Relative entropy", sprintf("%s %.3f", entropy$level, entropy$relative_entropy))
    line("Smallest class", per_level(x$classification, function(rows, level) {
        row <- rows[which.min(rows$estimated_proportion), , drop = FALSE]
        sprintf("%s %.1f (%.1f%%)", level, row$estimated_n, 100 * row$estimated_proportion)
    }))
    averages <- x$average_posteriors
    assigned <- averages[averages$assigned_class == averages$class, , drop = FALSE]
    line("Lowest avg posterior", per_level(assigned, function(rows, level) {
        sprintf("%s %.3f", level, min(rows$average_posterior))
    }))
    if (is.null(x$residuals)) {
        line("Largest residual", if (isTRUE(fit$noise)) 
            "not available for a fit with a noise component"
        else "not available for this model family")
    }
    else {
        worst <- x$residuals[which.max(abs(x$residuals$residual)), , drop = FALSE]
        line("Largest residual", sprintf("%.3f  (%s, %s; %s)", worst$residual, worst$indicator_1, worst$indicator_2, worst$profile))
    }
    cat("\nTables: get_results(x, what = \"entropy\" | \"classification\" |", "\n        \"average_posteriors\" | \"residuals\" | \"all\").", "plot(x) draws them.\n")
    invisible(x)
}

