    stopifnot(`\`x\` must be a fitted model of this package` = .multilpa_any_fit(x), `\`plots\` must be TRUE or FALSE` = isTRUE(plots) || isFALSE(plots))
    .multilpa_reject_extra_arguments(list(...), "report()", "It forwards `by` to diagnostics() and `rows` to print(summary(x)).")
    by <- match.arg(by)
    data <- .multilpa_resolve_data(x, data)
    print(summary(x), rows = rows)
    cat("\n")
    print(descriptives(x))
    cat("\n")
    quality <- diagnostics(x, data = data, plots = FALSE, by = by)
    print(quality)
    if (isTRUE(plots) && .gg_available()) {
        views <- .multilpa_supported_views(x)
        refused <- unlist(lapply(views, function(view) {
            drawn <- tryCatch({
                print(if (is.na(view)) 
                  plot(x)
                else plot(x, what = view))
                NULL
            }, latents_no_plot = function(condition) view, latents_nothing_to_plot = function(condition) view, latents_no_time = function(condition) view, latents_no_categorical = function(condition) view, latents_no_continuous = function(condition) view, latents_no_indicator_data = function(condition) view)
            drawn
        }))
        if (length(refused) > 0L) {
            cat(sprintf("\nNot drawn for this model: %s\n", paste(ifelse(is.na(refused), "the default plot", refused), collapse = ", ")))
        }
    }
    invisible(x)
}

