function(theta, x, object, codes = NULL) {
    stopifnot(`\`theta\` must be numeric` = is.numeric(theta), `\`x\` must be a numeric matrix` = is.matrix(x) && is.numeric(x), `\`object\` must be an \`multilpa\` fit` = inherits(object, "multilpa"))
    parameters <- .multilpa_decode(theta, object)
    group_index <- object$group_index
    expectation <- .multilpa_expectation(x, group_index, parameters, codes, unname(object$sampling_weights), object$extra_data)
    n_profiles <- object$n_profiles
    n_types <- object$n_group_classes
    measurement <- if (.multilpa_uses_chart(object)) {
        .multilpa_chart_scores(parameters, expectation, x, object, theta[length(parameters$means) + seq_len(.multilpa_coordinate_widths(object, "unconstrained")[["variances"]])], group_index)
    }
    else if (identical(object$covariance_model, "full")) {
        .multilpa_full_measurement_group_score(parameters, expectation, object)
    }
    else {
        shifted <- .latents_direct_shift(x, object$extra_data, parameters)
        observed <- !is.na(x)
        blocks <- lapply(seq_len(n_profiles), function(profile) {
            residuals <- sweep(shifted, 2L, parameters$means[profile, ], "-")
            residuals[!observed] <- 0
            weights <- expectation$subject_posteriors[, profile]
            list(means = rowsum(sweep(residuals, 2L, parameters$variances[profile, ], "/") * weights, group_index, reorder = FALSE), variances = rowsum(0.5 * (sweep(residuals^2, 2L, parameters$variances[profile, ], "/") - observed) * weights, group_index, reorder = FALSE))
        })
        variances <- if (object$variance_model == "equal") {
            Reduce(`+`, lapply(blocks, `[[`, "variances"))
        }
        else do.call(cbind, lapply(blocks, `[[`, "variances"))
        list(means = do.call(cbind, lapply(blocks, `[[`, "means")), covariances = variances)
    }
    profile_scores <- do.call(cbind, lapply(seq_len(n_types), function(group_type) {
        counts <- rowsum(expectation$joint[[group_type]], group_index, reorder = FALSE)
        expected <- outer(rowSums(counts), parameters$profile_probabilities[group_type, ])
        (counts - expected)[, seq_len(n_profiles - 1L), drop = FALSE]
    }))
    group_scores <- (expectation$group_posteriors - outer(rowSums(expectation$group_posteriors), parameters$group_probabilities))[, seq_len(n_types - 1L), drop = FALSE]
    response_scores <- .multilpa_response_scores(codes, expectation$subject_posteriors, parameters$response_probabilities, group_index)
    extra_scores <- .latents_extra_scores(object$extra_data, expectation$subject_posteriors, parameters, group_index, x = x)
    scores <- cbind(measurement$means, measurement$covariances, response_scores, extra_scores, profile_scores, group_scores)
    dimnames(scores) <- list(object$group_ids, names(theta))
    scores
}

