        }
        if (identical(search, "kmeans")) {
            stop(errorCondition(paste("`n_screen` sets the pool of the emEM search; `search = \"kmeans\"`", "screens nothing. Drop `n_screen`, or use `search = \"emEM\"`."), class = "latents_bad_argument", call = NULL))
        }
    }
    if (identical(search, "kmeans")) 
        return(NULL)
    if (supplied && n_starts == 1L) 
        return(NULL)
    defaults <- .latents_search_defaults()
    n_pool <- as.integer(n_screen %||% (defaults$pool_factor * n_starts))
    list(n_pool = n_pool, iterations = min(defaults$iterations, max_iter), protect = if (supplied || defaults$protect_first) 1L else integer())
}

