function(x, y) {
    n <- length(x)
    none <- list(at = NA_integer_, distance = rep(NA_real_, n), rising = FALSE)
    if (n < 3L || diff(range(x)) <= 0 || diff(range(y)) <= 0) 
        return(none)
    if (y[n] >= y[1L]) {
        none$rising <- TRUE
        return(none)
    }
    x_scaled <- (x - min(x))/(max(x) - min(x))
    y_scaled <- (y - min(y))/(max(y) - min(y))
    slope <- y_scaled[n] - y_scaled[1L]
    below <- (y_scaled[1L] + slope * x_scaled) - y_scaled
    distance <- below/sqrt(1 + slope^2)
    at <- which.max(distance)
    list(at = if (distance[at] > sqrt(.Machine$double.eps)) at else NA_integer_, distance = distance, rising = FALSE)
}

