function(x, using = "bic_groups") {
    frame <- .latents_selection_frame(x, using)
    usable <- frame[frame$usable, , drop = FALSE]
    structure_text <- function(rows) {
        if (all(is.na(rows$model)) || length(unique(stats::na.omit(frame$model))) < 2L) 
            ""
        else paste0(", ", rows$model[1L])
    }
    one_line <- function(rows, along, direction, line) {
        rows <- rows[order(rows[[along]]), , drop = FALSE]
        n <- nrow(rows)
        knee <- .latents_kneedle(rows[[along]], rows$value)
        shorter <- if (n >= 4L) 
            .latents_kneedle(rows[[along]][-n], rows$value[-n])$at
        else NA_integer_
        found <- !is.na(knee$at)
        without <- if (is.na(shorter)) 
            NA_character_
        else rows$candidate[shorter]
        knee_name <- if (found) 
            rows$candidate[knee$at]
        else NA_character_
        note <- if (n < 3L) 
            "fewer than three candidates"
        else if (isTRUE(knee$rising)) 
            "the criterion does not fall along this line"
        else if (!found) 
            "the curve does not bend below the line"
        else if (n < 4L) 
            "three candidates: stability not assessed"
        else if (is.na(without)) 
            "no knee when the largest is left out"
        else if (identical(without, knee_name)) 
            ""
        else "moves when the largest is left out"
        data.frame(direction = direction, line = line, criterion = using, from = rows$candidate[1L], to = rows$candidate[n], n_points = n, knee_candidate = knee_name, distance = if (found) 
            knee$distance[knee$at]
        else NA_real_, knee_without_largest = without, stable = if (found && n >= 4L) 
            identical(without, knee_name)
        else NA, note = note, stringsAsFactors = FALSE)
    }
    model_key <- ifelse(is.na(usable$model), "", usable$model)
    along_profiles <- lapply(split(usable, list(usable$n_group_classes, model_key), drop = TRUE), function(rows) {
        one_line(rows, "n_profiles", "profiles", sprintf("%d group class%s%s", rows$n_group_classes[1L], if (rows$n_group_classes[1L] == 1L) 
            ""
        else "es", structure_text(rows)))
    })
    several_groups <- length(unique(usable$n_group_classes)) > 1L
    along_groups <- if (several_groups) {
        lapply(split(usable, list(usable$n_profiles, model_key), drop = TRUE), function(rows) {
            one_line(rows, "n_group_classes", "group_classes", sprintf("%d profile%s%s", rows$n_profiles[1L], if (rows$n_profiles[1L] == 1L) 
                ""
            else "s", structure_text(rows)))
        })
    }
    else list()
    by_parameters <- lapply(split(usable, model_key, drop = TRUE), function(rows) {
        one_line(rows, "n_parameters", "parameters", paste0("all candidates", structure_text(rows)))
    })
    result <- do.call(rbind, c(along_profiles, along_groups, by_parameters))
    if (is.null(result)) {
        return(data.frame(direction = character(), line = character(), criterion = character(), from = character(), to = character(), n_points = integer(), knee_candidate = character(), distance = numeric(), knee_without_largest = character(), stable = logical(), note = character()))
    }
    result <- result[order(match(result$direction, c("profiles", "group_classes", "parameters"))), , drop = FALSE]
    row.names(result) <- NULL
    result
}

