function(replicates, observed, iter) {
    valid <- all(replicates$valid)
    p_value <- if (valid) 
        (1 + sum(replicates$statistic >= observed))/(iter + 1)
    else NA_real_
    if (!valid) {
        warning(warningCondition(paste("Some bootstrap fits failed validation, so p_value is NA.", "summary() reports every replicate; improve fitting and rerun."), class = "latents_failed_replicates"))
    }
    list(p_value = p_value, monte_carlo_se = if (valid) sqrt(p_value * (1 - p_value)/(iter + 1)) else NA_real_, n_valid = sum(replicates$valid))
}

