function(candidates, phase = c("screen", "final"), screened = NULL, ranked = NULL) {
    phase <- match.arg(phase)
    unlist(lapply(seq_along(candidates), function(i) {
        plan <- candidates[[i]]$value
        if (inherits(plan, "error")) 
            return(list())
        screening <- !is.null(plan$screen)
        if (phase == "screen" && !screening) 
            return(list())
        if (phase == "final" && screening && inherits(ranked[[i]]$value, "error")) {
            return(list())
        }
        starts <- if (phase == "screen") 
            seq_along(plan$initial)
        else if (screening) 
            ranked[[i]]$value$finalists
        else seq_along(plan$initial)
        lapply(starts, function(start_index) {
            list(candidate = i, start_index = start_index, run = plan$run, initial = if (phase == "final" && screening) NULL else plan$initial[[start_index]], resume = if (phase == "final" && screening) screened[[i]][[start_index]]$value$checkpoint else NULL, screen = if (phase == "screen") plan$screen else NULL)
        })
    }), recursive = FALSE, use.names = FALSE)
}

