function(object) {
    continuous <- .multilpa_continuous_names(object)
    k <- object$n_profiles
    d <- length(continuous)
    chart <- .multilpa_chart(object$covariance_structure, k, d)
    blocks <- .multilpa_fitted_blocks(object)
    anchor <- .multilpa_chart_anchor(blocks, chart)
    log_volumes <- vapply(blocks, function(block) {
        as.numeric(determinant(block, logarithm = TRUE)$modulus)/d
    }, numeric(1))
    label <- function(shared, row) if (shared) 
        "shared"
    else as.character(row)
    volume_values <- if (chart$volume_shared) 
        mean(log_volumes)
    else log_volumes
    volume_names <- sprintf("log_volume[%s]", vapply(seq_len(chart$widths[["volume"]]), function(row) label(chart$volume_shared, row), character(1)))
    profile_log_shapes <- function() {
        lapply(seq_len(k), function(profile) {
            block <- blocks[[profile]]
            values <- switch(chart$form, diagonal = diag(block), rotation = diag(crossprod(anchor[[chart$rotation_of[profile]]], block %*% anchor[[chart$rotation_of[profile]]])))
            log(values) - log_volumes[profile]
        })
    }
    shape <- if (identical(chart$form, "spherical")) {
        list(values = numeric(0), names = character(0), scale = numeric(0))
    }
    else if (chart$form %in% c("diagonal", "rotation")) {
        shapes <- profile_log_shapes()
        rows <- if (chart$shape_shared) 
            list(Reduce(`+`, shapes)/k)
        else shapes
        free <- seq_len(d - 1L)
        list(values = unlist(lapply(rows, function(row) row[free]), use.names = FALSE), names = unlist(lapply(seq_along(rows), function(row) {
            sprintf("log_shape[%s,%s]", label(chart$shape_shared, row), continuous[free])
        }), use.names = FALSE), scale = rep(1, length(rows) * length(free)))
    }
    else {
        positions <- .multilpa_chart_cholesky_positions(d)
        matrices <- if (chart$shape_shared) {
            list(Reduce(`+`, lapply(seq_len(k), function(profile) {
                blocks[[profile]]/exp(log_volumes[profile])
            }))/k)
        }
        else {
            lapply(seq_len(k), function(profile) {
                blocks[[profile]]/exp(volume_values[chart$volume_of[profile]])
            })
        }
        pieces <- lapply(seq_along(matrices), function(row) {
            factor <- t(chol(matrices[[row]]))
            on_diagonal <- positions[, 1L] == positions[, 2L]
            values <- factor[positions]
            values[on_diagonal] <- log(values[on_diagonal])
            kind <- ifelse(on_diagonal, "log_shape_cholesky", "shape_cholesky")
            list(values = values, names = sprintf("%s[%s,%s,%s]", kind, label(chart$shape_shared, row), continuous[positions[, 1L]], continuous[positions[, 2L]]), scale = ifelse(on_diagonal, 1, sqrt(diag(matrices[[row]]))[positions[, 1L]]))
        })
        list(values = unlist(lapply(pieces, `[[`, "values"), use.names = FALSE), names = unlist(lapply(pieces, `[[`, "names"), use.names = FALSE), scale = unlist(lapply(pieces, `[[`, "scale"), use.names = FALSE))
    }
    pairs <- .multilpa_chart_rotation_pairs(d)
    rotation_names <- if (chart$rotation_rows == 0L) 
        character(0)
    else {
        unlist(lapply(seq_len(chart$rotation_rows), function(row) {
            sprintf("rotation[%s,%s,%s]", label(chart$rotation_shared, row), continuous[pairs[, 1L]], continuous[pairs[, 2L]])
        }), use.names = FALSE)
    }
    values <- c(volume_values, shape$values, rep(0, length(rotation_names)))
    names(values) <- c(volume_names, shape$names, rotation_names)
    stopifnot(`the chart must have one coordinate per structure parameter` = length(values) == chart$width && chart$width == .multilpa_structure_parameters(chart$structure, k, d))
    list(values = values, scale = c(rep(1, length(volume_values)), shape$scale, rep(1, length(rotation_names))), chart = chart, anchor = anchor)
