function(x, data, outcome, level = c("individuals", "groups"), method = c("bch", "proportional", "modal", "ml"), ci_level = 0.95, contrast = c("none", "pairs"), adjust = c("BH", "holm", "hochberg", "hommel", "bonferroni", "BY", "none"), vcov_type = c("cluster", "independent"), variance = c("varying", "equal")) {
    variance_given <- !missing(variance)
    level <- match.arg(level)
    methods <- eval(formals(three_step)$method)
    released <- pmatch(method[1L], c("bch", "proportional", "modal"))
    method <- if (identical(method, methods)) 
        "bch"
    else if (length(method) == 1L && !is.na(released)) 
        methods[released]
    else match.arg(method, methods)
    variance <- match.arg(variance)
    if (variance_given && !identical(method, "ml")) {
        stop(errorCondition(paste("`variance` sets the class variances of the outcome in the ML step-three", "model; the other methods weight the outcome and model no variance. Use", "`method = \"ml\"`."), class = "latents_bad_argument", call = NULL))
    }
    contrast <- match.arg(contrast)
    adjust <- match.arg(adjust)
    vcov_type <- match.arg(vcov_type)
    .multilpa_refuse_noise(x, "three_step()")
    if (.latents_is_weighted(x)) 
        .latents_refuse_weights("`three_step()` yet")
    stopifnot(`\`data\` must be a data frame` = is.data.frame(data), `\`outcome\` must name a single column of \`data\`` = is.character(outcome) && length(outcome) == 1L && outcome %in% names(data), `\`outcome\` must be numeric` = is.numeric(data[[outcome]]), `\`outcome\` must not be missing` = !anyNA(data[[outcome]]), `\`outcome\` must be finite` = all(is.finite(data[[outcome]])), `\`ci_level\` must be a single number in (0, 1)` = is.numeric(ci_level) && length(ci_level) == 1L && ci_level > 0 && 
        ci_level < 1)
    if (.trajectory_is_fit(x)) {
        if (identical(level, "groups")) {
            stop(errorCondition(paste("A trajectory model classifies persons and has no group classes, so", "`level = \"groups\"` does not apply; its outcome is related to the", "person classes."), class = "latents_bad_argument", call = NULL))
        }
        prepared <- .trajectory_three_step_inputs(x, data, outcome)
        pieces <- prepared$pieces
        values <- prepared$values
        level <- "persons"
    }
    else {
        .multilpa_check_three_step_fit(x)
        if (outcome %in% .multilpa_measured_items(x)) {
            stop(errorCondition(sprintf("`%s` helped define the fitted classes, so it is not a distal outcome.", outcome), class = c("multilpa_indicator_reused", "latents_bad_outcome"), call = NULL))
        }
        pieces <- .multilpa_level_assignments(x, level)
        .multilpa_check_row_count(x, data)
        .multilpa_check_alignment(x, data)
        values <- .multilpa_outcome_values(x, data, outcome, level)
    }
    if (identical(method, "ml")) {
        return(.multilpa_three_step_ml(pieces, values, level, variance, ci_level, contrast, adjust, vcov_type))
    }
    weights <- .multilpa_step_weights(pieces, method)
    classes <- seq_len(pieces$n_classes)
    quantile <- stats::qnorm(1 - (1 - ci_level)/2)
    totals <- colSums(weights)
    if (any(!is.finite(totals)) || any(totals <= 0)) {
        stop(errorCondition("A class has no positive total outcome weight.", class = "latents_inseparable_classes", call = NULL))
    }
    baseline <- values[[1L]]
    centered <- values - baseline
    centered_estimates <- as.vector(crossprod(weights, centered))/totals
    estimates <- baseline + centered_estimates
    influence <- sweep(weights * outer(centered, centered_estimates, "-"), 2L, totals, "/")
    clustered <- .multilpa_step_clusters(influence, pieces, vcov_type)
    if (identical(contrast, "pairs")) {
        return(.multilpa_step_pairs(centered_estimates, clustered, level, method, quantile, adjust, vcov_type))
    }
    errors <- sqrt(colSums(clustered^2))
    result <- data.frame(level = level, method = method, class = classes, estimate = estimates, standard_error = errors, conf_low = estimates - quantile * errors, conf_high = estimates + quantile * errors, effective_n = totals^2/colSums(weights^2), row.names = NULL, stringsAsFactors = FALSE)
    attr(result, "vcov_type") <- vcov_type
    column <- .latents_column
    .latents_table(result, ci_level, sprintf("Distal outcome by class (%s, %s%% CI)", method, format(100 * ci_level)), list(column("Class", "class", "integer"), column("Mean", "estimate"), column(sprintf("%s%% CI", format(100 * ci_level)), c("conf_low", "conf_high"), "ci", "estimate"), column("SE", "standard_error"), column("Effective n", "effective_n")))
}

