function(x, data, covariates = character(), level = c("individuals", "groups"), ci_level = 0.95, vcov_type = c("robust", "observed"), adjust = c("BH", "holm", "hochberg", "hommel", "bonferroni", "BY", "none"), by_group_class = FALSE, initial_covariates = character(), transition_covariates = character()) {
    level <- match.arg(level)
    vcov_type <- match.arg(vcov_type)
    adjust <- match.arg(adjust)
    if (length(initial_covariates) > 0L || length(transition_covariates) > 0L) {
        return(.r3step_transitions(x, data, covariates, level, ci_level, vcov_type, adjust, by_group_class, initial_covariates, transition_covariates))
    }
    trajectory <- .trajectory_is_fit(x)
    if (!trajectory) 
        .multilpa_refuse_noise(x, "r3step()")
    if (.latents_is_weighted(x)) 
        .latents_refuse_weights("`r3step()` yet")
