        length(ci_level) == 1L && ci_level > 0 && ci_level < 1, `\`by_group_class\` must be TRUE or FALSE` = is.logical(by_group_class) && length(by_group_class) == 1L && !is.na(by_group_class))
    if (trajectory) {
        if (identical(level, "groups") || by_group_class) {
            stop(errorCondition(paste("A trajectory model classifies persons and has no group classes, so", "`level = \"groups\"` and `by_group_class = TRUE` do not apply."), class = "latents_bad_argument", call = NULL))
        }
        prepared <- .trajectory_r3step_inputs(x, data, covariates)
        pieces <- prepared$pieces
        design <- prepared$design
        level <- "persons"
    }
    else {
        .multilpa_check_three_step_fit(x)
        if (by_group_class && !identical(level, "individuals")) {
            stop(errorCondition(paste("`by_group_class = TRUE` gives each group class its own profile", "intercepts, so it applies to `level = \"individuals\"` only."), class = "latents_bad_argument", call = NULL))
        }
        if (by_group_class && inherits(x, "multilpa_transitions")) {
            stop(errorCondition(paste("`by_group_class = TRUE` is not available for a transition fit, whose", "group classes govern transitions rather than a profile mix."), class = "latents_bad_argument", call = NULL))
        }
        reused <- intersect(covariates, .multilpa_measured_items(x))
        if (length(reused) > 0L) {
            stop(errorCondition(sprintf("Measurement indicator(s) %s already helped define the fitted classes and cannot be used as external predictors.", paste(sprintf("`%s`", reused), collapse = ", ")), class = c("multilpa_indicator_reused", "latents_bad_covariate"), call = NULL))
        }
        pieces <- .multilpa_level_assignments(x, level)
        .multilpa_check_row_count(x, data)
        .multilpa_check_alignment(x, data)
        .r3step_require_classes(pieces)
        design <- .multilpa_r3step_design(x, data, covariates, level)
    }
    .r3step_require_classes(pieces)
    errors <- .multilpa_error_matrix(pieces)
    if (by_group_class) {
        if (identical(vcov_type, "robust")) {
            .multilpa_require_clusters(length(unique(pieces$group_index)), (x$n_group_classes + length(covariates)) * (pieces$n_classes - 1L) + x$n_group_classes - 1L, what = "A cluster-robust covariance for the membership regression", alternative = paste("`vcov_type = \"observed\"` uses the model-based", "information instead."))
        }
        return(.multilpa_r3step_by_group_class(x, design[, -1L, drop = FALSE], pieces, errors, ci_level, vcov_type, adjust))
    }
    basis <- .multilpa_design_basis(design) %||% diag(.multilpa_design_scale(design), ncol(design))
    terms <- colnames(design)
    design <- t(backsolve(basis, t(design), transpose = TRUE))
    by_assigned <- t(errors)[pieces$modal, , drop = FALSE]
    n_free <- pieces$n_classes - 1L
    shape <- function(theta) matrix(theta, ncol(design), n_free)
    if (identical(vcov_type, "robust")) {
        .multilpa_require_clusters(length(unique(pieces$group_index)), ncol(design) * n_free, what = "A cluster-robust covariance for the membership regression", alternative = paste("`vcov_type = \"observed\"` uses the model-based", "information instead, which does not allow for the", "nesting."))
    }
    objective <- function(theta) {
        prior <- .multilpa_logit_prior(shape(theta), design)
        -sum(log(pmax(rowSums(prior * by_assigned), 9.99999999999999e-301)))
    }
    score_rows <- function(theta) {
        prior <- .multilpa_logit_prior(shape(theta), design)
        joint <- prior * by_assigned
        posterior <- joint/rowSums(joint)
        residual <- (posterior - prior)[, seq_len(n_free), drop = FALSE]
        do.call(cbind, lapply(seq_len(n_free), function(k) design * residual[, k]))
    }
    gradient <- function(theta) -colSums(score_rows(theta))
    proportional_objective <- function(theta) {
        prior <- .multilpa_logit_prior(shape(theta), design)
        -sum(pieces$posteriors * log(pmax(prior, 9.99999999999999e-301)))
    }
    proportional_gradient <- function(theta) {
        prior <- .multilpa_logit_prior(shape(theta), design)
        residual <- (pieces$posteriors - prior)[, seq_len(n_free), drop = FALSE]
        -colSums(do.call(cbind, lapply(seq_len(n_free), function(k) design * residual[, k])))
    }
    control <- list(maxit = 1000L, reltol = 1e-12)
    zero <- rep(0, ncol(design) * n_free)
    starts <- list(zero, stats::optim(zero, proportional_objective, proportional_gradient, method = "BFGS", control = control)$par)
    attempts <- lapply(starts, function(start) stats::optim(start, objective, gradient, method = "BFGS", control = control))
    converged <- vapply(attempts, function(attempt) identical(attempt$convergence, 0L), logical(1))
    if (!any(converged)) {
        stop(errorCondition(sprintf("The membership regression did not converge (optim code %d).", attempts[[1L]]$convergence), class = "latents_no_converge", call = NULL))
    }
    attempts <- attempts[converged]
    fitted <- attempts[[which.min(vapply(attempts, `[[`, numeric(1), "value"))]]
    information <- .multilpa_observed_hessian(function(step) objective(fitted$par + step), function(step) gradient(fitted$par + step), rep(1, length(fitted$par)), 1e-04)
    covariance <- information$inverse
    if (identical(vcov_type, "robust")) {
        scores <- rowsum(score_rows(fitted$par), pieces$group_index, reorder = FALSE)
        covariance <- .inference_sandwich(covariance, .multilpa_cross_product(scores), nrow(scores))
    }
    natural <- kronecker(diag(n_free), backsolve(basis, diag(ncol(design))))
    .multilpa_r3step_frame(as.vector(natural %*% fitted$par), natural %*% covariance %*% t(natural), terms, n_free, pieces$n_classes, level, ci_level, vcov_type, adjust)
}

