    family <- spec$family %||% "gaussian"
    inverse_link <- switch(family, gaussian = identity, binomial = stats::plogis, poisson = exp, negative_binomial = exp)
    response_mean <- if (identical(family, "ordinal")) {
        function(linear, classes) {
            scores <- .ordinal_expected_scores(matrix(linear, length(linear), spec$n_classes), x$params$thresholds)
            scores[cbind(seq_along(linear), classes)]
        }
    }
    else function(linear, classes) inverse_link(linear)
    list(growth = growth, spec = spec, posterior = posterior, modal = max.col(posterior, ties.method = "first"), classes = paste0("class_", seq_len(spec$n_classes)), family = family, inverse_link = inverse_link, response_mean = response_mean, weights = spec$sampling_weights)
}

