function(x, rows, inference, level) {
    view <- .trajectory_view(x)
    spec <- view$spec
    design <- .growth_design(x, rows)
    z <- .inference_critical(level, "one_minus")
    if (identical(view$family, "ordinal")) {
        return(.ordinal_trajectory_band(x, design, inference, z, view$classes))
    }
    do.call(rbind, lapply(view$classes, function(class) {
        names <- c(sprintf("coefficient.%s.%s", class, colnames(spec$x)), if (ncol(spec$z) > 0L) sprintf("coefficient.common.%s", colnames(spec$z)))
        estimate <- as.vector(design %*% inference$theta[names]) + attr(design, "offset")
        covariance <- inference$vcov[names, names, drop = FALSE]
        std_error <- .inference_delta_se(design, covariance, "rowsums")
        response <- view$inverse_link(estimate)
        response_derivative <- switch(view$family, gaussian = rep(1, length(estimate)), binomial = response * (1 - response), poisson = , negative_binomial = response)
        data.frame(class = class, estimate = response, std_error = std_error * response_derivative, conf_low = view$inverse_link(estimate - z * std_error), conf_high = view$inverse_link(estimate + z * std_error), stringsAsFactors = FALSE)
    }))
}

