            joint <- log_from[, origin, drop = FALSE] + log_to[, destination, drop = FALSE] + log_transition
            active * exp(joint)
        }))
        list(initial = initial, transition = moves)
    })
    list(initial = lapply(per_type, `[[`, "initial"), transition = lapply(per_type, `[[`, "transition"))
}

