function(x, vcov_type) {
    refuse <- function(message, class) {
        stop(errorCondition(message, class = class, call = NULL))
    }
    if (!isTRUE(x$converged)) {
        refuse("Inference requires a converged fit.", "latents_no_converge")
    }
    if (!is.null(x$covariance_structure) && !x$covariance_structure %in% c("EEI", "VVI", "EEE", "VVV")) {
        refuse(paste("Standard errors for transition models are available for the EEI, VVI,", "EEE and VVV structures; this fit uses", x$covariance_structure, "."), "latents_unsupported_inference")
    }
    n_groups <- sum(.multilpa_inference_groups(x, observed_only = TRUE))
    if (vcov_type %in% c("robust", "opg") && n_groups <= x$n_parameters) {
        refuse(sprintf(paste("Robust and OPG inference need more groups than parameters; this fit has", "%d groups and %d parameters."), n_groups, x$n_parameters), "latents_too_few_groups")
    }
    if (isTRUE(x$boundary)) {
        refuse("Wald inference is unavailable for a bound-active fit.", "latents_boundary_fit")
    }
    if (any(x$empty_transition_rows)) {
        refuse(paste("A transition row was never informed: some profile is occupied by no", "group before its last occasion, so its outgoing probabilities are not", "estimated and have no standard error."), "latents_boundary_fit")
    }
    floor <- .multilpa_probability_floor(x)
    probabilities <- c(unlist(x$response_probabilities, use.names = FALSE), x$initial_probabilities, x$transition_probabilities, x$group_probabilities)
    if (any(probabilities <= floor)) {
        refuse(paste("Wald inference is unavailable when a probability sits at its lower", "bound: its logit is at minus infinity, where the likelihood has no", "curvature to invert."), "latents_boundary_fit")
    }
    invisible(NULL)
}

