function(x, level, n_profiles, n_group_classes, model, candidates) {
    table <- .latents_tree_table_of(x)
    names <- table$candidate
    if (identical(.latents_grid_kind(x), "families") && !identical(level, "groups")) {
        stop(errorCondition(paste("A family grid's candidates have group classes only, so their tree is", "of the groups: use `level = \"groups\"`."), class = c("latents_unsupported_view", "latents_bad_argument"), call = NULL))
    }
    if (!is.null(candidates)) {
        if (!is.null(n_profiles) || !is.null(n_group_classes) || !is.null(model)) {
            stop(errorCondition(paste("`candidates` names the rows of the tree itself; it is not combined", "with `n_profiles`, `n_group_classes` or `model`."), class = "latents_bad_argument", call = NULL))
        }
        if (!(is.character(candidates) && length(candidates) >= 2L && !anyNA(candidates) && !anyDuplicated(candidates))) {
            stop(errorCondition(paste("`candidates` names two or more different candidates, such as", "c(\"classes3_groups3\", \"classes4_groups3\"); `from` and `to` take", "class counts, such as from = c(3, 3), to = c(4, 3)."), class = "latents_bad_argument", call = NULL))
        }
        at <- match(candidates, names)
        if (anyNA(at)) {
            stop(errorCondition(sprintf("%s is not a candidate of this grid. Its candidates are %s.", paste(sprintf("\"%s\"", candidates[is.na(at)]), collapse = ", "), paste(sprintf("\"%s\"", names), collapse = ", ")), class = "latents_unknown_candidate", call = NULL))
        }
        invisible(lapply(at, function(row) .latents_tree_fit(x, row)))
        unconverged <- !table$converged[at] %in% TRUE
        if (any(unconverged)) {
            stop(errorCondition(sprintf("%s did not converge, so its classification is not a solution to compare.", paste(sprintf("\"%s\"", names[at][unconverged]), collapse = ", ")), class = "latents_unconverged", call = NULL))
        }
        if (identical(level, "groups") && all(table$n_group_classes[at] %in% 1L)) {
            stop(errorCondition(paste("These candidates have one group class, so their groups have no tree."), class = c("latents_no_tree", "latents_nothing_to_plot"), call = NULL))
        }
        word <- .latents_tree_word(x)
        counts_label <- function(count, noun) {
            if (is.na(count)) 
                return(NULL)
            sprintf("%d %s", count, if (count == 1L) 
                .latents_singular(noun)
            else noun)
        }
        crossed <- length(unique(table$model[!is.na(table$model)])) > 1L
        labels <- vapply(at, function(row) paste(c(counts_label(table$n_profiles[row], word), if (!all(table$n_group_classes %in% 1L)) {
            counts_label(table$n_group_classes[row], "group classes")
        }, if (crossed) table$model[row]), collapse = ", "), character(1))
        return(list(list(name = "candidates", label = "", row_facet = "", col_facet = "", rows = data.frame(at = at, candidate = names[at], key = NA_integer_, label = labels, stringsAsFactors = FALSE))))
    }
    structure <- ifelse(is.na(table$model), "", table$model)
    fitted <- !vapply(.subset2(x, "fits"), function(fit) {
        is.null(fit) || inherits(fit, "condition")
    }, logical(1))
    usable <- table$converged %in% TRUE & fitted
    .latents_check_tree_filter(model, structure[usable], "model")
    .latents_check_tree_filter(n_profiles, table$n_profiles[usable], "n_profiles")
    .latents_check_tree_filter(n_group_classes, table$n_group_classes[usable], "n_group_classes")
    keep <- usable & (if (is.null(model)) 
        TRUE
    else structure %in% model) & (if (is.null(n_profiles)) 
        TRUE
    else table$n_profiles %in% n_profiles) & (if (is.null(n_group_classes)) 
        TRUE
    else table$n_group_classes %in% n_group_classes)
    groups_level <- identical(level, "groups")
    no_profiles <- all(is.na(table$n_profiles))
    tree_count <- if (groups_level) {
        if (no_profiles) 
            rep(0L, nrow(table))
        else table$n_profiles
    }
    else table$n_group_classes
    row_count <- if (groups_level) 
        table$n_group_classes
    else table$n_profiles
    fixed <- unique(if (groups_level) 
        n_group_classes
    else n_profiles)
    across <- length(fixed) == 1L
    if (across) {
        row_count <- tree_count
        tree_count <- rep(0L, nrow(table))
    }
    single_level <- all(table$n_group_classes %in% 1L)
    if (groups_level && single_level) {
        stop(errorCondition(paste("This grid has one group class, so its groups have no tree.", "A group-level tree needs two or more numbers of group classes."), class = c("latents_no_tree", "latents_nothing_to_plot"), call = NULL))
    }
    word <- .latents_tree_word(x)
    rows_noun <- if (groups_level != across) 
        "group classes"
    else word
    fixed_noun <- if (groups_level) 
        "group classes"
    else word
    fixed_label <- if (across) 
        sprintf("%d %s", fixed, if (fixed == 1L) 
            .latents_singular(fixed_noun)
        else fixed_noun)
