        posteriors <- .latents_regression_posteriors(fit, level)
        if (is.null(posteriors)) {
            stop(errorCondition("These regression fits have no group classes, so their groups have no tree.", class = c("latents_no_tree", "latents_nothing_to_plot"), call = NULL))
        }
        spec <- fit$spec
        weights <- if (inherits(fit, "latents_growth_mixture") || identical(level, "groups") || identical(spec$nesting, "group")) {
            spec$sampling_weights
        }
        else spec$row_weights
        return(list(posteriors = posteriors, weights = weights %||% rep(1, nrow(posteriors))))
    }
    sampling <- fit$sampling_weights
    if (identical(level, "groups")) {
        posteriors <- fit$group_posteriors
        counted <- .multilpa_informative_groups(fit) %||% rep(TRUE, nrow(posteriors))
        weights <- if (is.null(sampling)) 
            rep(1, nrow(posteriors))
        else if (is.null(names(sampling)) || is.null(rownames(posteriors))) 
            unname(sampling)
        else unname(sampling)[match(rownames(posteriors), names(sampling))]
        return(list(posteriors = posteriors[counted, , drop = FALSE], weights = weights[counted]))
    }
    if (isTRUE(fit$noise)) {
        stop(errorCondition(paste("A fit with a noise component has no tree of its classes yet: the noise", "component's share would be left out of every row."), class = "latents_unsupported_noise", call = NULL))
    }
    posteriors <- fit$subject_posteriors
    counted <- .multilpa_informative_rows(fit)
    weights <- if (is.null(sampling)) 
        rep(1, nrow(posteriors))
    else unname(sampling)[fit$group_index]
    list(posteriors = posteriors[counted, , drop = FALSE], weights = weights[counted])
}

