function(x, tree, level) {
    gap <- 0.03
    drawn <- lapply(tree$rows$at, function(at) {
        .latents_tree_posteriors(.latents_tree_fit(x, at), level)
    })
    posteriors <- lapply(drawn, `[[`, "posteriors")
    weights <- drawn[[1L]]$weights
    total <- sum(weights)
    shares <- lapply(posteriors, function(p) colSums(p * weights)/total)
    flows <- lapply(seq_along(posteriors)[-1L], function(row) {
        crossprod(posteriors[[row - 1L]] * weights, posteriors[[row]])/total
    })
    segments_of <- function(share, ordering) {
        widths <- share[ordering]
        k <- length(widths)
        right <- cumsum(widths) + gap * (seq_len(k) - 1) - gap * (k - 1)/2
        data.frame(class = ordering, xmin = right - widths, xmax = right, share = widths)
    }
    first_order <- order(-shares[[1L]], seq_along(shares[[1L]]))
    segments <- Reduce(function(previous, row) {
        parent <- previous[[length(previous)]]
        flow <- flows[[row - 1L]]
        centres <- (parent$xmin + parent$xmax)[order(parent$class)]/2
        child_centre <- colSums(flow * centres)/colSums(flow)
        c(previous, list(segments_of(shares[[row]], order(child_centre, seq_along(child_centre)))))
    }, seq_along(posteriors)[-1L], init = list(segments_of(shares[[1L]], first_order)))
    first_colours <- character(length(shares[[1L]]))
    first_colours[first_order] <- rep_len(.gg_okabe_ito, length(first_order))
    colours <- Reduce(function(state, row) {
        flow <- flows[[row - 1L]]
        dominant_parent <- apply(flow, 2L, which.max)
        main_child <- apply(flow, 1L, which.max)
        continues <- main_child[dominant_parent] == seq_len(ncol(flow))
        fresh <- rep_len(.gg_okabe_ito, state$used + sum(!continues))[-seq_len(state$used)]
        row_colours <- character(ncol(flow))
        row_colours[continues] <- state$colours[[row - 1L]][dominant_parent[continues]]
        row_colours[!continues] <- fresh
        list(colours = c(state$colours, list(row_colours)), used = state$used + sum(!continues))
    }, seq_along(posteriors)[-1L], init = list(colours = list(first_colours), used = length(first_colours)))$colours
    if (length(unique(lengths(shares))) == 1L) {
        colours <- c(colours[1L], lapply(seq_along(posteriors)[-1L], function(row) {
            matched <- .latents_match_classes(crossprod(posteriors[[row]] * weights, posteriors[[1L]]))
            .latents_distinct_colours(ifelse(matched > 0L, colours[[1L]][pmax(matched, 1L)], colours[[row]]))
        }))
    }
    colours <- lapply(colours, .latents_distinct_colours)
    c(tree, list(posteriors = posteriors, weights = weights, shares = shares, flows = flows, segments = segments, colours = colours))
}

