function(log_likelihood, converged, rule = c("likelihood", "converged"), interior = NULL) {
    rule <- match.arg(rule)
    stopifnot(`\`log_likelihood\` must be numeric` = is.numeric(log_likelihood), `\`converged\` must be logical and match \`log_likelihood\`` = is.logical(converged) && length(converged) == length(log_likelihood), `at least one start must have a finite likelihood` = any(is.finite(log_likelihood)), `\`interior\` must be NULL or logical and match \`log_likelihood\`` = is.null(interior) || (is.logical(interior) && length(interior) == length(log_likelihood) && !anyNA(interior)))
    usable <- is.finite(log_likelihood)
    if (!is.null(interior)) {
        if (any(usable & interior)) {
            usable <- usable & interior
        }
        else {
            warning(warningCondition(paste("Every start reached a variance at its lower bound, so none could be", "excluded; the best start across all of them is reported."), class = "latents_all_starts_boundary", call = NULL))
        }
    }
    settled <- usable & converged
    candidates <- if (identical(rule, "converged") && any(settled)) {
        which(settled)
    }
    else which(usable)
    best <- max(log_likelihood[candidates])
    tied <- candidates[log_likelihood[candidates] >= best - 1e-10 * (1 + abs(best))]
    preferred <- tied[converged[tied]]
    if (length(preferred) > 0L) 
        preferred[1L]
    else tied[1L]
}

