function(data, weights, group_index, n_groups) {
    if (is.null(weights)) 
        return(NULL)
    if (!is.character(weights) || length(weights) != 1L || is.na(weights) || !weights %in% names(data)) {
        stop(errorCondition("`weights` must name one column of `data` holding a sampling weight per unit.", class = "latents_bad_weights", call = NULL))
    }
    values <- data[[weights]]
    if (!is.numeric(values) || anyNA(values) || any(!is.finite(values)) || any(values < 0)) {
        stop(errorCondition(sprintf("Sampling weights in `%s` must be finite, non-missing and non-negative.", weights), class = "latents_bad_weights", call = NULL))
    }
    stopifnot(`one unit per row` = length(group_index) == length(values))
    unit <- as.vector(tapply(values, group_index, min))
    spread <- as.vector(tapply(values, group_index, max)) - unit
    if (any(spread > sqrt(.Machine$double.eps) * pmax(1, abs(unit)))) {
        stop(errorCondition(sprintf(paste("Sampling weights in `%s` vary inside a unit. The pseudo likelihood", "weights the independent units (the `id` groups, or the rows of a", "single-level fit); a within-unit weight is not supported."), weights), class = "latents_bad_weights", call = NULL))
    }
    if (sum(unit) <= 0 || sum(unit > 0) < 2L) {
        stop(errorCondition(sprintf("Sampling weights in `%s` must be positive for at least two units.", weights), class = "latents_bad_weights", call = NULL))
    }
    stopifnot(`one weight per unit` = length(unit) == n_groups)
    relative <- unit/max(unit)
    relative * (n_groups/sum(relative))
}

