function(supplied, stored) {
    if (.multilpa_same_values(supplied, stored)) 
        return(TRUE)
    if (!is.numeric(supplied) || !is.numeric(stored) || length(supplied) != length(stored) || !identical(unname(is.na(supplied)), unname(is.na(stored)))) 
        return(FALSE)
    observed <- !is.na(stored)
    original <- as.numeric(stored[observed])
    encoded <- character()
    connection <- textConnection("encoded", "w", local = TRUE)
    tryCatch(utils::write.table(data.frame(value = original), connection, row.names = FALSE, col.names = FALSE, quote = FALSE), finally = close(connection))
    serialized <- as.numeric(encoded)
    if (anyDuplicated(serialized[!duplicated(original)])) 
        return(FALSE)
    identical(as.numeric(supplied[observed]), serialized)
}

function(candidate, reference) {
    stopifnot(is.list(candidate), is.list(reference))
    weights <- isTRUE(all.equal(candidate$weights, reference$weights, tolerance = 1e-12))
    indicators <- isTRUE(all.equal(candidate$indicators, reference$indicators, tolerance = 0))
    forward_matches <- function(centered, raw) {
        !is.null(centered$indicator_centers) && is.matrix(raw$indicators) && identical(dim(raw$indicators), dim(centered$centered_indicators)) && ncol(raw$indicators) == length(centered$indicator_centers) && isTRUE(all.equal(sweep(raw$indicators, 2L, centered$indicator_centers, "-"), centered$centered_indicators, tolerance = 0))
    }
    if (!indicators) {
        indicators <- forward_matches(candidate, reference) || forward_matches(reference, candidate)
    }
    candidate$weights <- NULL
    reference$weights <- NULL
    candidate[c("indicators", "indicator_centers", "centered_indicators")] <- NULL
    reference[c("indicators", "indicator_centers", "centered_indicators")] <- NULL
    weights && indicators && isTRUE(all.equal(candidate, reference, tolerance = 0))
}

function(spec, newdata) {
    random_terms <- spec$random_terms %||% stats::terms(stats::model.frame(spec$random, spec$model_data))
    xlevels <- spec$random_xlevels %||% stats::.getXlevels(random_terms, stats::model.frame(random_terms, spec$model_data))
    random_frame <- .mixture_prediction_data(stats::model.frame(random_terms, newdata, xlev = xlevels, na.action = stats::na.fail))
    design <- stats::model.matrix(random_terms, random_frame, contrasts.arg = attr(spec$random_design, "contrasts"))
    if (!identical(colnames(design), colnames(spec$random_design)) || any(!is.finite(design))) {
        stop(errorCondition(paste("The random-effects design of `newdata` must be finite and have the", "fitted columns."), class = "latents_bad_data", call = NULL))
    }
    design
}

