function(spec, newdata, with_response) {
    stopifnot(`\`newdata\` must be a data frame` = is.data.frame(newdata))
    model_terms <- if (with_response) 
        spec$terms
    else stats::delete.response(spec$terms)
    frame <- stats::model.frame(model_terms, newdata, xlev = spec$xlevels, na.action = stats::na.fail)
    full_design <- stats::model.matrix(model_terms, frame, contrasts.arg = spec$contrasts)
    new <- spec
    new$n <- nrow(newdata)
    new$x <- full_design[, colnames(spec$x), drop = FALSE]
    new$z <- full_design[, colnames(spec$z), drop = FALSE]
    new$offset <- as.numeric(stats::model.offset(frame) %||% rep(0, new$n))
    if (any(!is.finite(full_design)) || any(!is.finite(new$offset))) {
        stop(errorCondition("The evaluated regression design and offsets must be finite.", class = "latents_bad_data", call = NULL))
    }
    new$kept_rows <- seq_len(new$n)
    if (with_response) {
        response <- .mixture_response(stats::model.response(frame), spec$family, spec$category_levels)
        new$y <- response$y
        new$trials <- response$trials
        new$log_normalizer <- switch(spec$family, gaussian = rep(0, new$n), binomial = lchoose(response$trials, response$y), poisson = , negative_binomial = -lgamma(response$y + 1), ordinal = rep(0, new$n))
    }
    else {
        new$y <- rep(0, new$n)
        new$trials <- rep(1, new$n)
        new$log_normalizer <- rep(0, new$n)
    }
    new
}
